export class AppSettingsModel {
  ai_endpoint: string = '';
  version: string = '1.0.0';
  language_allowed: string = 'en';
  logo_url: string = '';
  logo_wide_light: string = '';
  logo_wide_dark: string = '';
  app_name: string = '';
  api_allowed: string = '0';

  constructor(data?: Partial<Record<keyof AppSettingsModel, string | boolean>>) {
    if (data) {
      this.ai_endpoint = (data.ai_endpoint as string) || this.ai_endpoint;
      this.version = (data.version as string) || this.version;
      this.language_allowed = (data.language_allowed as string) || this.language_allowed;
      this.logo_url = (data.logo_url as string) || this.logo_url;
      this.logo_wide_light = (data.logo_wide_light as string) || this.logo_wide_light;
      this.logo_wide_dark = (data.logo_wide_dark as string) || this.logo_wide_dark;
      this.api_allowed = (data.api_allowed as string) || this.api_allowed;
      this.app_name = (data.app_name as string) || this.app_name;
    }
  }
}

export class LocalSettingsModel {
  enable_advanced_tools: boolean = false;
  advance_setting_toggle: boolean = true;
  iocExpanded: boolean = true;
  entityfilterCategories: Record<string, string[]> = {};
  entityFilterCondition: boolean = true;
  isSidebarOpen: boolean = true;
  matchType: string = "";
  sortType: string = "";
}

export class ConfigSettings {
  appSettings: AppSettingsModel;
  localSettings: LocalSettingsModel;

  constructor(appSettings?: Partial<AppSettingsModel>, localSettings?: Partial<LocalSettingsModel>) {
    this.appSettings = Object.assign(new AppSettingsModel(), appSettings);
    this.localSettings = Object.assign(new LocalSettingsModel(), localSettings);
  }
}

import {Injectable} from '@angular/core';
import {HttpClient, HttpHeaders, HttpParams} from '@angular/common/http';
import {Observable} from 'rxjs';

@Injectable({providedIn: 'root'})
export class ApiService {
  private baseUrl = '/api';

  constructor(private http: HttpClient) {
  }

  get<T>(endpoint: string, options?: { params?: HttpParams; headers?: HttpHeaders }): Observable<T> {
    return this.http.get<T>(`${this.baseUrl}/${endpoint}`, options);
  }

  post<T>(endpoint: string, body: any, options?: { headers?: HttpHeaders }): Observable<T> {
    return this.http.post<T>(`${this.baseUrl}/${endpoint}`, body, options);
  }

  put<T>(endpoint: string, body: any, options?: { headers?: HttpHeaders }): Observable<T> {
    return this.http.put<T>(`${this.baseUrl}/${endpoint}`, body, options);
  }

  delete<T>(endpoint: string, options?: { headers?: HttpHeaders }): Observable<T> {
    return this.http.delete<T>(`${this.baseUrl}/${endpoint}`, options);
  }

}

import { effect, Injectable, WritableSignal } from '@angular/core';
import { AppSettingsModel, ConfigSettings, LocalSettingsModel } from '../../../shared/model/app/config';

@Injectable({
  providedIn: 'root'
})
export class AppStorageService {
  public readonly watchList: (keyof LocalSettingsModel)[] = [
    'enable_advanced_tools',
    'advance_setting_toggle',
    'iocExpanded',
    'entityFilterCondition',
    'entityfilterCategories',
    'isSidebarOpen',
    'matchType',
    'sortType'
  ];

  getFromStorage<T>(key: string, parseJson = false): T | undefined {
    const value = localStorage.getItem(key);
    if (value === null) return undefined;
    if (parseJson) return JSON.parse(value);
    if (value === 'true') return true as T;
    if (value === 'false') return false as T;
    return value as unknown as T;
  }

  getLocalSettings(): Partial<LocalSettingsModel> {
    return {
      enable_advanced_tools: this.getFromStorage<boolean>('enable_advanced_tools'),
      advance_setting_toggle: this.getFromStorage<boolean>('advance_setting_toggle') || true,
      iocExpanded: this.getFromStorage<boolean>('iocExpanded') || true,
      entityFilterCondition: this.getFromStorage<boolean>('entityFilterCondition') || true,
      entityfilterCategories: this.getFromStorage('entityfilterCategories', true) || {},
      isSidebarOpen: this.getFromStorage('isSidebarOpen', true),
      matchType: this.getFromStorage<string>('matchType') || 'or',
      sortType: this.getFromStorage<string>('sortType'),
    };
  }

  getStaticConfig(baseAppSettings: AppSettingsModel): ConfigSettings {
    const localSettings = this.getLocalSettings();
    const app: Partial<AppSettingsModel> = {
      version: baseAppSettings.version,
      language_allowed: baseAppSettings.language_allowed,
      logo_url: baseAppSettings.logo_url
    };
    return new ConfigSettings(app, localSettings);
  }

  setupWatcher(configData: WritableSignal<ConfigSettings>): void {
    effect(() => {
      const settings = configData().localSettings;
      this.watchList.forEach(key => {
        const value = settings[key];
        if (value !== undefined) {
          const storeValue =
            typeof value === 'boolean' ? String(value)
              : typeof value === 'object' ? JSON.stringify(value)
                : String(value);

          localStorage.setItem(key, storeValue);
        }
      });
    });
  }

  getTheme(): 'dark-theme' | 'light-theme' | undefined {
    const v = localStorage.getItem('theme') as 'dark-theme' | 'light-theme' | null;
    return v === 'dark-theme' || v === 'light-theme' ? v : undefined;
  }

  setTheme(theme: 'dark-theme' | 'light-theme'): void {
    localStorage.setItem('theme', theme);
  }

  clearStorage(): void {
    localStorage.clear();
  }
}

import { Injectable, signal } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AppSettingsModel, ConfigSettings, LocalSettingsModel } from '../../../shared/model/app/config';
import { AppStorageService } from './app-storage.service';
import { ApiService } from '../../../shared/services/api.service';
import { HttpClient } from '@angular/common/http';
import { tap } from 'rxjs/operators';
import { license_rules, search_filter_labels } from '../../../shared/constants/shared-enums';
import { userSessionData } from '../../../shared/model/company-profile/node.model';
import { TenantModel } from '../../../shared/model/tenant/tenant.model';
import { Title } from '@angular/platform-browser';
import { firstValueFrom } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class AppService {
  public configData = signal<ConfigSettings>(new ConfigSettings());
  public page = signal<number>(1);
  public entities = signal<any[]>([]);
  public worldJson = signal<any>(null);
  private entitiesCache: any[] | null = null;

  private createEmptyUserSessionData(): userSessionData {
    return {
      user: {
        email: '',
        twofa_enabled: false,
        username: '',
        role: '',
        status: '',
        subscription: false,
        verificationDate: '',
        license: []
      },
      tenant: {
        id: '',
        name: '',
        phone: '',
        isDefault: false,
        hasOnboarding: false,
        country: '',
        city: '',
        postalCode: '',
        taxId: '',
        userId: '',
        licenses: [],
        assignedQuota: '0',
        quotaExceeded: false
      },
      alerts: []
    };
  }

  public userSessionData = signal<userSessionData>(this.createEmptyUserSessionData());

  public tenantData = signal<TenantModel>({
    name: '',
    iocs: []
  });
  public userImageUrl = signal<string | null>(null);

  constructor(
    private title: Title,
    private apiService: ApiService,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    private appStorageService: AppStorageService,
    private http: HttpClient
  ) {
    this.loadEntities();
    this.loadLicenseRules();
    this.loadWorldJson();
    this.activatedRoute.queryParams.subscribe(params => {
      const pageParam = +params['page'];
      if (!isNaN(pageParam)) this.updatePage(pageParam);
    });

    this.loadStaticConfig();
    this.appStorageService.setupWatcher(this.configData);
  }

  async loadSession(forced = false): Promise<void> {
    let token = localStorage.getItem('token');
    if (token || forced) {
      try {
        const session = await firstValueFrom(this.apiService.post<userSessionData>('get/tenant/node', {}));
        if (session) this.userSessionData.set(session);
      } catch {
        this.userSessionData.set(this.createEmptyUserSessionData());
      }
    }
  }

  loadConfig(): void {
    this.apiService.get<any>('public').subscribe(response => {
      if (response?.settings) {
        const current = this.configData();
        this.configData.set(new ConfigSettings(response.settings, current.localSettings));
      }
    });
  }

  loadStaticConfig(): void {
    const current = this.configData();
    const newConfig = this.appStorageService.getStaticConfig(current.appSettings);
    this.configData.set(newConfig);
  }

  getConfig(): ConfigSettings {
    return this.configData();
  }

  set<T extends keyof (AppSettingsModel & LocalSettingsModel)>(key: T, value: (AppSettingsModel & LocalSettingsModel)[T]): void {
    this.configData.update(current => {
      const isAppSetting = key in current.appSettings;
      const updatedAppSettings = isAppSetting ? { ...current.appSettings, [key]: value } : current.appSettings;
      const updatedLocalSettings = !isAppSetting ? { ...current.localSettings, [key]: value } : current.localSettings;
      this.updateFavicon(current.appSettings.logo_url)
      return new ConfigSettings(updatedAppSettings, updatedLocalSettings);
    });
  }

  public updateFavicon(url: string = '/api/s/static/system/logo.png'): void {
    (document.querySelector<HTMLLinkElement>('link[rel="icon"]') ??
      document.head.appendChild(
        Object.assign(document.createElement('link'), { rel: 'icon' })
      )
    ).href = url;
  }

  updatePage(newPage: number): void {
    this.page.set(newPage);
    this.router
      .navigate([], {
        relativeTo: this.activatedRoute,
        queryParams: { ...this.activatedRoute.snapshot.queryParams, page: newPage },
        replaceUrl: true
      })
      .then();
  }

  loadEntities(): void {
    if (this.entitiesCache) {
      this.entities.set(this.entitiesCache);
      return;
    }

    this.http
      .get<any[]>('assets/data/entities_data/entities.json')
      .pipe(
        tap(data => {
          this.entitiesCache = data;
          this.entities.set(data);
          for (const e of data) {
            const key = `${e.key.replace(/[A-Z]/g, (c: string) => `_${c.toLowerCase()}`)}`;
            search_filter_labels[key] = e.title;
          }
        })
      )
      .subscribe();
  }

  loadLicenseRules(): void {
    this.http
      .get<any>('assets/data/licenses/license_rules.json')
      .pipe(
        tap(data => {
          for (const key in data) {
            license_rules[key] = data[key];
          }
        })
      )
      .subscribe();
  }
  loadWorldJson(): void {
    this.http
      .get<any>('assets/data/map/world.json')
      .pipe(
        tap(data => {
          this.worldJson.set(data);
        })
      )
      .subscribe();
  }

  clearAll(): void {
    this.appStorageService.clearStorage();
    this.configData.set(new ConfigSettings());
    this.userImageUrl.set(null);
    this.userSessionData.set(this.createEmptyUserSessionData());
  }

  isMobileMode(): boolean {
    return this.activatedRoute.snapshot.queryParamMap.get('mode') === 'free';
  }

  setOnboardingStatus(value: boolean) {
    this.userSessionData.update(state => {
      if (!state) return state;
      localStorage.setItem('onboarding', String(value));
      return {
        ...state,
        tenant: {
          ...state.tenant,
          hasOnboarding: value
        }
      };
    });
  }
}

import { Injectable } from '@angular/core';
import { interval, Observable, switchMap, tap, timer } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class TokenRefreshService {
  private refreshTokenSubscription: any;
  private readonly FIRST_REFRESH_DELAY = 5000;
  private readonly REFRESH_INTERVAL = 120000;

  startTokenRefresh(refreshAction: () => Observable<string | null>): void {
    if (!this.refreshTokenSubscription || this.refreshTokenSubscription.closed) {
      this.refreshTokenSubscription = timer(this.FIRST_REFRESH_DELAY)
        .pipe(
          switchMap(() => refreshAction()),
          tap({
            next: (_) => {
              return
            },
            error: () => {
              this.stopTokenRefresh();
            },
          }),
          switchMap(() => interval(this.REFRESH_INTERVAL).pipe(switchMap(() => refreshAction())))
        )
        .subscribe();
    }
  }


  stopTokenRefresh(): void {
    if (this.refreshTokenSubscription) {
      this.refreshTokenSubscription.unsubscribe();
      this.refreshTokenSubscription = null;
    }
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, map, Observable, tap } from 'rxjs';
import { ApiService } from '../../shared/services/api.service';
import { Router } from '@angular/router';
import { AuthModel } from '../../shared/model/auth/auth.model';
import { TokenRefreshService } from './token-refresh.service';
import { HttpHeaders } from '@angular/common/http';
import { AppStorageService } from '../core/app/app-storage.service';
import { AppService } from '../core/app/app.service';

@Injectable({ providedIn: 'root' })
export class AuthService {
  private authState = new BehaviorSubject<AuthModel>(this.loadAuthState());

  constructor(
    private appService: AppService,
    private appStorageService: AppStorageService,
    private apiService: ApiService,
    private router: Router,
    private tokenRefreshService: TokenRefreshService
  ) {
    if (this.isAuthenticated()) {
      const needsSession =
        !this.appService.userSessionData().user.username &&
        !this.appService.userSessionData().user.role &&
        !this.appService.userSessionData().user.verificationDate;

      if (needsSession) this.refreshToken().subscribe();
      this.startTokenRefresh();
    }
  }

  get authState$(): Observable<AuthModel> {
    return this.authState.asObservable();
  }

  login(mail: string, password: string, isDemo: boolean = false): Observable<any> {
    if (this.appService.isMobileMode()) {
      localStorage.setItem('mobileDemo', 'true');
    }

    const body = new URLSearchParams();
    const headers = new HttpHeaders({ 'Content-Type': 'application/x-www-form-urlencoded' });
    let route = 'token';

    if (isDemo) {
      route = 'token/demo';
    } else {
      body.set('username', mail);
      body.set('password', password);
    }

    return this.apiService.post<any>(route, body.toString(), { headers }).pipe(
      tap({
        next: (response) => {
          if (response.twofa_required) {
            this.denyAccess('2FA required');
            return response.provisioning_uri || null;
          }

          if (!this.applyLoginResponse(response)) return;

          this.appService.loadSession(true).then(() => {
          });
        },
        error: (error) => {
          if (error?.error?.detail === 'Verification pending.') {
            this.authState.next({
              token: null,
              isAuthenticated: false,
              isValidated: false,
              error: 'Access denied!',
            });
          } else {
            this.denyAccess('Access denied!');
          }
        },
      })
    );
  }

  verifyTwofa(code: string, tempToken: string, username: string): Observable<any> {
    if (!tempToken)
      return new Observable((observer) => {
        observer.next(null);
        observer.complete();
      });

    const headers = new HttpHeaders({
      'Content-Type': 'application/json',
      Authorization: `Bearer ${tempToken}`,
    });

    return this.apiService.post<any>('token/2fa/verify', { code }, { headers }).pipe(
      tap({
        next: (response) => {
          if (!this.applyLoginResponse(response, 'Invalid 2FA code')) return;
        },
        error: () => {
          this.denyAccess('Invalid 2FA code');
        },
      })
    );
  }

  logout(): void {
    this.authState.next({
      token: null,
      isAuthenticated: false,
      isValidated: true,
      error: null,
    });

    this.router.navigate(['/login']).then(() => {
      this.apiService.post('logout', {}).subscribe();

      localStorage.clear();
      sessionStorage.clear();
      this.tokenRefreshService.stopTokenRefresh();
      localStorage.setItem('onboarding', String(false));
      this.appStorageService.clearStorage();
      this.appService.clearAll();
      this.appService.loadConfig();
    });
  }

  demoLogin(): void {
    this.login('_', '_', true).subscribe(async (_) => {});
  }

  signup(username: string, email: string, password: string): Observable<any> {
    return this.apiService.post('signup', { username, email, password });
  }

  signup_verification(mail: string, password: string): Observable<any> {
    return this.apiService.post('signup/verificaion', { username: mail, password });
  }

  forgotPassword(email: string): Observable<any> {
    return this.apiService.post('forgot', { email });
  }

  updatePassword(token: string, password: string): Observable<any> {
    return this.apiService.post('updatePassword', { token, password });
  }

  getIsMobileDemo(): boolean {
    return localStorage.getItem('mobileDemo') === 'true';
  }

  isAuthenticated(): boolean {
    return !!this.getStoredToken();
  }

  getSessionStatus(): { isAuthenticated: boolean; hasSession: boolean } {
    const isAuthenticated = !!this.getStoredToken();
    const hasSession =
      !!this.appService.userSessionData().user.username &&
      !!this.appService.userSessionData().user.role &&
      !!this.appService.userSessionData().user.verificationDate;
    return { isAuthenticated, hasSession };
  }

  private denyAccess(error: string): void {
    this.authState.next({
      token: null,
      isAuthenticated: false,
      isValidated: true,
      error,
    });
  }

  private setToken(token: string): void {
    localStorage.setItem('token', token);
    this.authState.next({
      token,
      isAuthenticated: true,
      isValidated: true,
      error: null,
    });
  }

  public getStoredToken(): string | null {
    return localStorage.getItem('token');
  }

  private loadAuthState(): AuthModel {
    const token = this.getStoredToken();
    return {
      token,
      isValidated: true,
      isAuthenticated: !!token,
      error: null,
    };
  }

  private startTokenRefresh(): void {
    if (this.isAuthenticated()) this.tokenRefreshService.startTokenRefresh(() => this.refreshToken());
  }

  refreshToken(): Observable<string | null> {
    const currentToken = this.getStoredToken();
    if (!currentToken)
      return new Observable((observer) => {
        observer.next(null);
        observer.complete();
      });

    return this.apiService
      .post<{ access_token: string; session?: any }>(
        'token/refresh',
        { token: currentToken },
        { headers: new HttpHeaders({ Authorization: `Bearer ${currentToken}` }) }
      )
      .pipe(
        tap((response) => {
          if (response?.access_token) this.setToken(response.access_token);
        }),
        map((response) => response?.access_token || null)
      );
  }

  private applyLoginResponse(response: any, deniedMessage: string = 'Access denied!'): boolean {
    if (!response?.access_token) {
      this.denyAccess(deniedMessage);
      return false;
    }

    const sessionData = response?.session || {};
    if (sessionData?.role === 'crawler') {
      this.denyAccess(deniedMessage);
      return false;
    }

    this.setToken(response.access_token);
    this.startTokenRefresh();
    return true;
  }

  private toBool(v: any): boolean {
    if (typeof v === 'boolean') return v;
    if (typeof v === 'string') return v === 'true';
    return !!v;
  }
}

import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivate, Router, RouterStateSnapshot } from '@angular/router';
import { AuthService } from '../../services/authetication/auth.service';
import { AppService } from '../../services/core/app/app.service';

@Injectable({ providedIn: 'root' })
export class AuthGuard implements CanActivate {
  constructor(private authService: AuthService, private router: Router, private appService: AppService) {}

  canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
    if (this.authService.getIsMobileDemo() && state.url !== '/dashboard/strategic/all') {
      this.router.navigate(['/dashboard/strategic/all']).then();
      return false;
    }

    if (!this.authService.isAuthenticated()) {
      this.router.navigate(['/login'], { queryParams: { redirect: state.url } }).then();
      return false;
    }

    return true;
  }
}

import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, Resolve, RouterStateSnapshot } from '@angular/router';
import { Observable } from 'rxjs';
import { shareReplay } from 'rxjs/operators';
import { ApiService } from '../services/api.service';
import { InsightCallbackModel } from '../model/homepage/stats_insight.model';

@Injectable({ providedIn: 'root' })
export class InsightResolver implements Resolve<InsightCallbackModel> {
  private cache$?: Observable<InsightCallbackModel>;

  constructor(private apiService: ApiService) {}

  resolve(_route: ActivatedRouteSnapshot, _state: RouterStateSnapshot): Observable<InsightCallbackModel> {
    if (!this.cache$) {
      this.cache$ = this.apiService.get<InsightCallbackModel>('insight').pipe(shareReplay(1));
    }
    return this.cache$;
  }
}

import {Injectable} from '@angular/core';
import {ActivatedRouteSnapshot, Resolve, Router, RouterStateSnapshot} from '@angular/router';
import {Observable, of} from 'rxjs';
import {catchError} from 'rxjs/operators';
import {ApiService} from '../services/api.service';

@Injectable({
  providedIn: 'root'
})
export class ReportResolver implements Resolve<any> {
  constructor(private apiService: ApiService, private router: Router) {
  }

  resolve(route: ActivatedRouteSnapshot, _state: RouterStateSnapshot): Observable<any> {
    let category_1 = route.parent?.url[0]?.path || '';
    const category_2 = route.url[0]?.path || '';
    const hash = route.paramMap.get('m_hash');
    const lang = route.queryParamMap.get('lang');

    let apiUrl = '';
    switch (category_1) {
      case 'breach':
        apiUrl = hash ? `search/breach/${hash}` : `search/breach`;
        break;
      case 'strategic':
        apiUrl = hash ? `search/strategic/${hash}` : `search/strategic`;
        break;
      case 'defacement':
        apiUrl = hash ? `search/defacement/${hash}` : `search/defacement`;
        break;
      case 'exploit':
        apiUrl = hash ? `search/exploit/${hash}` : `search/exploit`;
        break;
      case 'social':
        if (category_2 == "all"){
          if(apiUrl.includes("chat")){
            apiUrl = `search/chat/${hash}`;
          }else {
            apiUrl = hash ? `search/social/${hash}` : `search/social`;
          }
        }
        else if (category_2 == "twitter" || category_2 == "reddit" || category_2 == "forum" || category_2 == "pastebin" || category_2 == "mastodon"){
          apiUrl = hash ? `search/social/${hash}` : `search/social`;
        }
        else{
          apiUrl = hash ? `search/chat/${hash}` : `search/chat`;
        }
        break;
      case 'feed':
        apiUrl = hash ? `search/news/${hash}` : `search/news`;
        break;
      default:
        this.router.navigate(['/']).then();
        return of(null);
    }

    if (lang) {
      apiUrl += `?lang=${lang}`;
    }

    return this.apiService.get<any>(apiUrl).pipe(
      catchError((_) => {
        this.router.navigate(['/']).then();
        return of(null);
      })
    );
  }
}

import { Directive, ElementRef, HostListener, Input, OnDestroy, AfterViewInit, Renderer2, NgZone } from '@angular/core';

@Directive({
  selector: '[appTooltip]'
})
export class TooltipDirective implements AfterViewInit, OnDestroy {
  @Input('appTooltip') tooltipText = '';
  private tooltip: HTMLElement | null = null;
  private showTimeout: any = null;
  private removeContainerScroll?: () => void;
  private rafHideScheduled = false;

  constructor(private el: ElementRef, private renderer: Renderer2, private zone: NgZone) { }

  ngAfterViewInit(): void {
    const container = document.getElementById('dashboard-container');
    if (container) {
      this.zone.runOutsideAngular(() => {
        this.removeContainerScroll = this.renderer.listen(container, 'scroll', () => this.scheduleHide());
      });
    }
  }

  @HostListener('window:scroll', ['$event'])
  onWindowScroll(): void {
    this.scheduleHide();
  }

  @HostListener('mouseenter')
  onMouseEnter(): void {
    if (this.tooltipText.trim()) {
      this.showTimeout = setTimeout(() => {
        this.createOrUpdateTooltip();
      }, 300);
    }
  }

  @HostListener('mouseleave')
  onMouseLeave(): void {
    this.hideNow();
  }

  ngOnDestroy(): void {
    if (this.removeContainerScroll) {
      this.removeContainerScroll();
      this.removeContainerScroll = undefined;
    }
    this.destroyTooltip();
    if (this.showTimeout) {
      clearTimeout(this.showTimeout);
      this.showTimeout = null;
    }
  }

  private scheduleHide(): void {
    if (!this.tooltip || this.rafHideScheduled) return;
    this.rafHideScheduled = true;
    requestAnimationFrame(() => {
      this.hideNow();
      this.rafHideScheduled = false;
    });
  }

  private hideNow(): void {
    if (this.showTimeout) {
      clearTimeout(this.showTimeout);
      this.showTimeout = null;
    }
    if (this.tooltip) {
      this.renderer.setStyle(this.tooltip, 'opacity', '0');
      this.renderer.setStyle(this.tooltip, 'pointer-events', 'none');
      this.renderer.setStyle(this.tooltip, 'display', 'none');
    }
  }

  private createOrUpdateTooltip(): void {
    if (!this.tooltip) {
      this.tooltip = this.renderer.createElement('div');
      this.renderer.addClass(this.tooltip, 'custom-tooltip');
      this.renderer.setStyle(this.tooltip, 'position', 'fixed');
      this.renderer.setStyle(this.tooltip, 'opacity', '0');
      this.renderer.setStyle(this.tooltip, 'text-transform', 'capitalize');
      this.renderer.setStyle(this.tooltip, 'pointer-events', 'none');
      this.renderer.appendChild(document.body, this.tooltip);
    } else {
      this.renderer.setProperty(this.tooltip, 'textContent', '');
    }

    const textNode = this.renderer.createText(this.tooltipText);
    this.renderer.appendChild(this.tooltip, textNode);
    this.renderer.setStyle(this.tooltip, 'display', 'block');

    requestAnimationFrame(() => {
      if (!this.tooltip) return;

      const hostRect = (this.el.nativeElement as HTMLElement).getBoundingClientRect();
      const tooltipRect = this.tooltip.getBoundingClientRect();
      const margin = 8;

      let top = hostRect.top - tooltipRect.height - margin;
      let left = hostRect.left + (hostRect.width - tooltipRect.width) / 2;

      const isTopOverflow = top < margin;
      const isLeftOverflow = left < margin;
      const isRightOverflow = left + tooltipRect.width > window.innerWidth - margin;

      if (isTopOverflow && isLeftOverflow) {
        top = hostRect.top + (hostRect.height - tooltipRect.height) / 2;
        left = hostRect.right + margin;
      } else if (isTopOverflow && isRightOverflow) {
        top = hostRect.top + (hostRect.height - tooltipRect.height) / 2;
        left = hostRect.left - tooltipRect.width - margin;
      } else if (isTopOverflow) {
        top = hostRect.bottom + margin;
      }

      if (left < margin) left = margin;
      else if (left + tooltipRect.width > window.innerWidth - margin) {
        left = window.innerWidth - tooltipRect.width - margin;
      }

      if (top < margin) top = margin;
      else if (top + tooltipRect.height > window.innerHeight - margin) {
        top = window.innerHeight - tooltipRect.height - margin;
      }

      this.tooltip.style.top = `${top}px`;
      this.tooltip.style.left = `${left}px`;
      this.tooltip.style.opacity = '1';
    });
  }

  private destroyTooltip(): void {
    if (this.tooltip) {
      const t = this.tooltip;
      this.tooltip = null;
      if (document.body.contains(t)) {
        this.renderer.removeChild(document.body, t);
      }
    }
  }
}

