import { Component, OnInit } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ProfileComponent } from '../../profile/profile.component';
import { NavigationEnd, Router, UrlTree } from '@angular/router';
import { filter } from 'rxjs';
import { NgForOf, NgIf, NgOptimizedImage, TitleCasePipe } from '@angular/common';
import { AppService } from '../../../../services/core/app/app.service';
import { AuthService } from '../../../../services/authetication/auth.service';

@Component({
  selector: 'app-dashboard-header',
  standalone: true,
  imports: [FormsModule, ProfileComponent, NgIf, NgForOf, TitleCasePipe, NgOptimizedImage],
  templateUrl: './dashboard-header.component.html',
})
export class DashboardHeaderComponent implements OnInit {
  breadcrumb: { path: string; label: string }[] = [];


  constructor(public authService: AuthService, private router: Router, protected appService: AppService) {
  }

  ngOnInit() {
    this.updateBreadcrumb(this.router.url);

    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: NavigationEnd) => {
        this.updateBreadcrumb(event.urlAfterRedirects);
      });
  }

  updateBreadcrumb(url: string) {
    const urlTree: UrlTree = this.router.parseUrl(url);
    const segments = urlTree.root.children['primary']?.segments.map((segment) => segment.path) ?? [];
    this.breadcrumb = segments.length > 1
      ? segments.slice(1).map((segment) => ({ path: segment, label: segment }))
      : segments.map((segment) => ({ path: segment, label: segment }));
  }

  goBack() {
    const currentUrlTree: UrlTree = this.router.parseUrl(this.router.url);
    const queryParams = currentUrlTree.queryParams;

    if (this.router.url.includes('profile/consolidated/all') || this.router.url.includes('profile/alerts')) {
      this.router.navigate(['/dashboard/profile/homepage'], { queryParams }).then();
      return;
    }
    if (this.router.url.includes('/profile/consolidated') || this.router.url.includes('/profile/alerts')) {
      this.router.navigate(['/dashboard/profile/consolidated/all'], { queryParams }).then();
      return;
    }
    if (this.router.url.includes('/consolidated')) {
      this.router.navigate(['/dashboard/consolidated/all'], { queryParams }).then();
      return;
    }
    if (this.router.url.includes('/social/chat/all')) {
      this.router.navigate(['/dashboard/social/all'], { queryParams }).then();
      return;
    }
    if (this.breadcrumb[0].label == 'ctigraph') {
      this.router.navigate(['/dashboard'], { queryParams }).then();
      return;
    }
    if (this.breadcrumb.length > 2) {
      const secondLastPath = '/dashboard/' + this.breadcrumb.slice(0, -1).map(crumb => crumb.path).join('/');
      const secondLastUrlTree = this.router.createUrlTree([secondLastPath], { queryParams });
      const secondLastUrl = this.router.serializeUrl(secondLastUrlTree);
      this.router.navigateByUrl(secondLastUrl).then();
    }
  }

  navigateToCrumb(index: number) {
    if (this.breadcrumb.length > 2) {
      const currentUrlTree: UrlTree = this.router.parseUrl(this.router.url);
      const queryParams = currentUrlTree.queryParams;

      const basePath = '/dashboard/' + this.breadcrumb.slice(0, index + 1).map((crumb) => crumb.path).join('/');
      const fullPathTree: UrlTree = this.router.createUrlTree([basePath], { queryParams });
      const fullPath = this.router.serializeUrl(fullPathTree);

      this.router.navigateByUrl(fullPath).then();
    }
  }
}

import { Component, OnDestroy, OnInit } from '@angular/core';
import { CommonModule, NgIf } from '@angular/common';
import { FormsModule, NgForm } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { AuthService } from '../../../services/authetication/auth.service';
import { Subscription } from 'rxjs';
import { AppService } from '../../../services/core/app/app.service';

import QRCode from 'qrcode';
import { DashboardHeaderComponent } from '../../../shared/partials/header/dashboard-header/dashboard-header.component';

@Component({
  selector: 'app-login-container',
  standalone: true,
  imports: [FormsModule, NgIf, CommonModule, DashboardHeaderComponent],
  templateUrl: './login-container.component.html',
})
export class LoginContainerComponent implements OnInit, OnDestroy {
  user = { mail: '', password: '' };
  errorMessage: string | null = null;
  authenticated = true;
  copied = false;
  private authSubscription!: Subscription;

  twofaRequired = false;
  otpCode = '';
  otpUri: string | null = null;
  otpDataUrl: string | null = null;
  otpSecret: string | null = null;

  private tempToken: string | null = null;
  private pendingUsername: string | null = null;
  isMobile = false;

  constructor(
    public authService: AuthService,
    private router: Router,
    protected appService: AppService,
    private route: ActivatedRoute
  ) {}

  ngOnInit() {
    this.authSubscription = this.authService.authState$.subscribe(authState => {
      if (authState.isAuthenticated) {
        this.appService.loadSession(true).then(() => {
          this.router.navigate(['dashboard'], { replaceUrl: true }).then();
        });
      } else {
        this.authenticated = false;
      }
    });

    this.route.queryParams.subscribe(params => {
      const isScreenMobile = window.innerWidth <= 480;
      this.isMobile = isScreenMobile;
      let mode = params['mode'];
      if (!mode && params['redirect']) {
        const tree = this.router.parseUrl(params['redirect']);
        mode = tree.queryParams['mode'];
      }
      if (mode === 'free') {
        this.demoLogin();
      }
    });
  }

  copyToClipboard(text: string): void {
    navigator.clipboard.writeText(text).then(() => {
      this.copied = true;
    });
  }

  async onSubmit(form: NgForm) {
    this.errorMessage = null;
    if (!form.valid) return;

    this.authService.login(this.user.mail, this.user.password).subscribe({
      next: async res => {
        if (res?.twofa_required) {
          this.twofaRequired = true;
          this.pendingUsername = res.username;
          this.tempToken = res.temp_token || null;
          this.otpUri = res.provisioning_uri || null;
          this.otpSecret = res.twofa_secret || null;
          this.otpDataUrl = this.otpUri ? await QRCode.toDataURL(this.otpUri) : null;
        }
      },
      error: err => {
        this.errorMessage = err?.error?.detail || err?.message || 'Login failed';
      }
    });
  }

  submitOtp() {
    this.errorMessage = null;

    if (!this.tempToken || !this.pendingUsername) return;

    this.authService
      .verifyTwofa(this.otpCode, this.tempToken, this.pendingUsername)
      .subscribe({
        next: () => {
          if (!this.authService.isAuthenticated()) return;
          // keep 2FA UI state intact to avoid flicker before redirect
        },
        error: (err) => {
          this.errorMessage =
            err?.error?.detail ||
            err?.message ||
            'Login failed';
        }
      });
  }

  goToSignUp() {
    this.router.navigate(['/signup']).then();
  }

  goToForgot() {
    this.router.navigate(['/reset']).then();
  }

  ngOnDestroy() {
    if (this.authSubscription) this.authSubscription.unsubscribe();
  }

  demoLogin() {
    this.authService.demoLogin();
  }

  resendMail() {
    this.authService.signup_verification(this.user.mail, this.user.password).subscribe({
      next: () => this.router.navigate(['/welcome']),
      error: (err) => {
        const vErr = err?.error?.validation_errors?.[0];
        this.errorMessage = vErr?.message || err?.error?.detail || 'Signup failed';
      }
    });
  }
}
