import { Injectable } from '@angular/core';
import { LicenseService } from '../../services/licenses/licenses.service';
import { DashboardService } from '../../services/dashboard/dashboard.service';

@Injectable({
  providedIn: 'root'
})
export class ScrollService {

  constructor(protected licenseService: LicenseService, protected dashboardService: DashboardService) {
    this.resetOnReload();
  }

  public resetOnReload(ingore = false): void {
    const navEntries = performance.getEntriesByType?.('navigation') as PerformanceNavigationTiming[];
    const isHardReload = navEntries?.[0]?.type === 'reload';

    if (isHardReload || ingore) {
      sessionStorage.setItem('scrollPosition', '0');
      sessionStorage.setItem('selectedItem', '');
      window.scrollTo(0, 0);
    }
  }

  saveSession(itemId: string): void {
  }

  openCTI(event: MouseEvent, itemId: string): void {
    if (!this.licenseService.canUseCtiGraph()) {
      this.dashboardService.showSubscription.set(true);
      return
    }
    event.stopPropagation()
    if (itemId) {
      const baseUrl = `${window.location.origin}/dashboard/ctigraph`;
      const params = new URLSearchParams({
        selectedType: 'document', singleInput: itemId
      });

      const fullUrl = `${baseUrl}?${params.toString()}`;
      window.open(fullUrl, '_blank');
    }
  }

  scrollToSavedPosition(): void {
    const savedPosition = sessionStorage.getItem('scrollPosition');
    const savedItemId = sessionStorage.getItem('selectedItem');

    if (savedPosition !== null && savedItemId) {
      const position = parseInt(savedPosition, 10);
      let scrollableContainer: HTMLElement | null = document.getElementById('item-' + savedItemId);
      while (scrollableContainer && !this.isScrollable(scrollableContainer)) {
        scrollableContainer = scrollableContainer.parentElement;
      }
      if (scrollableContainer) {
        scrollableContainer.scrollTop = position;
      } else {
        window.scrollTo({ top: position, behavior: 'auto' });
      }
    }
  }
  private isScrollable(element: HTMLElement): boolean {
    const style = window.getComputedStyle(element);
    const overflowY = style.overflowY;
    return (overflowY === 'auto' || overflowY === 'scroll') && element.scrollHeight > element.clientHeight;
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import { ScrollService } from '../../shared/services/scroll.service';

@Injectable({
  providedIn: 'root'
})
export class SelectionStoreService {
  private selectedSectionSubject = new BehaviorSubject<string | null>(null);
  private selectedOptionSubject = new BehaviorSubject<string | null>(null);

  selectedSection$ = this.selectedSectionSubject.asObservable();
  selectedOption$ = this.selectedOptionSubject.asObservable();

  first_trigger = true

  constructor(private router: Router, private scroll_service: ScrollService) {
    this.setInitialSelectionFromUrl(this.router.url);

    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: NavigationEnd) => {
        if (event.url.startsWith('/dashboard')) {
          this.setInitialSelectionFromUrl(event.url);
        } else {
          this.resetSelection();
        }
      });
  }

  private setInitialSelectionFromUrl(url: string) {
    const pathOnly = url.split('?')[0].split('#')[0];
    const match = pathOnly.match(/^\/dashboard\/([^\/]+)(?:\/([^\/]+))?(?:\/([^\/]+))?$/);

    if (match) {
      let section = match[1];
      let option = match[2];

      const currentSection = this.getSelectedSection();
      const currentOption = this.selectedOptionSubject.value;

      const shouldRedirectToHome =
        !this.first_trigger &&
        (!currentSection && !currentOption);

      this.first_trigger = false;

      if ((!option && section !== 'home' && section !== 'directory') || (currentSection === section && currentOption === option)) {
        return;
      }
      if (this.router.url.includes('/profile/consolidated') || this.router.url.includes('/profile/alerts') || this.router.url.includes('/profile/addCustomAlert')) {
        this.setSelectedOption('Dashboard');
        return;
      }

      if (shouldRedirectToHome && this.router.url !== '/dashboard/home') {
        this.router.navigate(['/dashboard', 'home'], {
          replaceUrl: true,
          queryParams: {},
          queryParamsHandling: '',
        }).then();
        this.scroll_service.resetOnReload(true)
        return;
      }

      const capitalizedSection = section.charAt(0).toUpperCase() + section.slice(1);
      this.setSelectedSection(capitalizedSection);

      if(this.router.url.includes('profile') && option=="homepage"){
        option="Homepage"
      }

      if (option) {
        const capitalizedOption = option.charAt(0).toUpperCase() + option.slice(1);
        this.setSelectedOption(capitalizedOption);
      } else {
        this.setSelectedOption('');
      }
    }
  }


  setSelectedSection(section: string) {
    this.selectedSectionSubject.next(section);
    this.selectedOptionSubject.next(null);
    localStorage.setItem('selectedSection', section);
  }

  setSelectedOption(option: string) {
    this.selectedOptionSubject.next(option);
    localStorage.setItem('selectedOption', option);
  }

  getSelectedSection(): string | null {
    return this.selectedSectionSubject.value;
  }

  private resetSelection() {
    this.selectedSectionSubject.next(null);
    this.selectedOptionSubject.next(null);
    localStorage.removeItem('selectedSection');
    localStorage.removeItem('selectedOption');
  }
}

