export const searchFilterAnimation =
    trigger('searchFilterAnimation', [
        transition(':enter', [
            style({ opacity: 0, transform: 'translateY(-10px)' }),
            animate('250ms ease-out', style({ opacity: 1, transform: 'translateY(0)' }))
