import { Component, ElementRef, ViewChild, AfterViewInit, OnChanges, SimpleChanges, HostListener, OnInit, OnDestroy } from '@angular/core';
import { NgIf } from '@angular/common';
import * as d3 from 'd3';
import * as topojson from 'topojson-client';
import { ActivatedRoute } from '@angular/router';
import { HeatmapReportComponent } from './heatmap-report/heatmap-report.component';
import { AppService } from '../../../services/core/app/app.service';

type CountryData = { id: string; name: string; value: number };

@Component({
  selector: 'app-world-heatmap',
  imports: [NgIf, HeatmapReportComponent],
  standalone: true,
  templateUrl: './world-heatmap.component.html'
})
export class WorldHeatmapComponent
  implements AfterViewInit, OnChanges, OnInit, OnDestroy {

  @ViewChild('mapContainer') private chartContainer!: ElementRef;

  public activeCountryReports: any;
  private allCategoryReports: any;
  public activeCategoryKey: string | null = null;
  private rotationTimer: any;
  public selectedCountryReports: any;
  public mapData: CountryData[] = [];
  public isOpenCountryReport = false;

  private svg!: d3.Selection<SVGSVGElement, unknown, null, undefined>;
  private mapG!: d3.Selection<SVGGElement, unknown, null, undefined>;
  private projection!: d3.GeoProjection;
  private path!: d3.GeoPath<any, d3.GeoPermissibleObjects>;
  private tooltip!: d3.Selection<HTMLDivElement, unknown, null, undefined>;
  private worldData: any;
  private categoryOrder = [
    'leak',
    'generic',
    'exploit',
    'chat',
    'social',
    'defacement'
  ];

  private valueByName = new Map<string, number>();
  private selectedName: string | null = null;

  private neutralFill = 'rgba(23,34,53,0.45)';

  constructor(
    private route: ActivatedRoute,
    private appService: AppService
  ) {
  }

  ngOnInit(): void {
    const data = this.route.snapshot.data['insights'];
    this.allCategoryReports = data.country_insight;
    this.activeCategoryKey = null;
    this.buildIndex();
  }

  ngAfterViewInit(): void {
    this.createChart();
    this.startCategoryRotation();

  }

  ngOnDestroy(): void {
    this.tooltip?.remove();
    if (this.rotationTimer) {
      clearInterval(this.rotationTimer);
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['data'] && !changes['data'].firstChange) {
      this.buildIndex();
      this.updateColors();
      this.updateLegend();
      this.updateActiveCategoryLabel();
    }
  }

  @HostListener('window:resize')
  onResize(): void {
    this.createChart();
  }
  private getAvailableCategories(): string[] {
    return this.categoryOrder.filter(cat =>
      this.allCategoryReports?.[cat] &&
      this.allCategoryReports[cat].length > 0
    );
  }

  private buildIndex(): void {
    this.valueByName.clear();
    for (const d of this.mapData) {
      const key = d.name?.toLowerCase().trim();
      if (key) this.valueByName.set(key, d.value);
    }
  }
  private startCategoryRotation(): void {
    const available = this.getAvailableCategories();
    if (!available.length) return;

    let index = 0;

    const switchCategory = () => {
      this.activeCategoryKey = available[index];
      this.activeCountryReports = this.allCategoryReports[this.activeCategoryKey];

      this.mapData = this.gettingUniqueCountrys();
      this.buildIndex();
      this.animateMapTransition();
      this.updateLegend();
      this.updateActiveCategoryLabel();

      index = (index + 1) % available.length;
    };

    switchCategory();

    this.rotationTimer = setInterval(() => {
      switchCategory();
    }, 8000);
  }

  private ensureLegendDefs(): void {
    const defs = this.svg.select('defs').empty()
      ? this.svg.append('defs')
      : this.svg.select('defs');

    defs.select('#legend-gradient').remove();
    const grad = defs.append('linearGradient')
      .attr('id', 'legend-gradient')
      .attr('x1', '0%')
      .attr('y1', '0%')
      .attr('x2', '100%')
      .attr('y2', '0%');

    const stops = [
      { offset: '0%', color: '#4a2530' },
      { offset: '25%', color: '#682636' },
      { offset: '50%', color: '#8a273d' },
      { offset: '75%', color: '#b22945' },
      { offset: '100%', color: '#df2d4f' },
    ];

    for (const stop of stops) {
      grad.append('stop')
        .attr('offset', stop.offset)
        .attr('stop-color', stop.color);
    }
  }

  private updateLegend(): void {
    const el = this.chartContainer.nativeElement as HTMLElement;
    const width = el.offsetWidth || 800;
    const height = Math.round(width * 0.52);

    this.ensureLegendDefs();

    const values = this.mapData.map(d => d.value).filter(v => v != null);
    const max = Math.max(...values, 1);

    const legend = this.svg.selectAll<SVGGElement, any>('g.legend').data([0]).join('g').attr('class', 'legend');

    const pad = 14;
    const barW = 180;
    const barH = 10;

    legend.attr('transform', `translate(${width - pad - barW - 25},${pad + 6})`);

    const title = legend.selectAll<SVGTextElement, any>('text.legend-title')
      .data([this.activeCategoryKey])
      .join('text')
      .attr('class', 'legend-title')
      .attr('x', 0)
      .attr('y', 0);

    title
      .transition()
      .duration(400)
      .attr('opacity', 0)
      .transition()
      .duration(400)
      .attr('opacity', 1)
      .text(d => d?.toUpperCase() ?? '');

    legend.selectAll<SVGRectElement, any>('rect.legend-bar')
      .data([0])
      .join('rect')
      .attr('class', 'legend-bar')
      .attr('x', 0)
      .attr('y', 8)
      .attr('width', barW)
      .attr('height', barH)
      .attr('rx', 4)
      .attr('ry', 4)
      .attr('fill', 'url(#legend-gradient)');

    const ticks = [0, Math.round(max * 0.33), Math.round(max * 0.66), max];

    const tickSelection = legend
      .selectAll<SVGLineElement, number>('line.legend-tick')
      .data(ticks);

    tickSelection.join(
      enter => enter.append('line')
        .attr('class', 'legend-tick')
        .attr('y1', 8 + barH)
        .attr('y2', 8 + barH + 6)
        .attr('x1', 0)
        .attr('x2', 0)
        .transition()
        .duration(600)
        .attr('x1', d => (d / max) * barW)
        .attr('x2', d => (d / max) * barW),

      update => update
        .transition()
        .duration(600)
        .attr('x1', d => (d / max) * barW)
        .attr('x2', d => (d / max) * barW),

      exit => exit.remove()
    );

    legend.selectAll<SVGTextElement, number>('text.legend-tick-label')
      .data(ticks)
      .join(
        enter => enter.append('text')
          .attr('class', 'legend-tick-label')
          .attr('y', 8 + barH + 18)
          .attr('text-anchor', 'middle')
          .attr('opacity', 0)
          .transition()
          .duration(600)
          .attr('opacity', 1)
          .attr('x', d => (d / max) * barW)
          .text(d => String(d)),

        update => update
          .transition()
          .duration(600)
          .attr('x', d => (d / max) * barW)
          .text(d => String(d)),

        exit => exit.remove()
      );
  }

  private updateActiveCategoryLabel(): void {
    const labelG = this.svg.selectAll<SVGGElement, any>('g.map-type').data([0]).join('g').attr('class', 'map-type');
    labelG.attr('transform', `translate(${33},${28})`).attr('pointer-events', 'none');
    labelG.selectAll<SVGTextElement, any>('text.map-type-text')
      .data([this.activeCategoryKey])
      .join('text')
      .attr('class', 'map-type-text')
      .attr('x', 0)
      .attr('y', 0)
      .attr('dominant-baseline', 'middle')
      .attr('font-size', 14)
      .attr('font-weight', 700)
      .attr('letter-spacing', 0.8)
      .attr('fill', '#ffe4e6')
      .text(d => `HEATMAP: ${(d ?? '').toUpperCase()}`);
  }

  private createChart(): void {
    this.worldData = this.appService.worldJson();
    if (!this.worldData) return;

    const el = this.chartContainer.nativeElement as HTMLElement;
    const width = el.offsetWidth || 800;
    const height = Math.round(width * 0.52);

    d3.select(el).selectAll('*').remove();

    this.tooltip = d3
      .select(el)
      .append<HTMLDivElement>('div')
      .attr('class', 'heatmap-tooltip');

    this.svg = d3
      .select(el)
      .append('svg')
      .attr('viewBox', `0 0 ${width} ${height}`);

    this.mapG = this.svg.append('g');

    this.projection = d3
      .geoMercator()
      .scale(width / (2 * Math.PI))
      .translate([width / 2, height / 1.55]);

    this.path = d3.geoPath(this.projection);

    const countries = topojson.feature(
      this.worldData,
      this.worldData.objects.countries
    ) as any;

    this.mapG
      .selectAll<SVGPathElement, any>('path.country')
      .data(countries.features)
      .enter()
      .append('path')
      .attr('d', this.path as any)
      .attr('class', 'country')
      .classed('has-data', (d: any) => this.getValueForFeature(d) != null)
      .on('mousemove', (event: MouseEvent, d: any) => this.onHoverMove(event, d))
      .on('mouseleave', (event: MouseEvent) => this.onHoverOut(event))
      .on('click', (_: MouseEvent, d: any) => {
        if (this.getValueForFeature(d) == null) return;
        this.onCountryClick(d);
      });

    const gridSize = 24;

    const gridG = this.mapG.append('g').attr('class', 'pixel-grid');

    for (let x = 0; x <= width; x += gridSize) {
      gridG.append('line')
        .attr('x1', x)
        .attr('y1', 0)
        .attr('x2', x)
        .attr('y2', height);
    }

    for (let y = 0; y <= height; y += gridSize) {
      gridG.append('line')
        .attr('x1', 0)
        .attr('y1', y)
        .attr('x2', width)
        .attr('y2', y);
    }

    this.updateColors();
    this.updateLegend();
    this.updateActiveCategoryLabel();
  }

  private getValueForFeature(d: any): number | null {
    const name = d?.properties?.name?.toLowerCase().trim();
    return name ? this.valueByName.get(name) ?? null : null;
  }

  private getColorScale() {
    const values = this.mapData.map(d => d.value).filter(v => v != null).sort(d3.ascending);
    const q = d3.scaleQuantile<number, number>()
      .domain(values)
      .range(d3.range(0, 7));

    const ramp = ['#4a2530', '#5a2533', '#6d2637', '#82273b', '#9a2840', '#b62a46', '#d92d4d'];

    return (v: number) => {
      const index = q(v);
      return ramp[index];
    };
  }

  private updateColors(): void {
    const color = this.getColorScale();
    this.mapG.selectAll<SVGPathElement, any>('path.country')
      .classed('has-data', (d: any) => this.getValueForFeature(d) != null)
      .attr('fill', (d: any) => {
        const v = this.getValueForFeature(d);
        return v == null ? this.neutralFill : color(v);
      });
  }

  private onHoverMove(event: MouseEvent, d: any): void {
    const name = d?.properties?.name ?? '';
    const v = this.getValueForFeature(d);

    this.mapG.selectAll('path.country').classed('hovered', false);
    d3.select(event.currentTarget as SVGPathElement).classed('hovered', true);

    this.tooltip.selectAll('*').remove();
    this.tooltip.append('div').text(name);
    this.tooltip.append('div').text(`Leaks: ${v ?? 'N/A'}`);

    const container = this.chartContainer.nativeElement as HTMLElement;
    const rect = container.getBoundingClientRect();
    const tipEl = this.tooltip.node() as HTMLDivElement | null;
    const tipW = tipEl?.offsetWidth ?? 160;
    const tipH = tipEl?.offsetHeight ?? 44;

    let x = event.clientX - rect.left + 12;
    let y = event.clientY - rect.top + 12;

    if (x + tipW > rect.width - 8) x = event.clientX - rect.left - tipW - 12;
    if (y + tipH > rect.height - 8) y = event.clientY - rect.top - tipH - 12;
    if (x < 8) x = 8;
    if (y < 8) y = 8;

    this.tooltip
      .attr('class', 'heatmap-tooltip heatmap-tooltip-visible')
      .style('left', `${x}px`)
      .style('top', `${y}px`);
  }

  private onHoverOut(event: MouseEvent): void {
    d3.select(event.currentTarget as SVGPathElement).classed('hovered', false);
    this.tooltip
      .attr('class', 'heatmap-tooltip')
      .style('left', null)
      .style('top', null);
  }

  private onCountryClick(d: any): void {
    const name = d?.properties?.name;
    if (!name) return;
    this.selectedName = name.toLowerCase();
    this.openCountryReport(name);
  }

  private gettingUniqueCountrys(): CountryData[] {
    const counts: Record<string, number> = {};

    this.activeCountryReports?.forEach((doc: any) => {

      doc?.m_country?.forEach((c: string) => {
        c.split(',').map(x => x.trim()).forEach(cc => {
          counts[cc] = (counts[cc] || 0) + 1;
        });
      });

    });

    return Object.entries(counts).map(([name, value]) => ({
      id: name,
      name,
      value
    }));
  }

  private openCountryReport(name: string): void {
    this.selectedCountryReports = this.getReportsByCountry(name);
    this.isOpenCountryReport = true;
  }

  getReportsByCountry(country: string): any[] {
    const key = country.toLowerCase();
    return this.activeCountryReports?.filter((r: any) =>
      r?.m_country?.some((c: string) =>
        c.split(',').some(p => p.trim().toLowerCase() === key)
      )
    ) ?? [];
  }

  closeCountryReport(): void {
    this.isOpenCountryReport = false;
    this.selectedName = null;
  }
  private animateMapTransition(): void {
    if (!this.mapG) return;

    const color = this.getColorScale();
    const getValueForFeature = this.getValueForFeature.bind(this);
    const neutralFill = this.neutralFill;

    const countries = this.mapG.selectAll<SVGPathElement, any>('path.country');

    countries
      .classed('has-data', (d: any) => getValueForFeature(d) != null)
      .transition()
      .duration(1100)
      .ease(d3.easeCubicInOut)
      .attrTween('fill', function (this: SVGPathElement, d: any) {
        const v = getValueForFeature(d);
        const nextFill = v == null ? neutralFill : color(v);
        const currentFill = d3.select(this).attr('fill') || neutralFill;
        const interpolateFill = d3.interpolateRgb(currentFill, nextFill);
        return (t: number) => interpolateFill(t);
      });
  }

}

import { Injectable, ElementRef } from '@angular/core';
import { DashboardService } from '../../services/dashboard/dashboard.service';
import { AppService } from '../core/app/app.service';

@Injectable({ providedIn: 'root' })
export class HomeSearchService {
    showFiltersOverlay = false;

    constructor(
        private dashboardService: DashboardService,
        private appService: AppService
    ) { }

    setMatchType(type: string) {
        this.dashboardService.selectedFilters.set({
            ...this.dashboardService.selectedFilters(),
            matchtype: type
        });
        this.appService.set('matchType', type);
    }

    closeOverlay() {
        this.showFiltersOverlay = false;
    }

    openOverlay() {
        this.showFiltersOverlay = true;
    }

    toggleAdvanceSettings() {
        const cfg = this.appService.configData();
        this.appService.set(
            'advance_setting_toggle',
            !cfg.localSettings.advance_setting_toggle
        );
        this.showFiltersOverlay = true;
    }

    toggleAdvancedTools(event: Event) {
        event.preventDefault();
        event.stopPropagation();
        const cfg = this.appService.configData();
        cfg.localSettings.enable_advanced_tools =
            !cfg.localSettings.enable_advanced_tools;

        this.appService.set(
            'enable_advanced_tools',
            cfg.localSettings.enable_advanced_tools
        );
        this.appService.configData.set(cfg);
    }

    handleSearchInput(event: Event) {
        const value = (event.target as HTMLInputElement)?.value?.trim();
        if (value && window.innerWidth < 460) {
            this.closeOverlay();
        }
    }

    handleDocumentClick(
        event: MouseEvent,
        filtersWrapper?: ElementRef,
        searchInput?: ElementRef
    ) {
        const target = event.target as HTMLElement;

        const clickedInsideFilter =
            filtersWrapper?.nativeElement.contains(target);
        const clickedInput =
            searchInput?.nativeElement.contains(target);

        if (!clickedInsideFilter && !clickedInput) {
            this.closeOverlay();
        }
    }
}

import { Component, ElementRef, HostListener, Input, OnInit, ViewChild } from '@angular/core';
import { CommonModule, NgOptimizedImage } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { DashboardService } from '../../../services/dashboard/dashboard.service';
import { ConsolidatedCallbackModel } from '../../../shared/model/results/consolidated/consolidated.callback.model';
import { SearchFiltersComponent } from "../search-filters/search-filters.component";
import { AppService } from '../../../services/core/app/app.service';
import { HomeInsightComponent } from "../home-insight/home-insight.component";
import { AuthService } from '../../../services/authetication/auth.service';
import { LicenseService } from '../../../services/licenses/licenses.service';
import { HomeSearchService } from '../../../services/home_search/home.search.service';
import { WorldHeatmapComponent } from "../world-heatmap/world-heatmap.component";

@Component({
  selector: 'app-home-search',
  standalone: true,
  imports: [FormsModule, NgOptimizedImage, CommonModule, SearchFiltersComponent, HomeInsightComponent, WorldHeatmapComponent],
  templateUrl: './home-search.component.html',
})
export class HomeSearchComponent implements OnInit {
  @Input() isRoleAdmin: boolean = true;
  searchQuery = '';
  selectedSearchBy = 'Match any term';
  @ViewChild('filtersWrapper', { static: false }) filtersWrapperRef!: ElementRef;
  @ViewChild('searchInput', { static: false }) searchInputRef!: ElementRef;

  homeInsightExpanded = false;

  public insightDragging = false;
  public insightDragY: number | null = null;

  private insightPointerId: number | null = null;
  private insightStartY = 0;
  private insightStartOffset = 0;
  private insightMoved = false;

  constructor(public dashboardService: DashboardService, private route: ActivatedRoute, private router: Router, public app_service: AppService, protected authService: AuthService, protected licenseService: LicenseService, protected homeSearchService: HomeSearchService) {
  }

  ngOnInit(): void {
    const cfg = this.app_service.configData();
    const matchtype = cfg.localSettings.matchType;
    this.onSetMatchType(matchtype)
  }

  onSetMatchType(type: string) {
    this.homeSearchService.setMatchType(type);
  }

  onSearchSubmit(): void {
    this.searchInputRef?.nativeElement.blur();
    this.dashboardService.consolidatedCallbackModel = new ConsolidatedCallbackModel();
    const queryParams = {
      ...this.route.snapshot.queryParams,
      q: this.searchQuery || null
    };
    this.router.navigate(['/dashboard/profile/consolidated/all'], {
      queryParams,
      queryParamsHandling: 'merge'
    }).then();
  }

  getMatchType() {
    const matchtype = this.dashboardService.selectedFilters()["matchtype"];

    if (matchtype === "full") {
      return "Match full query";
    } else if (matchtype === "or") {
      return "Match any term";
    } else if (matchtype === "semantic") {
      return "Match semantic query";
    } else {
      return "Match individual terms";
    }
  }

  setFilterOverlay(newValue: boolean) {
    this.homeSearchService.showFiltersOverlay = newValue;
  }

  onAdvanceSettingToggle() {
    this.homeSearchService.toggleAdvanceSettings();
  }

  onToolToggle(event: Event) {
    this.homeSearchService.toggleAdvancedTools(event);
  }

  onSearchInput(event: Event) {
    this.homeSearchService.handleSearchInput(event);
  }

  onInsightToggleClick(event: MouseEvent): void {
    event.preventDefault();
    event.stopPropagation();
    if (this.insightMoved) {
      this.insightMoved = false;
      return;
    }
    this.homeInsightExpanded = !this.homeInsightExpanded;
  }

  onInsightPointerDown(event: PointerEvent): void {
    event.preventDefault();
    event.stopPropagation();

    const el = event.currentTarget as HTMLElement;
    el.setPointerCapture(event.pointerId);

    this.insightDragging = true;
    this.insightMoved = false;
    this.insightPointerId = event.pointerId;
    this.insightStartY = event.clientY;

    const max = Math.round(window.innerHeight * 0.30);
    this.insightStartOffset = this.homeInsightExpanded ? -max : 0;
    this.insightDragY = this.insightStartOffset;
  }

  onInsightPointerMove(event: PointerEvent): void {
    if (!this.insightDragging || this.insightPointerId !== event.pointerId) return;

    event.preventDefault();
    event.stopPropagation();

    const max = Math.round(window.innerHeight * 0.30);
    const dy = event.clientY - this.insightStartY;
    if (Math.abs(dy) > 3) {
      this.insightMoved = true;
    }
    const next = this.insightStartOffset + dy;

    this.insightDragY = Math.max(-max, Math.min(0, next));
  }

  onInsightPointerUp(event: PointerEvent): void {
    if (this.insightPointerId !== event.pointerId) return;

    event.preventDefault();
    event.stopPropagation();

    const el = event.currentTarget as HTMLElement;
    try {
      el.releasePointerCapture(event.pointerId);
    } catch {
    }

    const max = Math.round(window.innerHeight * 0.30);
    const mid = -max / 2;
    const y = this.insightDragY ?? (this.homeInsightExpanded ? -max : 0);

    this.homeInsightExpanded = y <= mid;

    this.insightPointerId = null;
    this.insightDragging = false;
    this.insightDragY = null;
  }

  onInsightPointerCancel(event: PointerEvent): void {
    if (this.insightPointerId !== event.pointerId) return;

    event.preventDefault();
    event.stopPropagation();

    const el = event.currentTarget as HTMLElement;
    try {
      el.releasePointerCapture(event.pointerId);
    } catch {
    }

    this.insightPointerId = null;
    this.insightDragging = false;
    this.insightDragY = null;
  }


  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent) {
    this.homeSearchService.handleDocumentClick(
      event,
      this.filtersWrapperRef,
      this.searchInputRef
    );
  }
}
