<ng-container *ngIf="query_triggered && loading">
  <div class="scan_progress-top" *ngIf="progress < 100">
    <div class="scan_progress-text">{{ currentStep || 'Scanning...' }} ({{ progress }}%)</div>
    <div class="scan_progress-bar">
      <div class="scan_progress-fill" [style.width.%]="progress"></div>
    </div>
  </div>
</ng-container>

<div class="ml-lg-4 dash-api_hint">
  <div class="default-notification-banner default-notification-banner-stealer">
    <span><img alt="Info Icon" class="default-notification-banner-icon" src="/assets/images/shared/hint.svg"/><span>{{ apiType === 'user' ? 'Determines whether the specified user has a presence on any (clearnet) platform.' : apiType === 'social' ? 'Determines whether the provided username exists on (clearnet) social platforms.' : apiType === 'cracked' ? 'Checks for cracked key signals for the provided Play Store URL.' : apiType === 'software' ? 'Checks for cracked mirrors of known softwares.' : apiType === 'crypto' ? 'Determines whether the provided wallet and transaction hash show any signals.' : '' }}</span></span>
  </div>
</div>

<div class="file-scan-container" *ngIf="query_triggered && !loading && hasResults" @fadeInDashboardItem>
  <section class="search__result-detail-ioc search__result-detail-extended ioc-report-container">
    <div class="ioc-report-hero" @fadeInDashboardItem>
      <div class="ioc-report-hero-title">Search Results for <span class="ioc-report-hero-sep">〡</span><span class="ioc-report-hero-file">{{ (apiType === 'user' ? (displayQ1 || q1) : (q1 || displayQ1)) || 'query' }}</span></div>
      <div class="ioc-report-hero-sub">
        <span class="ioc-report-pill status-success"><i class="bi bi-check-circle-fill"></i> success </span>
        <button type="button" class="ioc-report-pill" *ngIf="apiType === 'crypto' && txDrilldown" (click)="backFromTx()"><i class="bi bi-arrow-left"></i> back</button>
      </div>
    </div>

    <div class="ioc-report-summary-grid" @fadeInDashboardItem>
      <div class="ioc-report-stat stat-0">
        <div class="ioc-report-stat-icon"><i class="bi bi-diagram-3"></i></div>
        <div class="ioc-report-stat-body">
          <div class="ioc-report-stat-label">API Type</div>
          <div class="ioc-report-stat-value">{{ apiType }}</div>
        </div>
      </div>

      <div class="ioc-report-stat stat-1">
        <div class="ioc-report-stat-icon"><i class="bi bi-shield-exclamation"></i></div>
        <div class="ioc-report-stat-body">
          <div class="ioc-report-stat-label">Total Results</div>
          <div class="ioc-report-stat-value">{{ apiType === 'crypto' ? ((cryptoResult?.recent_transactions?.length || 0) || 1) : cardsData.length }}</div>
        </div>
      </div>

      <div class="ioc-report-stat stat-2">
        <div class="ioc-report-stat-icon"><i class="bi bi-person-badge"></i></div>
        <div class="ioc-report-stat-body">
          <div class="ioc-report-stat-label">Query 1</div>
          <div class="ioc-report-stat-value mono">{{ (displayQ1 || q1) || 'not found' }}</div>
        </div>
      </div>

      <div class="ioc-report-stat stat-3" *ngIf="apiType !== 'social' && apiType !== 'cracked' && apiType !== 'software'">
        <div class="ioc-report-stat-icon"><i class="bi bi-envelope"></i></div>
        <div class="ioc-report-stat-body">
          <div class="ioc-report-stat-label">Query 2</div>
          <div class="ioc-report-stat-value mono">{{ (displayQ2 || q2) || 'not found' }}</div>
        </div>
      </div>
    </div>

    <section class="ioc-report-findings">
      <ng-container *ngIf="apiType === 'crypto'; else nonCryptoSwitch">
        <ng-container *ngIf="cryptoResult as r">
          <ng-container *ngIf="(r?.query_type === 'transaction_id' || r?.txid); else cryptoWalletView">
            <div class="ioc-report-category" @fadeInDashboardItem>
              <div class="ioc-report-category-header">
                <div class="ioc-report-category-left">
                  <div class="ioc-report-category-name">{{ r?.detected_network || r?.network || 'crypto' }}</div>
                  <div class="ioc-report-category-count">{{ r?.txid ? '1 Transaction' : 'not available' }}</div>
                </div>
              </div>

              <div class="ioc-report-findings-list">
                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.txid || (displayQ2 || q2) || 'not found' }}</div>
                    <div class="ioc-report-finding-desc">TXID</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">TX</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value">{{ r?.network || r?.detected_network || 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Network</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Network</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value">{{ r?.status_info?.confirmed === true ? 'true' : (r?.status_info?.confirmed === false ? 'false' : 'not available') }}</div>
                    <div class="ioc-report-finding-desc">Confirmed</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Status</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.status_info?.block_height ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Block Height</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Block</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.status_info?.confirmations ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Confirmations</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Block</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.amounts?.total_input_btc ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Total Input (BTC)</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Amounts</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.amounts?.total_output_btc ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Total Output (BTC)</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Amounts</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.amounts?.fee_btc ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Fee (BTC)</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Fee</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.transaction_details?.size ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Size</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Details</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.transaction_details?.weight ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Weight</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Details</span></div>
                </div>
              </div>
            </div>

            <div class="ioc-report-category" *ngIf="r?.inputs && r?.inputs.length > 0" @fadeInDashboardItem>
              <div class="ioc-report-category-header">
                <div class="ioc-report-category-left">
                  <div class="ioc-report-category-name">Inputs</div>
                  <div class="ioc-report-category-count">{{ r?.inputs.length }} Inputs</div>
                </div>
              </div>

              <div class="ioc-report-findings-list">
                <div class="ioc-report-finding" *ngFor="let i of r?.inputs" @fadeInDashboardItem (click)="openAddr(i?.address)" style="cursor:pointer">
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ i?.address }}</div>
                    <div class="ioc-report-finding-desc">Address ({{ i?.value_btc ?? 'not available' }} BTC)</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">IN</span></div>
                </div>
              </div>
            </div>

            <div class="ioc-report-category" *ngIf="r?.outputs && r?.outputs.length > 0" @fadeInDashboardItem>
              <div class="ioc-report-category-header">
                <div class="ioc-report-category-left">
                  <div class="ioc-report-category-name">Outputs</div>
                  <div class="ioc-report-category-count">{{ r?.outputs.length }} Outputs</div>
                </div>
              </div>

              <div class="ioc-report-findings-list">
                <div class="ioc-report-finding" *ngFor="let o of r?.outputs" @fadeInDashboardItem (click)="openAddr(o?.address)" style="cursor:pointer">
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ o?.address }}</div>
                    <div class="ioc-report-finding-desc">Address ({{ o?.value_btc ?? 'not available' }} BTC)</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">OUT</span></div>
                </div>
              </div>
            </div>
          </ng-container>

          <ng-template #cryptoWalletView>
            <div class="ioc-report-category" @fadeInDashboardItem>
              <div class="ioc-report-category-header">
                <div class="ioc-report-category-left">
                  <div class="ioc-report-category-name">{{ r?.network || 'crypto' }}</div>
                  <div class="ioc-report-category-count">{{ (r?.recent_transactions?.length || 0) }} Transactions</div>
                </div>
              </div>

              <div class="ioc-report-findings-list">
                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.address || (displayQ1 || q1) || 'not found' }}</div>
                    <div class="ioc-report-finding-desc">Wallet Address</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Wallet</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value">{{ r?.network || 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Network</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Network</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.balance?.confirmed ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Confirmed Balance</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Balance</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.balance?.unconfirmed ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Unconfirmed Balance</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Balance</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.transaction_count?.total ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Total Transactions</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">TX</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.transaction_count?.received ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Received</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">TX</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.transaction_count?.sent ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Sent</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">TX</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.total_received ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Total Received</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Stats</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.total_sent ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Total Sent</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Stats</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.statistics?.first_seen ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">First Seen</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Stats</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.statistics?.last_seen ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Last Seen</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Stats</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ r?.statistics?.avg_transaction_value ?? 'not available' }}</div>
                    <div class="ioc-report-finding-desc">Avg Transaction Value</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Stats</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value">{{ r?.statistics?.is_active === true ? 'true' : (r?.statistics?.is_active === false ? 'false' : 'not available') }}</div>
                    <div class="ioc-report-finding-desc">Is Active</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Status</span></div>
                </div>
              </div>
            </div>

            <div class="ioc-report-category" *ngIf="r?.recent_transactions && r?.recent_transactions.length > 0" @fadeInDashboardItem>
              <div class="ioc-report-category-header">
                <div class="ioc-report-category-left">
                  <div class="ioc-report-category-name">Recent Transactions</div>
                  <div class="ioc-report-category-count">{{ r?.recent_transactions.length }} TX</div>
                </div>
              </div>

              <div class="ioc-report-findings-list">
                <div class="ioc-report-finding" *ngFor="let tx of r?.recent_transactions" @fadeInDashboardItem (click)="openTx(tx?.txid)" style="cursor:pointer">
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value mono">{{ tx?.txid }}</div>
                    <div class="ioc-report-finding-desc">TXID</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">TX</span></div>
                </div>
              </div>
            </div>
          </ng-template>
        </ng-container>
      </ng-container>

      <ng-template #nonCryptoSwitch>
        <ng-container *ngIf="apiType === 'cracked' || apiType === 'software'; else nonCrackedSwitch">
          <div class="ioc-report-category" *ngFor="let item of cardsData" @fadeInDashboardItem>
            <div class="ioc-report-category-header">
              <div class="ioc-report-category-left">
                <div class="ioc-report-category-name">{{ item?.m_app_name }}</div>
                <div class="ioc-report-category-count">{{ (item?.m_download_link?.length || 0) }} Links</div>
              </div>
            </div>

            <div class="ioc-report-findings-list">
              <div class="ioc-report-finding" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value mono">{{ item?.m_app_url }}</div>
                  <div class="ioc-report-finding-desc">Application URL</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">{{ apiType }}</span></div>
              </div>

              <div class="ioc-report-finding" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value mono">{{ item?.m_package_id }}</div>
                  <div class="ioc-report-finding-desc">Package ID</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Package</span></div>
              </div>

              <div class="ioc-report-finding" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value">{{ item?.m_network }}</div>
                  <div class="ioc-report-finding-desc">Network</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Network</span></div>
              </div>

              <div class="ioc-report-finding" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value mono">{{ item?.m_version }}</div>
                  <div class="ioc-report-finding-desc">Version</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Version</span></div>
              </div>

              <div class="ioc-report-finding" *ngFor="let ct of item?.m_content_type" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value">{{ ct }}</div>
                  <div class="ioc-report-finding-desc">Content Type</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Type</span></div>
              </div>

              <div class="ioc-report-finding" *ngFor="let d of item?.m_download_link" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value"><a class="card-link" [href]="d" target="_blank" rel="noopener noreferrer" title="{{ d }}"><span class="link-ico" aria-hidden="true">🔗</span><span class="link-text">{{ d }}</span></a></div>
                  <div class="ioc-report-finding-desc">Download Link</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Download</span></div>
              </div>

              <div class="ioc-report-finding" *ngIf="!item?.m_download_link || item?.m_download_link?.length === 0" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value">not available</div>
                  <div class="ioc-report-finding-desc">Download Links</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Download</span></div>
              </div>

              <div class="ioc-report-finding" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value mono">{{ item?.m_apk_size ? item?.m_apk_size : 'not available' }}</div>
                  <div class="ioc-report-finding-desc">APK Size</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Size</span></div>
              </div>

              <div class="ioc-report-finding" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value mono">{{ item?.m_latest_date }}</div>
                  <div class="ioc-report-finding-desc">Latest Date</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Date</span></div>
              </div>

              <div class="ioc-report-finding" *ngIf="item?.m_mod_features && (item?.m_mod_features + '').trim().length > 0" @fadeInDashboardItem>
                <div class="ioc-report-finding-main">
                  <div class="ioc-report-finding-value mono">{{ item?.m_mod_features }}</div>
                  <div class="ioc-report-finding-desc">Mod Features</div>
                </div>
                <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Mod</span></div>
              </div>
            </div>
          </div>
        </ng-container>

        <ng-template #nonCrackedSwitch>
          <ng-container *ngIf="apiType === 'social'; else nonSocialView">
            <div class="ioc-report-category" *ngFor="let item of cardsData; let last = last" @fadeInDashboardItem>
              <div class="ioc-report-category-header">
                <div class="ioc-report-category-left">
                  <div class="ioc-report-category-name">{{ item?.m_title }}</div>
                  <div class="ioc-report-category-count">{{ ((item?.m_weblink?.length || 0) + (item?.m_dumplink?.length || 0)) }} Links</div>
                </div>
              </div>

              <div class="ioc-report-findings-list">
                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value"><a class="card-link" [href]="item?.m_url" target="_blank" rel="noopener" title="{{ item?.m_url }}"><span class="link-ico" aria-hidden="true">🔗</span><span class="link-text">{{ item?.m_url }}</span></a></div>
                    <div class="ioc-report-finding-desc">Profile URL</div>
                  </div>
                  <div class="ioc-report-finding-right"><span class="ioc-report-type-badge">Profile</span></div>
                </div>

                <div class="ioc-report-finding" @fadeInDashboardItem>
                  <div class="ioc-report-finding-main">
                    <div class="ioc-report-finding-value">{{ item?.m_base_url }}</div>
                    <div class="ioc-report-finding-desc">Found On</div>
                  </div>
