        <div class="selected-filter-bar__filter-type" *ngIf="sidebarFilterCount()>0">
          Sidebar({{ sidebarFilterCount() }}) <img
          src="../../../../assets/images/shared/theme/searchFilter_clossButton_white.svg"
          class="selected-filter-bar__remove-x" (click)="clearFilters('sidebar')" alt="close"/>
        </div>
        <div class="selected-filter-bar__filter-type"
             *ngIf="this.app_service.getConfig().localSettings.matchType && this.app_service.getConfig().localSettings.matchType!='or'">
          Search Type ({{ this.app_service.getConfig().localSettings.matchType }}) <img
          src="../../../../assets/images/shared/theme/searchFilter_clossButton_white.svg"
          class="selected-filter-bar__remove-x" (click)="clearMatchType()" alt="close"/>
