            <div class="selected-filter-bar__filter-item">
              <div class="selected-filter-bar__filter-label-edit">
                {{ filter_mapping[key] || key }}
              </div>
              <span class="selected-filter-bar__filter-tag">
                {{ selectedFilters[key] }}
              </span>
