          </ng-container>
        </ng-container>

        <ng-template #noSidebarFilters>
          <div class="selected-filter-bar__no-filters-text">
            Sidebar filters are empty. Click the filter icon (top right) to select filters.
          </div>
        </ng-template>
      </div>


      <div class="selected-filter-bar__divider"></div>

      <ng-container *ngIf="entityFiltersCount(); else noSearchFilters">
        <div class="selected-filter-bar__filter-item">
          <div class="selected-filter-bar__filter-label-edit">Entity Type</div>
          <div class="selected-filter-bar__entity-filter-wrap">
            <ng-container *ngIf="getVisibleTags().length > 0">
              <div class="selected-filter-bar__filter-tag" *ngFor="let tag of getVisibleTags()">
                {{ tag }}<img src="assets/images/shared/theme/searchFilter_clossButton_white.svg"
                              class="selected-filter-bar__remove-x" (click)="removeEntityTypeFilterTag(tag)"
                              alt="search"/>
              </div>
              <div class="selected-filter-bar__filter-tag selected-filter-bar__more-tag"
                   *ngIf="getHiddenTagCount() > 0">
                +{{ getHiddenTagCount() }}
              </div>
            </ng-container>
          </div>
        </div>
      </ng-container>

      <ng-template #noSearchFilters>
        <div class="selected-filter-bar__no-filters-text">
          Entity filters are empty. Click the search bar to select filters.
        </div>
      </ng-template>
    </div>

  </div>
</div>

