const sets = [
  bold,
  italic,
  boldItalic,
  script,
  boldScript,
  fraktur,
  doubleStruck,
  sans,
  sansBold,
  sansItalic,
  sansBoldItalic,
  mono,
  fullwidth
];

const map: Record<string, string> = {};

for (const set of sets) {
  let i = 0;
  for (const ch of set) {
    if (i >= base.length) {
      break;
    }
    map[ch] = base[i];
    i++;
  }
}

map["　"] = " ";

export function normalizeUnicode(input: string): string {
  if (!input) {
    return "";
  }
  let out = "";
  for (const c of input) {
    out += map[c] ?? c;
  }
  return out;
}

import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
  name: 'normalizeUnicode'
})
export class NormalizeUnicodePipe implements PipeTransform {

  transform(value: unknown): unknown {
    return typeof value === 'string' ? normalizeUnicode(value) : value;
  }

}

import {AfterViewInit, ChangeDetectorRef, Component, OnInit, signal} from '@angular/core';
import {AppService} from '../../../../../services/core/app/app.service';
import {DashboardService} from '../../../../../services/dashboard/dashboard.service';
import {ActivatedRoute, Router} from '@angular/router';
import {combineLatest, distinctUntilChanged, map, switchMap, timer} from 'rxjs';
import {ChatCallbackModel} from '../../../../model/results/chat/chat.callback.model';
import {NgIf} from '@angular/common';
import {PaginationComponent} from '../../../pagination/pagination.component';
import {ResultComponent} from '../../../result/result.component';
import {DashboardResultChatComponent} from '../../dashboard-results/dashboard-result-chat/dashboard-result-chat.component';
import {fadeInDashboardItem} from '../../../../animations/dashboard.item.animation';
import {chat_filters} from '../../../../constants/filters';
import {ChannelTypeKeys, SortType} from '../../../../constants/shared-enums';
import {HelperService} from '../../../../services/helper.service';

@Component({
  selector: 'app-dashboard-chats',
  imports: [
    NgIf,
    PaginationComponent,
    ResultComponent,
    DashboardResultChatComponent
  ],
  templateUrl: './dashboard-chats.component.html',
  animations: [fadeInDashboardItem]
})
export class DashboardChatsComponent implements OnInit, AfterViewInit {
  public isResponseLoading = signal(false);
  public chatCallbackModel: ChatCallbackModel = new ChatCallbackModel();

  query = ""
  firstTrigger = true
  result_count = 0;
  protected readonly Math = Math;
  protected readonly chat_filters = chat_filters;

  constructor(protected helperService: HelperService, public appService: AppService, public dashboardService: DashboardService, private router: Router, private route: ActivatedRoute, private cdr: ChangeDetectorRef) {
  }

  get currentResultCount(): number {
    return this.chatCallbackModel.Page_Count ?? 0;
  }

  ngAfterViewInit(): void {
    this.appService.updatePage(this.dashboardService.consolidatedParamModel.page);
    if(this.router.url.split('?')[0] != this.dashboardService.m_current_route){
      this.fetchSearchResults()
    }
  }

  ngOnInit(): void {
    this.chatCallbackModel = {...this.dashboardService.chatCallbackModel} as ChatCallbackModel;
    this.result_count = this.chatCallbackModel.Result.length
    const category = this.route.snapshot.routeConfig?.path;
    let isDiscussion = false
    if (category && ChannelTypeKeys.includes(category.toUpperCase())) {
      this.dashboardService.consolidatedParamModel.category = category
      isDiscussion = true
    } else {
      this.dashboardService.consolidatedParamModel.category = "all"
    }

    combineLatest([this.route.queryParams, this.route.url])
      .pipe(distinctUntilChanged())
      .subscribe(([params, _]) => {
        this.query = params['q'];
        this.dashboardService.consolidatedParamModel.q = params['q'] || '';
        this.dashboardService.consolidatedParamModel.page = params['page'] || '1';
        if (!isDiscussion && this.firstTrigger && ((this.chatCallbackModel.Result.length > 0))) {
          this.isResponseLoading.set(false)
          this.query = this.dashboardService.consolidatedParamModel.q
        } else if(this.dashboardService.chatCallbackModel.Result.length==0){
          this.cdr.detectChanges();
          this.fetchSearchResults()
        }
        this.firstTrigger = false
      });
  }

  fetchSearchResults(): void {
    if (!this.dashboardService.consolidatedParamModel.q) {
      this.isResponseLoading.set(false)
      this.dashboardService.consolidatedParamModel.q = "";

      this.router.navigate([], {
        queryParams: {},
        queryParamsHandling: ''
      }).then();
    }

    this.isResponseLoading.set(true)
    this.dashboardService
      .fetchSearchResults<ChatCallbackModel>('chat/telegram', this.dashboardService.consolidatedParamModel)
      .pipe(switchMap(response => timer(1000).pipe(map(() => response))))
      .subscribe(response => {
        if (response.success && response.data) {
          this.chatCallbackModel = response.data as ChatCallbackModel;
          this.dashboardService.chatCallbackModel = response.data as ChatCallbackModel;
        } else {
          this.chatCallbackModel = new ChatCallbackModel();
        }
        this.isResponseLoading.set(false)
        this.result_count = this.chatCallbackModel.Result.length;
      });
  }

  onPageChange(step: number) {
    this.dashboardService.consolidatedParamModel.page = step;
    this.fetchSearchResults();
  }

  onUpdateQuery(query: string) {
    this.dashboardService.consolidatedParamModel.q = query
  }

  resetFilters(_: void) {
    this.dashboardService.consolidatedParamModel.page = 1;
    this.fetchSearchResults();
  }

  reloadFilters(_: Record<string, string | null>) {
    this.fetchSearchResults();
  }

  onToggleSort(sort: SortType) {
    let key;
    let order: 'asc' | 'desc' = 'asc';

    key = 'm_message_date';

    if (sort === SortType.NEWEST_FIRST) {
      order = 'desc';
    } else if (sort === SortType.OLDEST_FIRST) {
      order = 'asc';
    } else if (sort === SortType.DEFAULT) {
      this.fetchSearchResults();
      return;
    }

    this.chatCallbackModel.Result = this.helperService.sortByKey<any>(
      this.chatCallbackModel.Result,
      key,
      order
    );
    this.cdr.detectChanges();
  }
}
<app-result (onToggleSort)="onToggleSort($event)" (reloadData)="fetchSearchResults()" (reloadFilters)="reloadFilters($event)" (resetFilter)="resetFilters($event)" (updateQuery)="onUpdateQuery($event)" [filterModel]="chat_filters" [isLoading]="isResponseLoading()" [result_count]="Math.ceil(chatCallbackModel.Result.length)" [searchQuery]="query" [showTabs]=false [suggestion]="chatCallbackModel.Suggestions[0]"></app-result>

<div *ngIf="!isResponseLoading()" @fadeInDashboardItem>
  <app-dashboard-result-chat [searchResults]="chatCallbackModel.Result"></app-dashboard-result-chat>
</div>

<div *ngIf="!isResponseLoading() && currentResultCount > 0" @fadeInDashboardItem class="pagination-margin">
  <app-pagination (pageChange)="onPageChange($event)" [currentPage]="this.dashboardService.consolidatedParamModel.page" [maxPages]="Math.floor(currentResultCount)"></app-pagination>
</div>

import { AfterViewInit, Component, Input, OnInit } from '@angular/core';
import { CommonModule, DatePipe, NgForOf, NgIf } from '@angular/common';
import { SafeHtml } from '@angular/platform-browser';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { HelperService } from '../../../../services/helper.service';
import { GeneralResultItem } from '../../../../model/results/general/general.callback.model';
import { LeakResultItem } from '../../../../model/results/leak/leak.callback.model';
import { ScrollService } from '../../../../services/scroll.service';
import { TooltipDirective } from '../../../../directive/tooltip-directive.directive';
import { AuthService } from '../../../../../services/authetication/auth.service';
import { LicenseService } from '../../../../../services/licenses/licenses.service';

@Component({
  selector: 'app-dashboard-results-general-grid',
  templateUrl: './dashboard-results-general-grid.component.html',
  imports: [NgForOf, RouterLink, DatePipe, NgIf, TooltipDirective, CommonModule],
  standalone: true
})
export class DashboardResultsGeneralGridComponent implements AfterViewInit, OnInit {
  private highlightCache = new Map<string, SafeHtml>();

  @Input() query!: string;
  @Input() type!: string;
  @Input() searchResults: (GeneralResultItem | LeakResultItem)[] = [];
  @Input() isExpandAble: boolean = false;

  currentUrl = '';
  queryParams: any = {};
  isCollapsed = true;
  isFreeStrategic = false;

  constructor(private authService: AuthService, private activatedRoute: ActivatedRoute, private helperService: HelperService, private router: Router, private route: ActivatedRoute, protected scrollService: ScrollService, protected licenseService: LicenseService) {
  }

  ngAfterViewInit() {
    this.scrollService.scrollToSavedPosition();
  }

  highlightWords(text: any): SafeHtml {
    const key = JSON.stringify(text);
    if (this.highlightCache.has(key)) return this.highlightCache.get(key)!;

    const result = this.helperService.highlightWords(text);
    this.highlightCache.set(key, result);
    return result;
  }

  ngOnInit() {
    this.currentUrl = this.router.url.split('?')[0];
    const ci = this.type === 'leak' ? 'leak' : this.type === 'tracking' ? 'leak' : this.type === 'news' ? 'leak' : this.type === 'general' ? 'general' : this.type === 'Strategic' ? 'strategic' : 'leak';
    if (this.currentUrl.includes('/consolidated/all') || this.currentUrl.includes('/profile/homepage/all')) {
      this.currentUrl = this.currentUrl.replace('/all', `/${ci}`);
    }

    this.route.queryParams.subscribe(params => {
      this.queryParams = {
        ...params,
        ci
      };
    });
    const params = new URLSearchParams(window.location.search);

    const isFree = params.get('mode') === 'free';
    const url = window.location.href.toLowerCase();
    const hasStrategic = url.includes('strategic');
    this.isFreeStrategic = isFree && hasStrategic;
  }

  isWithinDays(dateString = '', days: number): boolean {
    if (!dateString) return false;
    const createdDate = new Date(dateString);
    const today = new Date();
    const diffInDays = Math.floor((today.getTime() - createdDate.getTime()) / (1000 * 60 * 60 * 24));
    return diffInDays <= days;
  }

  isMobileMode(): boolean {
    return this.authService.getIsMobileDemo();
  }

  protected readonly window = window;
}
