      <ng-container *ngIf="item?.m_url as url; else noUrl">
        <div *ngIf="url.trim().length > 1; else noUrl" class="dashboard__search-link">
          {{ url }}
        </div>
      </ng-container>
      <ng-template #noUrl>
        <div class="dashboard__search-link">URL not available</div>
