      <div class="dashboard__search-info">
        <div class="dashboard__search-info-item">
          <span class="dashboard__info-label">Published on:</span> <span class="dashboard__info-value">{{
            item?.m_leak_date ? (item.m_leak_date | date: 'MMM d, y') : '-'
            }}</span>
        </div>
        <div class="dashboard__search-info-item">
          <span class="dashboard__info-label">Network:</span> <span class="dashboard__info-value">{{
            item.m_network
            }}</span>
        </div>
        <div class="dashboard__search-info-item">
          <span class="dashboard__info-label">Last checked:</span> <span class="dashboard__info-value">{{
            item?.m_creation_date | date: 'mediumDate'
            }}</span>
        </div>
        <div class="dashboard__search-status">
          <span class="dashboard__info-label">Status</span>
          <div class="d-flex align-items-center">
            <span [ngClass]="{
                  'bg-success': isWithinDays(item.m_creation_date, 5),
                  'bg-warning': isWithinDays(item.m_creation_date, 10) && !isWithinDays(item.m_creation_date, 5),
                  'bg-danger': !isWithinDays(item.m_creation_date, 10)
                }" class="rounded-circle d-inline-block me-2 dashboard__status-dot">
            </span>
            <span class="dashboard__status-text">
              {{ isWithinDays(item.m_creation_date, 5) ? 'active' : 'inactive' }}
            </span>
          </div>
        </div>
      </div>

    </div>
  </ng-container>
  <div class="see-more-wrapper" *ngIf="isExpandAble && searchResults.length > 2">
