import {Component, Input, OnInit} from '@angular/core';
import {CommonModule} from '@angular/common';

@Component({
  selector: 'app-json-viewer',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './json-viewer.component.html'
})
export class JsonViewerComponent implements OnInit{
  @Input() json: any;
  @Input() level = 0;
  @Input() parentPath = '';

  expandedMap = new Map<string, boolean>();

  excludedPaths = new Set([
    '_title:trocador.app',
    'm_meta_description',
    'm_content',
    'm_important_content'
  ]);

  ngOnInit(): void {
    this.initExpansionState(this.json, this.parentPath);
  }

  initExpansionState(obj: any, path: string): void {
    const shouldCollapse = [...this.excludedPaths].some(ex => path.endsWith(ex));

    if (this.isObject(obj)) {
      this.expandedMap.set(path, !shouldCollapse);

      for (const key of Object.keys(obj)) {
        const nextPath = this.pathKey(path, key);
        this.initExpansionState(obj[key], nextPath);
      }
    } else {
      this.expandedMap.set(path, !shouldCollapse);
    }
  }

  pathKey(parent: string, key: string): string {
    return parent ? `${parent}.${key}` : key;
  }

  isObject(value: any): boolean {
    return typeof value === 'object' && value !== null;
  }

  isCollapsible(value: any): boolean {
    return this.isObject(value) || (typeof value === 'string' && value.length > 1);
  }

  toggle(path: string): void {
    const current = this.expandedMap.get(path);
    this.expandedMap.set(path, !current);
  }

  isExpanded(path: string): boolean {
    return this.expandedMap.get(path) ?? false;
  }

  keys(obj: any): string[] {
    return Object.keys(obj);
  }
}
<ul class="json-tree json-tree--depth-{{ level }}">
  <ng-container *ngFor="let key of keys(json); let last = last">
    <li [class.json-tree__node--last]="last" class="json-tree_node">
      <div (click)="isCollapsible(json[key]) && toggle(pathKey(parentPath, key))" class="json-tree_line">
        <span *ngIf="isCollapsible(json[key])" class="json-tree_toggle">
          <img *ngIf="isExpanded(pathKey(parentPath, key)); else collapsedIcon"
            src="/assets/images/shared/theme/search_side_dropdown_icon_dark.svg" alt="Expanded" width="20"
            height="20" />
          <ng-template #collapsedIcon>
            <img [ngClass]="{ 'rotated': !isExpanded(pathKey(parentPath, key)) }"
              src="/assets/images/shared/theme/search_side_dropdown_icon_dark.svg" alt="Collapsed" width="20"
              height="20" />
          </ng-template>
        </span> <span class="json-tree_key json-tree_key-faded ms-1">{{ key }}</span>
      </div>

      <div *ngIf="isExpanded(pathKey(parentPath, key))" class="json-tree_children">
        <ng-container *ngIf="isObject(json[key]); else jsonLeaf">
          <app-json-viewer [json]="json[key]" [level]="level + 1"
            [parentPath]="pathKey(parentPath, key)"></app-json-viewer>
        </ng-container>

        <ng-template #jsonLeaf>
          <ul class="json-tree json-tree--depth-{{ level + 1 }}">
            <li class="json-tree_node json-tree__node--last">
              <div class="json-tree_line json-tree_line-leaf">
                <strong class="json-tree_value">{{ json[key] }}</strong>
              </div>
            </li>
          </ul>
        </ng-template>
      </div>
    </li>
  </ng-container>
</ul>

