              item.m_attacker.join(', ')
            }}</span>
          </div>
          <div *ngIf="item.m_web_server?.length" class="dashboard__search-info-item">
            <span class="dashboard__info-label">Web Server:</span> <span class="dashboard__info-value">{{
              item.m_web_server.join(', ')
            }}</span>
