  </div>
</ng-template>

import {AfterViewInit, ChangeDetectorRef, Component, OnInit, signal} from '@angular/core';
import {NgIf} from '@angular/common';
import {combineLatest, distinctUntilChanged, map, switchMap, timer} from 'rxjs';
import {ActivatedRoute, Router} from '@angular/router';
import {ResultComponent} from '../../../result/result.component';
import {DashboardService} from '../../../../../services/dashboard/dashboard.service';
import {PaginationComponent} from '../../../pagination/pagination.component';
import {DashboardResultGeneralListComponent} from '../../dashboard-results/dashboard-result-general-list/dashboard-result-general-list.component';
import {fadeInDashboardItem} from '../../../../animations/dashboard.item.animation';
import {DefacementCallbackModel} from '../../../../model/results/defacement/defacement.callback.model';
import {AppService} from '../../../../../services/core/app/app.service';
import {defacement_filters} from '../../../../constants/filters';
import {Category} from '../../../../constants/pages';
import {SortType} from '../../../../constants/shared-enums';
import {HelperService} from '../../../../services/helper.service';

@Component({
  selector: 'app-dashboard-defacement',
  standalone: true, imports: [ResultComponent, NgIf, PaginationComponent, DashboardResultGeneralListComponent],
  templateUrl: './dashboard-defacement.component.html',
  animations: [fadeInDashboardItem],
})
export class DashboardDefacementComponent implements OnInit, AfterViewInit {
  public isResponseLoading = signal(false);

  protected readonly Math = Math;
  protected readonly defacement_filters = defacement_filters;
  protected isList = true

  defacementCallbackModel: DefacementCallbackModel = new DefacementCallbackModel();
  result_count = 0;
  type = Category.DEFACEMENT
  query = '';
  firstTrigger = true;

  constructor(private app_service: AppService, protected helperService: HelperService, public appService: AppService, private route: ActivatedRoute, private cdr: ChangeDetectorRef, public dashboardService: DashboardService, private router: Router) {
  }

  ngAfterViewInit(): void {
    this.appService.updatePage(this.dashboardService.consolidatedParamModel.page)
  }

  ngOnInit(): void {
    this.defacementCallbackModel = {...this.dashboardService.defacementCallbackModel} as DefacementCallbackModel;
    this.result_count = this.defacementCallbackModel.Result.length

    combineLatest([this.route.queryParams, this.route.url])
      .pipe(distinctUntilChanged())
      .subscribe(([params, _]) => {
        this.query = params['q'] || '';
        this.dashboardService.consolidatedParamModel.q = params['q'] || '';
        this.dashboardService.consolidatedParamModel.page = params['page'] ? +params['page'] : 1;

        const route: string = this.router.url.split('?')[0];
        if (String(route) != this.dashboardService.m_current_route) {
          this.isResponseLoading.set(false)
          this.dashboardService.defacementCallbackModel = new DefacementCallbackModel()
          this.fetchSearchResults()
          return
        }


        if (this.dashboardService.defacementCallbackModel.Result.length > 0) {
          this.query = this.dashboardService.consolidatedParamModel.q
        } else {
          this.cdr.detectChanges();
          this.fetchSearchResults()
        }
        this.firstTrigger = false
      });
  }

  onUpdateQuery(query: string) {
    this.dashboardService.consolidatedParamModel.q = query;
    this.dashboardService.consolidatedParamModel.page = 1;
    this.fetchSearchResults();
  }

  fetchSearchResults() {
    if (!this.dashboardService.consolidatedParamModel.q) {
      this.dashboardService.consolidatedParamModel.q = ""

      this.router.navigate([], {
        queryParams: {},
        queryParamsHandling: ''
      }).then();
    }

    const lastSegment = this.route.snapshot.url.at(-1)?.path;
    if (lastSegment)
      this.dashboardService.consolidatedParamModel.content = lastSegment

    let matchtype = ""
    if(this.isList && this.app_service.configData().localSettings.matchType=="or"){
      matchtype = "or"
    }

    this.isResponseLoading.set(true)
    this.dashboardService
      .fetchSearchResults<DefacementCallbackModel>('search/defacement', this.dashboardService.consolidatedParamModel, matchtype)
      .pipe(switchMap(response => timer(1000).pipe(map(() => response))))
      .subscribe(response => {
        if (response.success && response.data) {
          this.defacementCallbackModel = response.data as DefacementCallbackModel;
          this.dashboardService.defacementCallbackModel = response.data as DefacementCallbackModel;
        } else {
          this.defacementCallbackModel = new DefacementCallbackModel();
        }
        this.isResponseLoading.set(false)
        this.result_count = this.defacementCallbackModel.Result.length;
        this.cdr.detectChanges();
      });
  }

  onPageChange(step: number) {
    this.dashboardService.consolidatedParamModel.page = step;
    this.fetchSearchResults();
  }

  resetFilters(_: void) {
    this.fetchSearchResults();
  }

  reloadFilters(_: Record<string, string | null>) {
    this.dashboardService.consolidatedParamModel.page = 1
    this.fetchSearchResults();
  }

  onToggleSort(sort: SortType) {
    let key;
    let order: 'asc' | 'desc' = 'asc';

    key = 'm_leak_date';

    if (sort === SortType.NEWEST_FIRST) {
      order = 'desc';
    } else if (sort === SortType.OLDEST_FIRST) {
      order = 'asc';
    } else if (sort === SortType.DEFAULT) {
      this.fetchSearchResults();
      return;
    }

    this.defacementCallbackModel.Result = this.helperService.sortByKey<any>(
      this.defacementCallbackModel.Result,
      key,
      order
    );
    this.cdr.detectChanges();
  }

  list_switch(tab: string) {
    this.isList = tab == "List";
  }
}
<app-result [discussion]="false" [isList]="isList" (onToggleSort)="onToggleSort($event)" [list_grid]="true" (onToggleSwitch)="list_switch($event)" [isLoading]="isResponseLoading()" (reloadData)="fetchSearchResults()" (reloadFilters)="reloadFilters($event)" (resetFilter)="resetFilters($event)" (updateQuery)="onUpdateQuery($event)" [filterModel]="defacement_filters" [result_count]="Math.ceil(result_count)" [searchQuery]="query" [showTabs]=true [type]="type"></app-result>

<app-dashboard-result-general-list *ngIf="!isResponseLoading() || isList" [isLoading]="isResponseLoading()" [isList]="this.isList" [searchResults]="defacementCallbackModel.Result" ></app-dashboard-result-general-list>

<div *ngIf="!isResponseLoading() && this.defacementCallbackModel.Result.length > 0" @fadeInDashboardItem class="pagination-margin">
  <app-pagination (pageChange)="onPageChange($event)" [maxPages]="Math.floor(this.dashboardService.consolidatedParamModel.page * this.defacementCallbackModel.Page_Count)"></app-pagination>
</div>

import {Component, OnInit} from '@angular/core';
import {ActivatedRoute} from '@angular/router';
import {CommonModule, DatePipe} from '@angular/common';
import {AppService} from '../../../../services/core/app/app.service';
import {JsonApiViewerComponent} from '../../json-api-viewer/json-api-viewer.component';
import {ReportMappingComponent} from '../../report-mapping/report-mapping.component';
import {DefacementResultItem} from '../../../model/results/defacement/defacement.callback.model';
import {ReportHeaderComponent} from '../../report-header/report-header.component';
import {ResultSectionComponent} from '../../result-components/result-section/result-section.component';
import {ResultListComponent} from '../../result-components/result-list/result-list.component';
import {TooltipDirective} from '../../../directive/tooltip-directive.directive';

@Component({
  selector: 'app-report-defacement',
  templateUrl: './report-defacement.component.html',
  imports: [
    CommonModule,
    DatePipe,
    JsonApiViewerComponent,
    ReportMappingComponent,
    ReportHeaderComponent,
    ResultSectionComponent,
    ResultListComponent,
    TooltipDirective
  ]
})
export class ReportDefacementComponent implements OnInit {
  defacementData: DefacementResultItem | null = null;
  lang = 'en';

  isExpandedMetadata = true;
  activeTab = '';
  content = '';
  listItems: any[] = [];
  arrayKeys: string[] = [];

  constructor(private route: ActivatedRoute, private appService: AppService) {
    this.lang = this.appService.getConfig().appSettings.language_allowed;
  }

  ngOnInit(): void {
    this.route.data.subscribe(data => {
      if (data['reportdata']) {
        this.defacementData = data['reportdata'] as DefacementResultItem;
        this.prepareMetadata();
      }
    });
  }

  get filteredArrayKeys(): string[] {
    return this.arrayKeys.filter(key => {
      const val = (this.defacementData as any)?.[key];
      return val != null && (!Array.isArray(val) || val.length > 0);
    });
  }

  metaadataToggleContent(): void {
    this.isExpandedMetadata = !this.isExpandedMetadata;
  }

  setActiveTab(tab: string): void {
    if (this.activeTab === tab) {
      this.activeTab = '';
      this.listItems = [];
      return;
    }
    this.activeTab = tab;

    if (this.defacementData && Array.isArray((this.defacementData as any)[tab])) {
      this.listItems = (this.defacementData as any)[tab];
    } else {
      this.listItems = [];
    }
  }

  formatKeyLabel(key: string): string {
    const cleaned = key.replace(/^m_/, '').replace(/[^a-zA-Z0-9]/g, ' ');
    return cleaned.length < 4
      ? cleaned.toUpperCase()
      : cleaned.toLowerCase().replace(/\w\S*/g, w => w[0].toUpperCase() + w.slice(1));
  }

  private prepareMetadata(): void {
    this.content = this.defacementData?.m_content || '';
    this.arrayKeys = [];

    if (Array.isArray((this.defacementData as any)?.m_section) && (this.defacementData as any).m_section.length > 0) {
      this.arrayKeys.push('m_section');
    }
    if (this.defacementData?.m_content && this.defacementData.m_content.trim() !== '') {
      this.arrayKeys.push('m_content');
    }

    if (this.defacementData) {
      Object.keys(this.defacementData).forEach(key => {
        const value = (this.defacementData as any)[key];
        if (Array.isArray(value) && value.length > 0 && key !== 'm_section') {
          this.arrayKeys.push(key);
        }
      });
    }

    const keys = this.filteredArrayKeys;
    if (keys.length > 0) {
      this.setActiveTab(keys[0]);
    }
  }
}

import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ChatResultItem } from '../../../model/results/chat/chat.callback.model';
import { CommonModule, NgForOf, NgIf, SlicePipe, } from '@angular/common';
import { ResultListComponent } from '../../result-components/result-list/result-list.component';
import { ResultSectionComponent } from '../../result-components/result-section/result-section.component';
import { fadeInDashboardItem } from '../../../animations/dashboard.item.animation';
import { TooltipDirective } from '../../../directive/tooltip-directive.directive';
import { JsonApiViewerComponent } from '../../json-api-viewer/json-api-viewer.component';
import { last, Observable } from 'rxjs';
import { AuthService } from '../../../../services/authetication/auth.service';
import { SocialResultItem } from '../../../model/results/social/social.callback.model';
import { ReportHeaderComponent } from '../../report-header/report-header.component';
import { DashboardService } from '../../../../services/dashboard/dashboard.service';
import { ChatWidgetComponent } from '../../chat-widget/chat-widget.component';
import { AppService } from '../../../../services/core/app/app.service';

@Component({
  selector: 'app-report-chat',
  templateUrl: './report-chat.component.html',
  standalone: true,
  imports: [
    NgIf,
    NgForOf,
    ResultListComponent,
    ResultSectionComponent,
    SlicePipe, CommonModule,
    JsonApiViewerComponent, TooltipDirective, ReportHeaderComponent, ChatWidgetComponent
  ],
  animations: [fadeInDashboardItem]
})
export class ReportChatComponent implements OnInit {
  protected readonly last = last;

  resultItem: ChatResultItem | SocialResultItem | null = null;
  arrayKeys: string[] = [];
  listItems: any[] = [];
  activeTab = '';
  content = '';
  summary = '';
  isExpandedMetadata = true

  constructor(protected appService: AppService, private route: ActivatedRoute, protected authService: AuthService, public dashboardService: DashboardService, private router: Router,) {
  }

  ngOnInit(): void {
    this.route.data.subscribe(({ reportdata }) => {
      this.resultItem = reportdata;
      this.processResultItem();
    });
  }

  metaadataToggleContent(): void {
    this.isExpandedMetadata = !this.isExpandedMetadata;
    if (this.router.url.split('?')[0] != this.dashboardService.m_current_route) {
      this.ngOnInit()
    }
  }

  processResultItem() {
    if (this.resultItem) {
      this.content = this.resultItem.m_content || '';
      this.summary = (this.resultItem.m_summary?.[0]) || '';
      this.arrayKeys = [];

      const addedKeys = new Set<string>();

      if (this.resultItem.m_content?.trim()) {
        this.arrayKeys.push('m_content');
        addedKeys.add('m_content');
      }

      if (Array.isArray(this.resultItem.m_summary) && this.resultItem.m_summary[0]?.trim()) {
        this.arrayKeys.push('m_summary');
        addedKeys.add('m_summary');
      }

      Object.keys(this.resultItem).forEach((key) => {
        const value = (this.resultItem as any)[key];
        if (
          Array.isArray(value) &&
          value.length > 0 &&
          !addedKeys.has(key)
        ) {
          this.arrayKeys.push(key);
          addedKeys.add(key);
        }
      });
      if (!this.activeTab) {
        let selectedTab = '';

        if (this.arrayKeys.includes('m_email')) {
          selectedTab = 'm_email';
        } else if (this.arrayKeys.includes('m_entity')) {
          selectedTab = 'm_entity';
        } else if (this.arrayKeys.includes('m_content_type')) {
          selectedTab = 'm_content_type';
        } else if (this.arrayKeys.length > 0) {
          selectedTab = this.arrayKeys[0];
        }

        if (selectedTab) {
          this.setActiveTab(selectedTab);
          const index = this.arrayKeys.indexOf(selectedTab);
          if (index > 0) {
            this.arrayKeys.splice(index, 1);
            this.arrayKeys.unshift(selectedTab);
          }
        }
      }
    }
  }


  setActiveTab(tab: string) {
    if (this.activeTab === tab) {
      this.activeTab = '';
      this.listItems = [];
      return;
    }

    this.activeTab = tab;

    if (tab === 'm_content' || tab === 'm_summary') {
      this.listItems = [];
    } else if (this.resultItem && Array.isArray((this.resultItem as any)[tab])) {
      this.listItems = (this.resultItem as any)[tab].slice(0, 100);
    } else {
      this.listItems = [];
    }
  }

  getContentLines(item: any): string[] {
    return item?.m_content
      ? item.m_content
        .split('\n')
        .filter((line: string) => line.trim() && (line.match(/ /g) || []).length > 5)
      : [];
  }

  getContentWithoutEmptyLines(content: string | undefined): string {
    if (!content) {
      return ""
    }
    return (content || '')
      .split('\n')
      .filter(line => line.trim().length > 0)
      .join('\n');
  }

  hasCodeType(obj: any): boolean {
    const t = obj?.m_content_type;
    return Array.isArray(t) ? t.some((x: string) => x?.includes('code')) : (typeof t === 'string' && t.includes('code'));
  }

  formatKeyLabel(key: string): string {
    const cleaned = key.replace(/^m_/, '').replace(/[^a-zA-Z0-9]/g, ' ');
    return cleaned.length < 4 ? cleaned.toUpperCase() : cleaned.toLowerCase().replace(/\w\S*/g, w => w[0].toUpperCase() + w.slice(1));
  }
}

import {AfterViewInit, ChangeDetectorRef, Component, OnInit, signal} from '@angular/core';
import {AppService} from '../../../../../services/core/app/app.service';
import {DashboardService} from '../../../../../services/dashboard/dashboard.service';
import {ActivatedRoute, Router} from '@angular/router';
import {combineLatest, distinctUntilChanged, map, switchMap, timer} from 'rxjs';
import {NgForOf, NgIf} from '@angular/common';
import {PaginationComponent} from '../../../pagination/pagination.component';
import {ResultComponent} from '../../../result/result.component';
import {fadeInDashboardItem} from '../../../../animations/dashboard.item.animation';
import {ExploitCallbackModel} from '../../../../model/results/exploit/exploit.callback.model';
import {FilterModel} from '../../../../model/filter/filter.model';
import {exploit_filters} from '../../../../constants/filters';
import {DashboardResultExploitComponent} from '../../dashboard-results/dashboard-result-exploit/dashboard-result-exploit.component';
import {Category} from '../../../../constants/pages';
import {SortType} from '../../../../constants/shared-enums';
import {HelperService} from '../../../../services/helper.service';
import {DashboardResultChatComponent} from '../../dashboard-results/dashboard-result-chat/dashboard-result-chat.component';
import {DashboardResultSocialComponent} from '../../dashboard-results/dashboard-result-social/dashboard-result-social.component';
import {DashboardResultsGeneralGridComponent} from '../../dashboard-results/dashboard-results-general-grid/dashboard-results-general-grid.component';
import {RankedCallbackModel} from '../../../../model/results/consolidated/ranked.callback.model';

@Component({
  selector: 'app-dashboard-exploit',
  imports: [
    NgIf,
    PaginationComponent,
    ResultComponent,
    DashboardResultExploitComponent,
    DashboardResultChatComponent,
    DashboardResultSocialComponent,
    DashboardResultsGeneralGridComponent,
    NgForOf
  ],
  templateUrl: './dashboard-exploit.component.html',
  animations: [fadeInDashboardItem]
})
export class DashboardExploitComponent implements OnInit, AfterViewInit {
  protected readonly Math = Math;
  protected readonly exploit_filter: FilterModel = JSON.parse(JSON.stringify(exploit_filters));

  query = ""
  isLoading = signal(false);
  firstTrigger = true
  result_count = 0;
  onToggleDiscussion: boolean = false;
  rankedResult: RankedCallbackModel = new RankedCallbackModel();

  constructor(protected helperService: HelperService, public appService: AppService, public dashboardService: DashboardService, private router: Router, private route: ActivatedRoute, private cdr: ChangeDetectorRef) {
  }

  get currentResultCount(): number {
    if (this.onToggleDiscussion) {
      return this.rankedResult.pageCount
    } else {
      return this.dashboardService.exploitCallbackModel.Page_Count ?? 0;
    }
  }

  ngAfterViewInit(): void {
    this.appService.updatePage(this.dashboardService.consolidatedParamModel.page)
  }

  ngOnInit(): void {
    this.dashboardService.exploitCallbackModel = {...this.dashboardService.exploitCallbackModel} as ExploitCallbackModel;
    this.result_count = this.dashboardService.exploitCallbackModel.Result.length
    combineLatest([this.route.queryParams, this.route.url])
      .pipe(distinctUntilChanged())
      .subscribe(([params, urlSegments]) => {
        this.onToggleDiscussion = false
        this.query = params['q'];
        this.dashboardService.consolidatedParamModel.q = params['q'] || '';
        this.dashboardService.consolidatedParamModel.page = params['page'] || '1';

        this.dashboardService.consolidatedParamModel.category = urlSegments.length ? urlSegments[urlSegments.length - 1].path : 'all';

        if (this.router.url.split('?')[0] === this.dashboardService.m_current_route) {
          return
        }
        if (this.router.url.split('?')[0] != this.dashboardService.m_current_route) {
          this.fetchSearchResults()
        } else if (this.firstTrigger && ((this.dashboardService.exploitCallbackModel.Result.length > 0))) {
          this.isLoading.set(false);
          this.query = this.dashboardService.consolidatedParamModel.q
        } else {
          this.cdr.detectChanges();
          this.fetchSearchResults()
        }
        this.firstTrigger = false
      });
  }

  fetchSearchResults(reset = false): void {
    if (reset)
      this.dashboardService.consolidatedParamModel.page = 1;

    if (!this.dashboardService.consolidatedParamModel.q) {
      this.isLoading.set(false);
      this.dashboardService.consolidatedParamModel.q = "";

      this.router.navigate([], {
        queryParams: {},
        queryParamsHandling: ''
      }).then();
    }

    this.isLoading.set(true);

    const cleanedParams: any = {};

    Object.entries(this.dashboardService.consolidatedParamModel).forEach(([key, value]) => {
      const isDefault =
        (key === 'daterange' && value === '') ||
        (key === 'network' && value === '') ||
        (value == null || value === '');

      if (!reset || !isDefault) {
        if (!isDefault) cleanedParams[key] = value;
      }
    });
    this.router.navigate([], {
      queryParams: cleanedParams,
      queryParamsHandling: reset ? '' : 'merge',
      replaceUrl: true,
      relativeTo: this.route
    }).then(() => {
      this.cdr.detectChanges();
    });

    if (reset) {
      this.isLoading.set(false);
      return;
    }
    this.dashboardService
      .fetchSearchResults<ExploitCallbackModel>('search/exploit', this.dashboardService.consolidatedParamModel)
      .pipe(switchMap(response => timer(1000).pipe(map(() => response))))
      .subscribe(response => {
        if (response.success && response.data) {
          this.dashboardService.exploitCallbackModel = response.data as ExploitCallbackModel;
        } else {
          this.dashboardService.exploitCallbackModel = new ExploitCallbackModel();
        }
        this.isLoading.set(false);
        this.result_count = this.dashboardService.exploitCallbackModel.Result.length;
      });
  }

  onPageChange(step: number) {
    this.dashboardService.consolidatedParamModel.page = step;
    this.fetchSearchResults();
  }

  onUpdateQuery(query: string) {
    this.dashboardService.consolidatedParamModel.q = query
  }

  resetFilters(_: void) {
    this.dashboardService.consolidatedParamModel.page = 1;
    this.dashboardService.consolidatedParamModel.category = "all";
    this.fetchSearchResults(true);
  }

  fetchSuggestion() {
    if (this.getTotalResults() > 0) {
      return;
    }
    this.isLoading.set(true);
    this.rankedResult = new RankedCallbackModel();
    this.dashboardService
      .fetchConsolidatedRankededResults('exploit/discussion', this.dashboardService.consolidatedParamModel)
      .pipe(switchMap(response => timer(500).pipe(map(() => response))))
      .subscribe(response => {
        if (response.success && response.data) {
          this.rankedResult = response.data;
        }
        this.isLoading.set(false);
        this.onToggleDiscussion = true;
        this.cdr.detectChanges();
      });
  }

  onToggleMenu(tab: string): void {
    if (tab == "Discussion") {
      this.onToggleDiscussion = true
      this.fetchSuggestion()
    } else {
      this.onToggleDiscussion = false
    }
  }

  reloadFilters(_: Record<string, string | null>) {
    this.fetchSearchResults();
  }

  protected readonly Category = Category;

  onToggleSort(sort: SortType) {
    let key;
    let order: 'asc' | 'desc' = 'asc';

    key = 'm_leak_date';

    if (sort === SortType.NEWEST_FIRST) {
      order = 'desc';
    } else if (sort === SortType.OLDEST_FIRST) {
      order = 'asc';
    } else if (sort === SortType.DEFAULT) {
      this.fetchSearchResults(true);
      return;
    }

    this.dashboardService.exploitCallbackModel.Result = this.helperService.sortByKey<any>(
      this.dashboardService.exploitCallbackModel.Result,
      key,
      order
    );

    this.cdr.detectChanges();
  }

  getTotalResults(): number {
    return this.rankedResult.result.length
  }

}
