    [StealerlogsSearchFilters.CREDITCARD]: 'Credit Card'
};

export interface StealerlogsAdvancedFilter {
    id: string;
    tag: StealerlogsSearchFilters;
    value: string;
    operator: '&&' | '||';
}

export interface PasswordSchemaFilter {
