import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, EMPTY, of, timer, forkJoin } from 'rxjs';
import { catchError, expand, filter, map, switchMap, takeWhile } from 'rxjs/operators';
import { SearchDynamicEmailCallbackModel } from '../model/api/email/search_dynamic_email_callback_model';
import { ConsolidatedLiveApis } from '../model/results/consolidated/consolidated.callback.model';
import { ConsolidatedLiveApiResults } from '../model/results/consolidated/consolidated.callback.model';
import { ConsolidatedScanResults } from '../model/results/consolidated/consolidated.callback.model';
import { ApiService } from './api.service';

@Injectable({
    providedIn: 'root'
})
export class ConsolidatedApiService {

    constructor(private http: HttpClient, private apiService: ApiService) {
    }

    private getLiveApiDetails(input: ConsolidatedLiveApis): { apiEndpoint: string, payload: any } {
        let payload: any;
        let endpoint: string;

        switch (input.type) {
            case 'user':
                endpoint = '/api/dynamic/user';
                payload = { text: { username: input.q1, email: input.q2 } };
                break;
            case 'social':
                endpoint = '/api/dynamic/social';
                payload = { text: { username: input.q1 } };
                break;
            case 'cracked':
                endpoint = '/api/dynamic/cracked';
                payload = { text: { playstore: input.q1 } };
                break;
            default:
                endpoint = '/api/dynamic/';
                payload = { text: { q1: input.q1, q2: input.q2 } };
                break;
        }
        return { apiEndpoint: endpoint, payload };
    }

    private fetchLiveApiResults(input: ConsolidatedLiveApis): Observable<any> {
        const { apiEndpoint, payload } = this.getLiveApiDetails(input);

        return this.http.post<any>(apiEndpoint, payload).pipe(
            expand(res => {
                const isPending = (res?.status === 'pending') || (res?.result?.status === 'busy') || (res?.result?.status === 'pending');
                const isFailedPending =
                    (res?.status === 'pending' || res?.result?.status === 'pending') &&
                    ((res?.result?.progress ?? res?.progress) === 0) &&
                    ((res?.result?.step ?? res?.step) === 'failed');

                return isPending && !isFailedPending
                    ? timer(2000).pipe(switchMap(() => this.http.post<any>(apiEndpoint, payload)))
                    : EMPTY;
            }),
            takeWhile(res => {
                const isPending = (res?.status === 'pending') || (res?.result?.status === 'busy') || (res?.result?.status === 'pending');
                const isFailedPending =
                    (res?.status === 'pending' || res?.result?.status === 'pending') &&
                    ((res?.result?.progress ?? res?.progress) === 0) &&
                    ((res?.result?.step ?? res?.step) === 'failed');
                return isPending && !isFailedPending;
            }, true),
            catchError(error => {
                return new Observable(observer => observer.error(error));
            })
        );
    }
    public runLiveApiSearch(inputs: ConsolidatedLiveApis[]): Observable<ConsolidatedLiveApiResults[]> {
        const searchObservables = inputs.map(input =>
            this.fetchLiveApiResults(input).pipe(
                map(res => {
                    let data: SearchDynamicEmailCallbackModel | null = null;
                    if (Array.isArray(res?.result)) {
                        data = { cards_data: res.result } as SearchDynamicEmailCallbackModel;
                    } else if (res?.success && res?.data) {
                        data = res.data;
                    } else if ((res as SearchDynamicEmailCallbackModel)?.cards_data) {
                        data = res as SearchDynamicEmailCallbackModel;
                    }
                    return {
                        input,
                        status: data && data.cards_data?.length ? 'success' : 'error',
                        resultData: data,
                        errorMessage: null,
                    } as ConsolidatedLiveApiResults;
                }),
                catchError(error => of({
                    input,
                    status: 'error',
                    resultData: null,
                    errorMessage: 'API request failed or data not found.',
                } as ConsolidatedLiveApiResults))
            )
        );

        return forkJoin(searchObservables);
    }

    public scan(target: string, scanType: 'basic' | 'seo' | 'repo'): Observable<ConsolidatedScanResults> {

        const endpoint = 'urlscan/domain';
        const payloadKey = 'domain';
        const payload = { [payloadKey]: target, scanType };

        return this.apiService
            .post<any>(endpoint, payload)
            .pipe(
                expand((res) => {
                    const isPending = res?.status === 'pending' || res?.step === 'queued' || res?.result?.status === 'pending';
                    if (isPending) {
                        return timer(5000).pipe(
                            switchMap(() =>
                                this.apiService.post<any>(endpoint, payload)
                            )
                        );
                    }
                    return EMPTY;
                }),
                takeWhile(
                    (res) => res?.status === 'pending' || res?.step === 'queued' || res?.result?.status === 'pending',
                    true
                ),
                map((res) => {
                    if (!res || res?.status === 'pending' || res?.step === 'queued') {
                        return null;
                    }
                    const meta = res?.result?.meta ?? null;
                    const grade = res?.result?.grade ?? res?.result?.meta?.grade ?? '—';

                    return {
                        domain: target,
                        scanType,
                        meta,
                        grade,
                        hasError: false,
                        errorMessage: ''
                    } as ConsolidatedScanResults;
                }),
                filter((res): res is ConsolidatedScanResults => res !== null),

                catchError((err) => {
                    return of({
                        domain: target,
                        scanType,
                        meta: null,
                        grade: '—',
                        hasError: true,
                        errorMessage: err?.error?.detail || `Failed to scan ${scanType}.`,
                    } as ConsolidatedScanResults);
                })
            );
    }
    public scanDomain(domain: string, scanType: 'basic' | 'seo'): Observable<ConsolidatedScanResults> {
        return this.scan(domain, scanType);
    }

    public scanForRepo(repoPath: string, scanType: 'repo'): Observable<ConsolidatedScanResults> {
        return this.scan(repoPath, scanType);
    }

}

import {Component, Input} from '@angular/core';
import {CommonModule} from '@angular/common';
import {Observable, merge, Subscription} from 'rxjs';
import {finalize, map} from 'rxjs/operators';
import {ConsolidatedApiService} from '../../../../../services/consolidated.api.service';
import {
  ConsolidatedScanResults,
  ConsolidatedLiveApiResults,
  ConsolidatedLiveApis
} from '../../../../../model/results/consolidated/consolidated.callback.model';
import {RouterLink} from '@angular/router';
import {scanAnimation} from '../../../../../animations/scan.animations';

type ScanKey = 'basic' | 'seo' | 'repo' | 'liveapi';
type PendingMsg = { status: 'pending'; progress?: number; step?: string };

@Component({
  selector: 'app-consolidated-scan',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './consolidated-scan.component.html',
  animations: [scanAnimation]
})
export class ConsolidatedScanComponent {
  @Input() isLoading!: boolean;
  today = new Date();
  isProcessing = false;
  isCollapsed = false;
  targetLabel = '';
  expectedTypes: ScanKey[] = [];

  private resultsByType: Partial<Record<Exclude<ScanKey, 'liveapi'>, ConsolidatedScanResults>> = {};
  private progressByType: Partial<Record<ScanKey, number>> = {};

  private liveApiEntities: ConsolidatedLiveApis[] = [];
  liveApiResults: ConsolidatedLiveApiResults[] = [];

  private scanSub?: Subscription;

  constructor(private api: ConsolidatedApiService) {}

  toggleCollapse(): void {
    this.isCollapsed = !this.isCollapsed;
  }

  clearResults(options?: { keepTargetLabel?: boolean; keepExpectedTypes?: boolean }): void {
    if (this.isProcessing && this.scanSub) {
      this.scanSub.unsubscribe();
      this.scanSub = undefined;
    }

    const keepTargetLabel = options?.keepTargetLabel ?? false;
    const keepExpectedTypes = options?.keepExpectedTypes ?? false;

    this.isProcessing = false;
    this.isCollapsed = false;

    this.resultsByType = {};
    this.progressByType = {};
    this.liveApiResults = [];
    this.liveApiEntities = [];

    if (!keepExpectedTypes) this.expectedTypes = [];
    if (!keepTargetLabel) this.targetLabel = '';
  }

  runScan(q: string): void {
    const input = (q || '').trim();
    if (!input) return;

    this.today = new Date();
    this.targetLabel = input;

    const isDomain = /^(https?:\/\/)?([a-z0-9-]+\.)+[a-z]{2,}$/i.test(input);
    if (!isDomain) return;

    const isRepo = input.includes('github.com/');
    this.expectedTypes = (isRepo ? ['repo', 'liveapi'] : ['basic', 'seo', 'liveapi']) as ScanKey[];

    this.resultsByType = {};
    this.progressByType = {};
    this.liveApiResults = [];
    this.isCollapsed = false;

    for (const t of this.expectedTypes) this.progressByType[t] = 0;

    this.isProcessing = true;
    this.liveApiEntities = this.extractLiveApiEntities(input);

    const scans: Array<{ t: ScanKey; o: Observable<any> }> = isRepo
      ? [{ t: 'repo', o: this.api.scanForRepo(input, 'repo') as any }]
      : [
          { t: 'basic', o: this.api.scanDomain(input, 'basic') as any },
          { t: 'seo', o: this.api.scanDomain(input, 'seo') as any }
        ];

    if (this.liveApiEntities.length) {
      scans.push({ t: 'liveapi', o: this.api.runLiveApiSearch(this.liveApiEntities) as any });
    } else {
      this.progressByType.liveapi = 100;
    }

    this.scanSub = merge(...scans.map(({ t, o }) => o.pipe(map(v => ({ t, v })))))
      .pipe(finalize(() => (this.isProcessing = false)))
      .subscribe({
        next: ({ t, v }: { t: ScanKey; v: any }) => {
          if (this.isPending(v)) {
            this.progressByType[t] = this.clamp(Number(v.progress ?? 0), 0, 100);
            return;
          }

          this.progressByType[t] = 100;

          if (t === 'liveapi') {
            this.liveApiResults = Array.isArray(v) ? v : [];
            return;
          }

          this.resultsByType[t as Exclude<ScanKey, 'liveapi'>] = {
            ...(v as ConsolidatedScanResults),
            scanType: (v as any)?.scanType || t
          } as ConsolidatedScanResults;
        },
        error: () => {
          this.isProcessing = false;
          this.expectedTypes = [];
          this.resultsByType = {};
          this.progressByType = {};
          this.liveApiResults = [];
        }
      });
  }

  private isPending(v: any): v is PendingMsg {
    return !!v && typeof v === 'object' && String(v.status || '').toLowerCase() === 'pending';
  }

  private clamp(n: number, min: number, max: number): number {
    if (!Number.isFinite(n)) return min;
    if (n < min) return min;
    if (n > max) return max;
    return n;
  }

  private extractLiveApiEntities(q: string): ConsolidatedLiveApis[] {
    const trimmed = (q || '').trim();
    if (!trimmed || /\s/.test(trimmed)) return [];

    const entities: ConsolidatedLiveApis[] = [];
    const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);

    if (isEmail) {
      const username = trimmed.split('@')[0];
      entities.push({type: 'user', q1: username, q2: trimmed} as ConsolidatedLiveApis);
      entities.push({type: 'social', q1: username} as ConsolidatedLiveApis);
      return entities;
    }

    if (trimmed.includes('play.google.com/store/apps')) {
      entities.push({type: 'cracked', q1: trimmed} as ConsolidatedLiveApis);
    }

    try {
      const url = new URL(trimmed);
      const hostname = url.hostname.replace('www.', '');
      const name = hostname.split('.')[0];
      if (name) entities.push({type: 'social', q1: name} as ConsolidatedLiveApis);
    } catch {
      let name = trimmed;
      if (name.includes('.')) name = name.split('.')[0];
      if (name) entities.push({type: 'social', q1: name} as ConsolidatedLiveApis);
    }

    return entities;
  }

  get showUi(): boolean {
    return this.isProcessing || this.domainResults.length > 0 || this.liveApiRows.length > 0;
  }

  get runningTypes(): ScanKey[] {
    return this.expectedTypes.filter(t => {
      if (t === 'liveapi') return (this.progressByType.liveapi ?? 0) < 100;
      return !this.resultsByType[t as Exclude<ScanKey, 'liveapi'>];
    });
  }

  get completedCount(): number {
    return this.expectedTypes.length - this.runningTypes.length;
  }

  get totalCount(): number {
    return this.expectedTypes.length;
  }

  get mergedProgress(): number {
    if (!this.totalCount) return 0;
    let sum = 0;
    for (const t of this.expectedTypes) sum += Number(this.progressByType[t] ?? 0);
    return Math.round(sum / this.totalCount);
  }

  get domainResults(): ConsolidatedScanResults[] {
    const out: ConsolidatedScanResults[] = [];
    const b = this.resultsByType.basic;
    const s = this.resultsByType.seo;
    if (b) out.push(b);
    if (s) out.push(s);
    return out;
  }

  get liveApiRows(): { platform: string; profile: string; url: string }[] {
    const rows: { platform: string; profile: string; url: string }[] = [];

    for (const r of this.liveApiResults || []) {
      const input = (r as any)?.input || {};
      const data = (r as any)?.resultData?.cards_data || [];

      for (const item of data) {
        const url = item?.m_url || item?.m_app_url || '';
        if (!url) continue;

        rows.push({
          platform: item?.m_base_url || item?.m_title || input?.type || 'N/A',
          profile: input?.q1 || '',
          url
        });
      }
    }

    return rows.slice(0, 25);
  }

  gradeBadgeClass(grade?: string): string {
    const g = (grade || '').toUpperCase();
    if (g === 'C' || g === 'D' || g === 'F') {
      return 'consolidated-scans-badge consolidated-scans-badge-warning';
    }
    return 'consolidated-scans-badge';
  }

  gradeText(grade?: string): string {
    const g = (grade || '—').toUpperCase();
    return `${g} Grade`;
  }
}
