@Component({
  selector: 'app-category-alert-report',
  imports: [NgFor, NgIf, CommonModule, FormsModule, AddCustomAlertComponent, FiltersComponent, ConfirmationPopupComponent, TooltipDirective, NgxPrintModule, AlertExportComponentComponent, EmptyResultComponent],
  templateUrl: './category-alert-report.component.html'
})
export class CategoryAlertReportComponent implements OnInit {
  filterModel: FilterModel = alert_filters;
  alerts: CategoryAlerts[] = []
  filteredAlerts: CategoryAlerts[] = []
  searchText: string = '';
  category: string = '';
  iocTypes: Record<string, string> = {};
  showCustomAlertPopup: boolean = false;
  showEditAlertPopup: boolean = false;
  isFilterOpen$: Observable<boolean>;
  selectedAlert!: AlertModel;
  isFlushAllConfirmationOpen = signal(false);
  isDeleteAlertConfirmationOpen = signal(false);
  selectedDeleteAlertId: string = '';
  importedAlert: AlertModel | null = null;
  alertToShowReport: AlertModel | null = null;

  @ViewChild('printBtn') printBtn!: ElementRef<HTMLButtonElement>;

  constructor(private router: Router, private route: ActivatedRoute, public appService: AppService, public sidebarService: SidebarService, private apiService: ApiService,
    private messageNotificationService: MessageNotificationService, protected licenseService: LicenseService, private helperService: HelperService) {
    this.isFilterOpen$ = this.sidebarService.sidebarState$;
  }
  ngOnInit(): void {
    this.route.url.pipe(
      map(segments => {
        if (segments && segments.length > 0) {
          return segments[segments.length - 1].path;
        }
        return '';
      })
    ).subscribe(lastSegment => {
      this.category = lastSegment;
    });
    this.iocTypes = { ...search_filter_labels };
    this.alerts = this.convertAlertsList(this.appService.userSessionData().alerts, this.category);
    this.filteredAlerts = this.alerts;
  }
  flushAll() {
    this.isFlushAllConfirmationOpen.set(true);
  }
  flushAllConfirmation(value: boolean) {
    this.isFlushAllConfirmationOpen.set(false);
    if (value === true) {
      this.apiService.post(`profile/alerts/delete/${this.category}`, null).subscribe({
        next: () => {
          this.getLatestAlerts();
          this.router.navigate(["/dashboard"], {});
        },
        error: (err) => {
          this.messageNotificationService.show(err?.error?.detail || 'Failed to delete')
        },
      });
    }
  }
  showAlertPopup(action: string, id: string) {
    switch (action) {
      case 'edit':
        const alert = this.appService.userSessionData().alerts.find(a => a.alert_id === id);
        if (alert) {
          this.selectedAlert = alert;
          this.showEditAlertPopup = true;
        }
        break;

      case 'add':
        this.showCustomAlertPopup = true;
        break;

      default:
        console.warn(`Unknown action: ${action}`);
        break;
    }
  }
  exportAlert(hash: string) {
    let apiUrl = '';
    switch (this.category) {
      case 'breach':
        apiUrl = hash ? `search/breach/stix/${hash}` : `search/breach`;
        break;
      case 'strategic':
        apiUrl = hash ? `search/strategic/stix/${hash}` : `search/strategic`;
        break;
      case 'defacement':
        apiUrl = hash ? `search/defacement/stix/${hash}` : `search/defacement`;
        break;
      case 'exploit':
        apiUrl = hash ? `search/exploit/stix/${hash}` : `search/exploit`;
        break;
      case 'social':
        apiUrl = hash ? `search/social/stix/${hash}` : `search/social`;
        break;
      case 'feed':
        apiUrl = hash ? `search/news/stix/${hash}` : `search/news`;
        break;
      default:
        this.router.navigate(['/']).then();
    }


    this.apiService.get<any>(apiUrl).subscribe({
      next: (response) => {
        if (response) {
          this.helperService.downloadstixJson(response);
        }
      },
      error: (err) => {
      }
    });


  }
  canExportstix() {
    const allowedCategories = [
      'breach',
      'strategic',
      'general',
      'defacement',
      'exploit',
      'social',
      'feed'
    ];
    return allowedCategories.includes(this.category);
  }
  cancleAlertPopup(refresh: boolean) {
    if (refresh)
      this.getLatestAlerts();
    this.filteredAlerts = this.alerts;
    this.showCustomAlertPopup = false;
    this.showEditAlertPopup = false;
  }
  deleteAlertConfirmation(id: string) {
    this.selectedDeleteAlertId = id;
    this.isDeleteAlertConfirmationOpen.set(true);
  }
  deleteCustomAlert(confirmed: boolean, id: string) {
    if (confirmed) {
      this.apiService.post('alert/delete', id).subscribe({
        next: () => {
          this.messageNotificationService.show('Alert deleted successfully!', 'success');
          this.getLatestAlerts();
        },
        error: (err) => {
          const mess = err?.error?.detail || 'delete alert failed'
          this.messageNotificationService.show(mess)
        },
      });
    }
    else {
      this.selectedDeleteAlertId = '';
    }
  }
  getLatestAlerts() {
    this.apiService.get<any>('profile/alerts').subscribe({
      next: response => {
        this.appService.userSessionData().alerts = response
        this.alerts = this.convertAlertsList(this.appService.userSessionData().alerts, this.category);
        this.filteredAlerts = this.alerts;
      }
    })
  }
  seeDetailReprot(alertId: string) {
    this.alertToShowReport =
      this.appService
        .userSessionData()
        ?.alerts
        ?.find(a => a.alert_id === alertId) || null;

    if (!this.alertToShowReport) return;
    if (this.alertToShowReport) {
      this.alertToShowReport.report_seen = true;
      this.apiService.post('alert/seen', [this.alertToShowReport]).subscribe({
      });

      setTimeout(() => {
        this.printBtn.nativeElement.click();
      }, 0);
    }
  }
  seeDetails(id: string, hash: string) {
    this.licenseService.loadLicenses().subscribe(licenses => {
      const hasEnterprise = licenses.includes('enterprise');

      if (hasEnterprise) {

        const alerts = this.appService.userSessionData().alerts;
        const _alert = alerts.find(a => a.alert_id === id);
        if (_alert?.type) {
          const value = _alert.ioc_value || '-';
          let scanType: string;
          let route: string = '/dashboard/scanner/basic-scan';

          switch (_alert.type.toLowerCase()) {
            case "advance scanning":
              scanType = "advance";
              route = "/dashboard/scanner/port-scan";
              this.router.navigate([route], {
                queryParams: { page: 1, domain: encodeURIComponent(value), canType: scanType }
              });
              break;

            case "seo scanning":
              scanType = "seo";
              route = "/dashboard/scanner/seo-scan";
              this.router.navigate([route], {
                queryParams: { page: 1, domain: encodeURIComponent(value), canType: scanType }
              });
              break;

            case "repo scanning":
              scanType = "repo";
              route = "/dashboard/scanner/repository-scan";
              this.router.navigate([route], {
                queryParams: { page: 1, domain: encodeURIComponent(value), canType: scanType }
              });
              break;
            case "email-breach":
              const _username = value.split('@')[0];
              scanType = "repo";
              route = "/dashboard/api/email-breach";
              this.router.navigate([route], {
                queryParams: { username: _username, email: value }
              });
              break;
            case "playstore-scanning":
              scanType = "repo";
              route = "/dashboard/api/playstore-scanner";
              this.router.navigate([route], {
                queryParams: { playstore: value }
              });
              break;
            case "social-scanner":
              scanType = "repo";
              route = "/dashboard/api/social-scanner";
              this.router.navigate([route], {
                queryParams: { username: value }
              });
              break;
            case "stealerlogs":
              route = "/dashboard/stealerlogs/credential";
              const queryParams: any = {
                q: "",
                page: 1,
                category: "credential",
                fullsearch: true,
                matchtype: "or",
                must: false
              };
              if (this.isDomain(value)) {
                queryParams.domain = value;
              } else {
                queryParams.user = value;
              }
              this.router.navigate([route], { queryParams });
              break;
            default:
              this.router.navigate([`/dashboard/${this.category}/all/${hash}`]);
              break;
          }


        }
        if (_alert) {
          _alert.report_seen = true;
          this.apiService.post('alert/seen', [_alert]).subscribe({
            next: () => {
            },
            error: (err) => {
            },
          });
        }
        else (alert("null"))} else {
        this.messageNotificationService.show("Please purchase enterprise license to view reports")
      }
    });

  }

  convertAlertsList(alerts: AlertModel[], targetType: string): CategoryAlerts[] {
    if (!alerts || alerts.length === 0) {
      return [];
    }
    const filteredAlerts = alerts.filter(alert => alert.type === targetType);
    return filteredAlerts.map(alert => this.convertToCategoryAlert(alert));
  }

  convertToCategoryAlert(alert: AlertModel): CategoryAlerts {
    const entity = alert.ioc_value || 'N/A';

    return {
      id: alert.alert_id || '',
      seen: alert.report_seen || false,
      custom: alert.custom_alert || false,
      risk: this.getRiskLevel(alert.type!),
      category: alert.type || 'unknown',
      title: alert.title || 'No Title',
      description: alert.description || 'No description provided.',
      hash: alert.data_hash || 'NO_HASH',
      source: alert.source || 'N/A',
      url: alert.url || 'N/A',
      entity: entity,

      allIOC: alert.all_ioc || [],
      detectedOn: alert.first_seen || new Date(),
    };
  }
  getRiskLevel(type: string): string {
    const normalized = type.toLowerCase();
    switch (normalized) {
      case 'general':
      case 'seo scanning':
        return 'Low';

      case 'breach':
      case 'exploit':
      case 'feed':
      case 'playstore-scanning':
      case 'social-scanner':
      case 'email-breach':
      case 'stealerlogs':
      case 'software-scanning':
        return 'Critical';

      case 'defacement':
      case 'advanced scanning':
      case 'repo scanning':
        return 'High';

      case 'social':
      case 'discussion':
        return 'Medium';

      default:
        return 'Unknown';
    }
  }
  sliceString(text: string, maxLength: number): string {
    if (typeof text !== 'string' || text === null || text === undefined) {
      return '';
    }
    if (text.length <= maxLength) {
      return text;
    }
    return text.slice(0, maxLength) + '...';
  }


  getFilteredIocs(allIOC: AlertAllIoc[]): { label: string, count: number }[] {
    if (!allIOC || allIOC.length === 0) {
      return [];
    }

    const mergedIocMap = new Map<string, AlertAllIoc>();

    for (const ioc of allIOC) {
      const existingIoc = mergedIocMap.get(ioc.name);

      if (existingIoc) {
        if (ioc.values.length > existingIoc.values.length) {
          mergedIocMap.set(ioc.name, ioc);
        }
      } else {
        mergedIocMap.set(ioc.name, ioc);
      }
    }
    return Array.from(mergedIocMap.values())
      .filter(ioc => this.iocTypes.hasOwnProperty(ioc.name))
      .map(ioc => ({
        label: this.iocTypes[ioc.name],
        count: ioc.values.length
      }));
  }
  countUniqueSources(alerts: CategoryAlerts[]): number {
    const uniqueSources = new Set<string>();
    for (const alert of alerts) {
      if (alert.source) {
        uniqueSources.add(alert.source);
      }
    }
    return uniqueSources.size;
  }
  getLatestDetectedDate(alerts: CategoryAlerts[]): string {
    const validDates = alerts
      .map(alert => alert.detectedOn instanceof Date
        ? alert.detectedOn
        : new Date(alert.detectedOn))
      .filter(date => !isNaN(date.getTime())); // ensures valid date

    if (validDates.length === 0) return '-';

    const latestDate = validDates.reduce((latest, current) =>
      current.getTime() > latest.getTime() ? current : latest
    );

    const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

    return `${dayNames[latestDate.getDay()]}, ${latestDate.getDate()} ${monthNames[latestDate.getMonth()]} ${latestDate.getFullYear()}`;
  }

  getTotalUniqueIocValueCount(alerts: CategoryAlerts[]): number {
    if (!alerts || alerts.length === 0) {
      return 0;
    }
    const totalUniqueValues = new Set<string>();

    for (const alert of alerts) {
      const allIOC: AlertAllIoc[] = alert.allIOC || [];

      if (allIOC.length === 0) {
        continue;
      }
      const mergedIocMap = new Map<string, AlertAllIoc>();

      for (const ioc of allIOC) {
        const existingIoc = mergedIocMap.get(ioc.name);

        if (existingIoc && ioc.values.length > existingIoc.values.length) {
          mergedIocMap.set(ioc.name, ioc);
        } else if (!existingIoc) {
          mergedIocMap.set(ioc.name, ioc);
        }
      }
      Array.from(mergedIocMap.values())
        .filter(ioc => this.iocTypes.hasOwnProperty(ioc.name))
        .forEach(ioc => {
          ioc.values.forEach(value => {
            if (value) {
              totalUniqueValues.add(value);
            }
          });
        });
    }

    return totalUniqueValues.size;
  }
  getNewAlertCount(): number {
    return this.filteredAlerts.filter(alert => !alert.seen).length;
  }
  applyFilter(filters: Record<string, string | null>) {
    const range = filters['daterange'];

    if (!range) {
      this.filteredAlerts = [...this.alerts];
      return;
    }

    const [startStr, endStr] = range.split(',');
    const startDate = new Date(startStr);
    const endDate = new Date(endStr);

    this.filterByDate(startDate, endDate);
  }
  filterByDate(start: Date, end: Date) {
    const inclusiveEnd = new Date(end);
    inclusiveEnd.setHours(23, 59, 59, 999);

    this.filteredAlerts = this.alerts.filter(alert => {
      const lastSeenDate = new Date(alert.detectedOn);
      return lastSeenDate >= start && lastSeenDate <= inclusiveEnd;
    });
  }
  isDomain(value: string): boolean {
    if (!value) return false;

    value = value.replace(/https?:\/\//, "").replace(/^www\./, "");

    const domainRegex = /^[a-zA-Z0-9-]+\.[a-zA-Z]{2,}(?:\.[a-zA-Z]{2,})*$/;

    return domainRegex.test(value);
  }

  onFileUpload(event: any) {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();

    reader.onload = () => {
      try {
        const jsonData = JSON.parse(reader.result as string);

        if (Array.isArray(jsonData)) {
          this.messageNotificationService.show(
            'Only one STIX bundle is allowed per upload'
          );
          return;
        }

        this.importedAlert = this.validateAlert(jsonData);

        this.apiService.post('alert/add', this.importedAlert).subscribe({
          next: () => {
            this.getLatestAlerts();
            this.messageNotificationService.show('Alert imported successfully!', 'success');
          },
          error: (err) => {
            const mess = err?.error?.detail || 'Add alert failed';
            this.messageNotificationService.show(mess);
          },
        });

      } catch (error: any) {
        this.messageNotificationService.show(error.message || 'Invalid JSON file');
      }
    };

    reader.readAsText(file);
  }

  validateAlert(data: any): AlertModel {
    if (!data || typeof data !== 'object') {
      throw new Error('Invalid JSON structure');
    }

    if (data.type !== 'bundle' || !Array.isArray(data.objects)) {
      throw new Error('Uploaded file must be a STIX 2.1 bundle');
    }

    const report = data.objects.find((o: any) => o.type === 'report');

    if (!report) {
      throw new Error('STIX bundle must contain a report object');
    }

    const requiredReportFields = ['id', 'name', 'created', 'modified'];
    for (const field of requiredReportFields) {
      if (!report[field]) {
        throw new Error(`Report missing required field: ${field}`);
      }
    }

    const firstSeen = new Date(report.created);
    const lastSeen = new Date(report.modified);

    if (isNaN(firstSeen.getTime()) || isNaN(lastSeen.getTime())) {
      throw new Error('Invalid report timestamps');
    }

    return {
      type: report.type ?? 'report',

      data_hash: '',
      ioc_type: 'stix-bundle',
      ioc_value: report.name,

      first_seen: firstSeen,
      last_seen: lastSeen,

      status: 'active',

      title: report.name ?? '',
      description: report.description ?? '',

      url:
        report.external_references?.find((r: any) => r.url)?.url ?? '',

      source:
        report.external_references?.[0]?.source_name ?? 'import',

      all_ioc: data.objects,
      content_types: report.labels ?? [],
    };
  }

}

import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { NgFor, NgIf } from '@angular/common';
import { LicenseName } from '../../../../shared/model/licenses/license.rules';
import { TenantTeamModel } from '../../../../shared/model/tenant/tenant.model';
import { ApiService } from '../../../../shared/services/api.service';
import { popupAnimation, overlayAnimation } from '../../../../shared/animations/popup.animations';
import { AppService } from '../../../../services/core/app/app.service';
import { LicenseService } from '../../../../services/licenses/licenses.service';

@Component({
  selector: 'app-add-tenant',
  imports: [FormsModule, NgFor, NgIf],
  templateUrl: './add-tenant.component.html',
  animations: [popupAnimation, overlayAnimation]
})
export class AddTenantComponent implements OnInit {
  @Output() closs = new EventEmitter<void>();
  @Output() accountAdded = new EventEmitter<void>();

  licenseList = Object.values(LicenseName);
  licenses = ['free', 'osint_basic', 'osint_advanced', 'social_mapper', 'pentester', 'maintainer', 'enterprise'];
  isAdmin: boolean = false;

  model: TenantTeamModel = {
    username: '',
    email: '',
    password: '',
    role: 'analyst',
    status: 'active',
    subscription: false,
    licenses: []
  };
  errorText: string = "";
  usernamePattern = /^[A-Za-z][A-Za-z0-9_-]{7,19}$/;
  usernameSuggestion: string = "";

  constructor(
    public apiService: ApiService,
    private appService: AppService,
    protected licenseService: LicenseService
  ) {
  }

  ngOnInit(): void {
    this.isAdmin = this.appService.userSessionData().user.role === 'admin';
    this.isAdmin ? (this.model.role = 'member') : (this.model.role = 'analyst');
  }

  onSubmit() {
    this.errorText = '';
    this.usernameSuggestion = '';

    if (!this.model.username) {
      this.errorText = 'Username is required';
      return;
    }
    if (!this.validateUsername()) {
      return;
    }
    if (!this.model.email && this.model.role != "demo") {
      this.errorText = 'Email is required';
      return;
    }
    if (!this.model.password) {
      this.errorText = 'Password is required';
      return;
    }

    if (!this.model.licenses || this.model.licenses.length === 0) {
      this.model.licenses = [LicenseName.FREE];
    }

    const endpoint = this.isAdmin ? 'tenant/create/user' : 'tenant/create/user';
    this.apiService.post(endpoint, this.model).subscribe({
      next: () => {
        this.accountAdded.emit();
        this.onClose();
      },
      error: err => {
        this.errorText = err?.error?.detail || 'Failed to create user';
      }
    });
  }

  validateUsername(): boolean {
    if (this.usernamePattern.test(this.model.username)) {
      return true;
    }
    const suggestions: string[] = [];
    const base = this.model.username || '';
    let counter = 1;
    while (suggestions.length < 4 && counter < 50) {
      const suffix = counter.toString();
      let s = base.toLowerCase();
      if (!/^[A-Za-z]/.test(s)) {
        s = 'u' + s;
      }
      s = s.replace(/[^A-Za-z0-9_-]/g, '');
      if (s.length > 20 - suffix.length) {
        s = s.slice(0, 20 - suffix.length);
      }
      if (s.length < 8 - suffix.length) {
        s = s.padEnd(8 - suffix.length, '0');
      }
      const suggestion = s + suffix;
      if (this.usernamePattern.test(suggestion) && !suggestions.includes(suggestion)) {
        suggestions.push(suggestion);
      }
      counter++;
    }
    this.usernameSuggestion = suggestions.length
      ? 'Username already taken. Suggested usernames: ' + suggestions.join(', ')
      : 'Username already taken.';
    this.errorText = 'Invalid username';
    return false;
  }

  onClose() {
    this.closs.emit();
  }

  get hasFullLicenseAccess(): boolean {
    return this.appService.userSessionData()?.user?.role === 'admin';
  }

  get tenantLicenses(): string[] {
    return this.appService.userSessionData()?.tenant?.licenses ?? [];
  }

  get visibleTenantLicensesCount(): number {
    if (this.hasFullLicenseAccess) {
      return this.licenseList.filter(
        license => this.licenseService.getLicenseLabel(license) !== 'maintainer'
      ).length;
    }

    return this.licenseList.filter(
      license =>
        this.tenantLicenses.includes(license) &&
        this.licenseService.getLicenseLabel(license) !== 'maintainer'
    ).length;
  }

  toggleTenantLicense(tenant: any, license: LicenseName): void {
    if (!tenant.licenses) {
      tenant.licenses = [];
    }

    const index = tenant.licenses.indexOf(license);
    if (index > -1) {
      tenant.licenses.splice(index, 1);
    } else {
      tenant.licenses.push(license);
    }
  }
}

import { Injectable } from '@angular/core';
import { Resolve } from '@angular/router';
import { Observable, of } from 'rxjs';
import { catchError, shareReplay, tap } from 'rxjs/operators';
import { ApiService } from '../services/api.service';
import { userSessionData } from '../model/company-profile/node.model';
import { AppService } from '../../services/core/app/app.service';

@Injectable({ providedIn: 'root' })
export class NodeResolver implements Resolve<userSessionData> {
  private cache$?: Observable<userSessionData>;

  constructor(private apiService: ApiService, private appService: AppService) {
  }

  resolve(): Observable<userSessionData> {
    return this.apiService
    .post<userSessionData>('get/tenant/node', {})
    .pipe(
      catchError(_ => {
        return of(null as any);
      }),
      tap(sessionData => {
        if (sessionData) {
          this.appService.userSessionData.set(sessionData);
        }
      }),
      shareReplay(1)
    );
  }
}

import { Component, HostListener, OnInit, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ApiService } from '../../../../shared/services/api.service';
import { HttpHeaders } from '@angular/common/http';
import { NgFor } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { User } from '../../../../shared/model/tenant/tenant.model';
import { fadeInDashboardItem } from '../../../../shared/animations/dashboard.item.animation';
import { LicenseName } from '../../../../shared/model/licenses/license.rules';
import { AddTenantComponent } from "../add-tenant/add-tenant.component";
import { ConfirmationPopupComponent } from '../../../../shared/partials/confirmation-popup/confirmation-popup.component';
import { AppService } from '../../../../services/core/app/app.service';
import { TooltipDirective } from '../../../../shared/directive/tooltip-directive.directive';
import { finalize, switchMap, tap } from 'rxjs';
import { NodeResolver } from '../../../../shared/resolvers/session-data-resolver.service';
import { LicenseService } from '../../../../services/licenses/licenses.service';

@Component({
  selector: 'app-view-profile',
  imports: [NgFor, FormsModule, CommonModule, AddTenantComponent, ConfirmationPopupComponent, TooltipDirective],
  animations: [fadeInDashboardItem],
  templateUrl: './manage-profile.component.html'
})
export class ManageProfileComponent implements OnInit {

  users: User[] = [];
  licenseList = Object.values(LicenseName);
  isLoading = true;
  selectedUserId: string | null = null;
  expandedUserIndex: number | null = null;
  showAddTenantPopup: boolean = false;
  isDeleteConfirmationOpen = signal<boolean>(false);
  userToDelete: User | null = null;

  constructor(public apiService: ApiService, protected appService: AppService, private nodeResolver: NodeResolver, protected licenseService: LicenseService) {
  }

  ngOnInit(): void {
    const headers = new HttpHeaders({});
    this.apiService.post<User[]>('users', headers).subscribe({
      next: (data) => {
        this.users = data;
        this.isLoading = false;
      },
      error: (err) => {
        this.isLoading = false;
      },
    });
  }

  toggleExpandedUser(index: number): void {
    this.expandedUserIndex = this.expandedUserIndex === index ? null : index;
  }

  updateUser(user: User) {
    if (!user.licenses || user.licenses.length === 0) {
      user.licenses = [LicenseName.FREE];
    }

    this.isLoading = true;

    this.apiService.post('update/user', user).pipe(
      switchMap(() => this.nodeResolver.resolve()),
      finalize(() => (this.isLoading = false))
    ).subscribe({
      next: (_) => {
      },
      error: () => {
      }
    });
  }

  @HostListener('document:click', ['$event'])
  handleClickOutside(event: MouseEvent) {
    const target = event.target as HTMLElement;
    if (!target.closest('.action-menu')) {
      this.selectedUserId = null;
    }
  }

  isLicenseDisabled(user: any, license: LicenseName): boolean {
    return false;
  }

  toggleUserLicense(user: any, license: LicenseName) {
    if (!user.licenses) user.licenses = [];

    if (user.licenses.includes(license)) {
      user.licenses = user.licenses.filter((l: LicenseName) => l !== license);
      return;
    }

    if (license === LicenseName.FREE || license === LicenseName.ENTERPRISE) {
      user.licenses = [license];
      return;
    }

    user.licenses = user.licenses.filter(
      (l: LicenseName) => l !== LicenseName.FREE && l !== LicenseName.ENTERPRISE
    );

    if (license === LicenseName.OSINT_BASIC) {
      user.licenses = user.licenses.filter((l: LicenseName) => l !== LicenseName.OSINT_ADVANCED);
    }

    if (license === LicenseName.OSINT_ADVANCED) {
      user.licenses = user.licenses.filter((l: LicenseName) => l !== LicenseName.OSINT_BASIC);
    }

    user.licenses.push(license);
  }


  deleteUser(user: User) {
    this.userToDelete = user;
    this.isDeleteConfirmationOpen.set(true);
  }

  confirmDeleteUser(value: boolean) {
    this.isDeleteConfirmationOpen.set(false);
    if (!value || !this.userToDelete) {
      this.userToDelete = null;
      return;
    }

    this.isLoading = true;

    this.apiService.post('delete/user', this.userToDelete).pipe(
      switchMap(() => this.apiService.post<User[]>('users', new HttpHeaders({}))),
      tap(data => this.users = data),
      switchMap(() => this.nodeResolver.resolve()),
      finalize(() => {
        this.isLoading = false;
        this.userToDelete = null;
      })
    ).subscribe();
  }


  getUserLicensesLabel(user: any): string {
    if (!user.licenses || user.licenses.length === 0) return 'None';
    const names = user.licenses.map((l: LicenseName) => this.licenseService.getLicenseLabel(l)).join(', ');
    return (names.length <= 15) ? names : names.slice(0, 15) + ('...');
  }

  addtenant() {
    this.showAddTenantPopup = true;
  }

  clossAddTenant() {
    this.showAddTenantPopup = false;
  }
  setStatus(user: User, status: 'active' | 'disable') {
    user.status = status;
  }


  protected readonly JSON = JSON;
}

import { Component, HostListener, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HttpHeaders } from '@angular/common/http';
import { FormsModule } from '@angular/forms';
import { NgFor } from '@angular/common';

import { ApiService } from '../../../../shared/services/api.service';
import { LicenseName } from '../../../../shared/model/licenses/license.rules';
import { fadeInDashboardItem } from '../../../../shared/animations/dashboard.item.animation';
import { TenantStatus, TenantStatusValues } from '../../../../shared/model/tenant/tenant.model';
import { LicenseService } from '../../../../services/licenses/licenses.service';

@Component({
  selector: 'app-view-tenant',
  standalone: true,
  imports: [NgFor, FormsModule, CommonModule],
  animations: [fadeInDashboardItem],
  templateUrl: './view-tenant.component.html',
})
export class ViewTenantComponent implements OnInit {
  tenants: any[] = [];
  licenseList = Object.values(LicenseName);
  isLoading = true;
  selectedTenantId: string | null = null;
  TenantStatus = TenantStatusValues;

  constructor(public apiService: ApiService, protected licenseService: LicenseService) {
  }

  ngOnInit(): void {
    const headers = new HttpHeaders({});
    this.apiService.post<any[]>('tenants/get', headers).subscribe({
      next: (data) => {
        this.tenants = (data || []).map((tenant: any) => ({
          ...tenant,
          verified: tenant.verified ?? false,
          user_quota: tenant.user_quota ?? 0,
          status:
            tenant.status === TenantStatusValues.ONBOARDING ||
              tenant.status === TenantStatusValues.ACTIVE ||
              tenant.status === TenantStatusValues.DISABLE
              ? tenant.status
              : TenantStatusValues.ACTIVE,
          licenses:
            tenant.licenses && tenant.licenses.length
              ? tenant.licenses
              : [LicenseName.FREE],
        }));
        this.isLoading = false;
      },
      error: (err) => {
        this.isLoading = false;
      },
    });
  }

  getStatusLabel(status: TenantStatus): string {
    switch (status) {
      case TenantStatusValues.ONBOARDING:
        return 'Disable';
      case TenantStatusValues.ACTIVE:
        return 'Active';
      case TenantStatusValues.DISABLE:
        return 'Disable';
      default:
        return '';
    }
  }

  getStatusClass(status: TenantStatus): string {
    if (status === TenantStatusValues.ACTIVE) {
      return 'status-active';
    }
    if (status === TenantStatusValues.DISABLE) {
      return 'status-disabled';
    }
    return 'status-other';
  }

  updateTenant(tenant: any): void {
    if (!tenant.licenses || tenant.licenses.length === 0) {
      tenant.licenses = [LicenseName.FREE];
    }

    this.isLoading = true;

    this.apiService.post('update/tenants', tenant).subscribe({
      next: () => {
        this.isLoading = false;
      },
      error: (err) => {
        this.isLoading = false;
      },
    });
  }

  @HostListener('document:click', ['$event'])
  handleClickOutside(event: MouseEvent): void {
    const target = event.target as HTMLElement;
    if (!target.closest('.action-menu')) {
      this.selectedTenantId = null;
    }
  }

  toggleTenantLicense(tenant: any, license: LicenseName): void {
    if (!tenant.licenses) {
      tenant.licenses = [];
    }

    const index = tenant.licenses.indexOf(license);
    if (index > -1) {
      tenant.licenses.splice(index, 1);
    } else {
      tenant.licenses.push(license);
    }
  }

  getTenantLicensesLabel(tenant: any): string {
    if (!tenant.licenses || tenant.licenses.length === 0) {
      return 'None';
    }

    const names = tenant.licenses
      .map((l: LicenseName) => this.licenseService.getLicenseLabel(l))
      .join(', ');

    return names.length <= 15 ? names : names.slice(0, 15) + '...';
  }

  protected readonly JSON = JSON;
}

