        <ng-container *ngIf="groupedIocs.length > 0; else emptyState">
          <section class="ioc-report-findings">
            <div class="ioc-report-category" *ngFor="let category of groupedIocs; trackBy: trackByCategory; let i = index" @fadeInDashboardItem>
