                      <i class="bi" [ngClass]="copiedValue() === item.value ? 'bi-clipboard-check-fill' : 'bi-clipboard'"></i>
                      <span class="ioc-report-copy-text">{{ copiedValue() === item.value ? 'Copied!' : 'Copy' }}</span>
