  private makeHeaderFooterHooks(payload: GraphReportPayload, meta: { generatedAt: string; kindLabel: string }): { didDrawPage: (data: any) => void; drawHeader: (doc: jsPDF, section: string) => void; drawFooter: (doc: jsPDF, meta: any) => void } {
    const drawHeader = (doc: jsPDF, section: string) => {
      const W = this.getPageW(doc);
      doc.setFillColor(248, 250, 252);
      doc.rect(0, 0, W, 54, 'F');
      doc.setDrawColor(226, 232, 240);
      doc.line(40, 54, W - 40, 54);
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.setTextColor(15, 23, 42);
      doc.text(payload.title || 'Network Report', 40, 34);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(9);
      doc.setTextColor(71, 85, 105);
      doc.text(section, W - 40, 34, { align: 'right' });
    };

    const drawFooter = (doc: jsPDF, meta2: any) => {
      const W = this.getPageW(doc);
      const H = this.getPageH(doc);
      const pageNo = doc.getCurrentPageInfo().pageNumber;
      const total = doc.getNumberOfPages();
      doc.setDrawColor(226, 232, 240);
      doc.line(40, H - 54, W - 40, H - 54);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(8);
      doc.setTextColor(100, 116, 139);
      doc.text(`${meta2.kindLabel} • ${payload.sessionName || '—'} • ${meta2.generatedAt}`, 40, H - 32);
      doc.text(`Page ${pageNo} of ${total}`, W - 40, H - 32, { align: 'right' });
    };

    const didDrawPage = (data: any) => {
      const pageNo = data?.pageNumber ?? docPageNumberSafe(data?.doc);
      const section = pageNo === 1 ? 'Overview' : 'Details';
      const d = data?.doc as jsPDF;
      drawHeader(d, section);
      drawFooter(d, meta);
    };

    const docPageNumberSafe = (d?: jsPDF): number => {
      try { return d?.getCurrentPageInfo().pageNumber ?? 1; } catch { return 1; }
    };

    return { didDrawPage, drawHeader, drawFooter };
  }

  private buildTypeComposition(nodes: GraphReportNode[]): { type: string; count: number }[] {
    const counts: Record<string, number> = {};
    nodes.forEach(n => {
      const key = this.normalizeNodeType(n.type || 'unknown');
      counts[key] = (counts[key] ?? 0) + 1;
    });
    return Object.entries(counts).map(([type, count]) => ({ type, count })).sort((a, b) => b.count - a.count);
  }

  private normalizeNodeType(type: string): string {
    const normalized = String(type || '').trim().toLowerCase();
    if (!normalized) {
      return 'unknown';
    }
    if (normalized === 'circularimage' || normalized === 'icon') {
      return 'entity';
    }
    if (normalized === 'dot') {
      return 'property';
    }
    return normalized;
  }

  private extractSocialPlatformCounts(payload: GraphReportPayload): Array<{ name: string; count: number }> {
    if (payload.graphKind !== 'social') {
      return [];
    }
    const counts = new Map<string, number>();
    payload.nodes.forEach(node => {
      const id = String(node.id ?? '');
      const match = id.match(/^platform-[^|]+\|([^|]+)\|/i);
      if (match?.[1]) {
        const name = match[1].toLowerCase();
        counts.set(name, (counts.get(name) ?? 0) + 1);
      }
    });
    return Array.from(counts.entries())
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name));
  }

  private makeMeta(payload: GraphReportPayload): { generatedAt: string; kindLabel: string } {
    const generatedAt = new Date(payload.generatedAtIso).toLocaleString();
    const kindLabel = payload.graphKind === 'cti' ? 'CTI Network' : 'Social Network';
    return { generatedAt, kindLabel };
  }

  private isJpegDataUrl(dataUrl?: string): boolean {
    return typeof dataUrl === 'string' && /^data:image\/jpeg;base64,/.test(dataUrl);
  }

  private fitRectToPage(doc: jsPDF, left: number, top: number, right: number, bottom: number): { x: number; y: number; w: number; h: number } {
    const W = this.getPageW(doc);
    const H = this.getPageH(doc);
    return { x: left, y: top, w: W - left - right, h: H - top - bottom };
  }

  private fitRect(_: jsPDF, maxW: number, maxH: number, x: number, y: number): { x: number; y: number; w: number; h: number } {
    return { x, y, w: maxW, h: maxH };
  }

  private getPageW(doc: jsPDF): number {
    return doc.internal.pageSize.getWidth();
  }

  private getPageH(doc: jsPDF): number {
    return doc.internal.pageSize.getHeight();
  }

  private docToBytes(doc: jsPDF): Uint8Array {
    const buf = doc.output('arraybuffer');
    return new Uint8Array(buf);
  }

  private buildSafeFilename(payload: GraphReportPayload): string {
    const date = new Date(payload.generatedAtIso).toISOString().slice(0, 10);
    const base = `${payload.graphKind}-${payload.sessionName || 'session'}-${date}-${payload.title || 'report'}`;
    return base.replace(/[^a-z0-9_-]/gi, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').toLowerCase();
  }

  private downloadText(content: string, mimeType: string, filename: string): void {
    const blob = new Blob([content], { type: mimeType });
    this.downloadBlob(blob, filename);
  }

  private downloadBinary(content: Uint8Array, mimeType: string, filename: string): void {
    const blob = new Blob([content], { type: mimeType });
    this.downloadBlob(blob, filename);
  }

  private downloadBlob(blob: Blob, filename: string): void {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }
}

import { Injectable, signal, computed } from '@angular/core';
import { NetworkData, Job, PlatformResult, CustomEntity, TabState, SerializableTabState, Tab, NetworkNode, GraphPlatformBatch } from '../../../../shared/model/social/social-scan.models';
import { ApiService } from '../../../../shared/services/api.service';
import { GraphReportExportService, GraphReportExportType, GraphReportPayload } from '../../shared/services/graph-report-export.service';

@Injectable({
  providedIn: 'root',
})
export class TabManagerService {
  private readonly maxTabsAllowed = 5;
  private readonly graphType = 'social';
  private static tabCounter = 1;
  private hasLoadedState = false;
  private hasPendingSave = false;
  private autosaveIntervalId: any;
  private lastSavedSignature = '';

  tabs = signal<Tab[]>([]);
  activeTabId = signal<string>('');
  editingTabId = signal<string | null>(null);

  activeTab = computed(() => this.tabs().find(t => t.id === this.activeTabId()));

  constructor(
    private api: ApiService,
    private graphReportExport: GraphReportExportService
  ) {
    this.startPeriodicSave();
    this.loadState();
  }

  private createNewState(): TabState {
    return {
      searchTerm: signal(''),
      homeMenuSearchTerm: signal(''),
      jobs: signal<Job[]>([]),
      networkData: signal<NetworkData>({ nodes: [], edges: [] }),
      scanResults: signal(new Map<string, PlatformResult[]>()),
      activeUsernames: signal(new Set<string>()),
      customEntities: signal<CustomEntity[]>([]),
      isEditMode: signal(false),
      isHomeMenuCollapsed: signal(false),
      isEntityMenuCollapsed: signal(false),
      activeHomeMenuTab: signal<'history' | 'entities'>('history'),
      isPhysicsEnabled: signal(true),
      viewMode: signal<'graph' | 'list'>('graph'),
      expandedGroupDataByUser: signal<{ [username: string]: NetworkNode | null }>({}),
      graphPlatformBatches: signal(new Map<string, GraphPlatformBatch>()),
    };
  }

  addTab() {
    if (this.tabs().length >= this.maxTabsAllowed) {
      return;
    }
    const newTab: Tab = {
      id: self.crypto.randomUUID(),
      name: `Session ${TabManagerService.tabCounter++}`,
      state: this.createNewState(),
    };

    this.tabs.update(tabs => [...tabs, newTab]);
    this.persistAddedTab(newTab);
    this.selectTab(newTab.id);
  }

  selectTab(id: string) {
    this.activeTabId.set(id);
    this.scheduleSave();
  }

  closeTab(id: string) {
    const tabs = this.tabs();
    if (tabs.length <= 1) {
      return;
    }
    const tabIndex = tabs.findIndex(t => t.id === id);
    this.tabs.update(currentTabs => currentTabs.filter(t => t.id !== id));

    if (this.activeTabId() === id) {
      const newActiveTab = tabs[tabIndex - 1] || tabs[tabIndex + 1];
      this.selectTab(newActiveTab.id);
    } else {
      this.scheduleSave();
    }
  }

  startEditing(id: string) {
    this.editingTabId.set(id);
  }

  stopEditing() {
    this.editingTabId.set(null);
  }

  renameTab(id: string, newName: string) {
    const trimmedName = newName.trim();
    if (!trimmedName) {
      this.stopEditing();
      return;
    }
    this.tabs.update(tabs =>
      tabs.map(tab => (tab.id === id ? { ...tab, name: trimmedName } : tab))
    );
    this.stopEditing();
    this.scheduleSave();
  }

  exportActiveTab() {
    const active = this.activeTab();
    if (!active) {
      return;
    }

    const tabDataToExport = {
      name: active.name,
      state: this.serializeTabState(active.state)
    };

    const jsonString = JSON.stringify(tabDataToExport, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    const safeFilename = active.name.replace(/[^a-z0-9]/gi, '_').toLowerCase();
    a.download = `orion-intelligence-session-${safeFilename}.json`;

    document.body.appendChild(a);
    a.click();

    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  exportActiveTabReport(type: GraphReportExportType): void {
    const payload = this.buildSocialReportPayload();
    if (!payload) {
      return;
    }
    this.graphReportExport.exportByType(payload, type);
  }

  importTab(jsonString: string): void {
    if (this.tabs().length >= this.maxTabsAllowed) {
      return;
    }

    try {
      const importedData = JSON.parse(jsonString);

      if (typeof importedData.name !== 'string' || typeof importedData.state !== 'object' || importedData.state === null) {
        return;
      }

      const newTab: Tab = {
        id: self.crypto.randomUUID(),
        name: importedData.name,
        state: this.deserializeTabState(importedData.state),
      };

      this.tabs.update(tabs => [...tabs, newTab]);
      this.persistAddedTab(newTab);
      this.selectTab(newTab.id);

    } catch {
      throw new Error('Invalid session file content.');
    }
  }

  scheduleSave() {
    if (!this.hasLoadedState) {
      return;
    }
    this.hasPendingSave = true;
  }

  private buildSerializableState() {
    return {
      active_tab_id: this.activeTabId(),
      tab_counter: TabManagerService.tabCounter,
      tabs: this.tabs().map(tab => ({
        id: tab.id,
        name: tab.name,
        state: this.serializeTabState(tab.state),
      })),
    };
  }

  private startPeriodicSave() {
    this.autosaveIntervalId = setInterval(() => this.tryPeriodicSave(), 5000);
  }

  private tryPeriodicSave() {
    if (!this.hasLoadedState) {
      return;
    }
    if (!this.hasPendingSave) {
      return;
    }
    const serializableState = this.buildSerializableState();
    const nextSignature = JSON.stringify(serializableState);
    if (nextSignature === this.lastSavedSignature) {
      this.hasPendingSave = false;
      return;
    }
    this.api.post<any>(`social/session/upsert?graph_type=${this.graphType}`, serializableState).subscribe({
      next: () => {
        this.lastSavedSignature = nextSignature;
        this.hasPendingSave = false;
      },
      error: () => {},
    });
  }

  private persistAddedTab(tab: Tab) {
    if (!this.hasLoadedState) {
      return;
    }
    const tabPayload = {
      id: tab.id,
      name: tab.name,
      state: this.serializeTabState(tab.state),
    };
    this.api.post<any>(`social/session/tab/add?graph_type=${this.graphType}`, tabPayload).subscribe({
      next: () => {},
      error: () => {},
    });
  }

  private loadState() {
    this.api.get<any>(`social/session/tabs?graph_type=${this.graphType}`).subscribe({
      next: (savedState) => {
        const savedTabs = Array.isArray(savedState?.tabs) ? savedState.tabs : [];

        if (savedTabs.length === 0) {
          this.hasLoadedState = true;
          this.addTab();
          return;
        }

        const loadedTabs: Tab[] = savedTabs.map((savedTab: any, index: number) => {
          const tabId = typeof savedTab?.id === 'string' && savedTab.id.length > 0 ? savedTab.id : self.crypto.randomUUID();
          const tabName = typeof savedTab?.name === 'string' && savedTab.name.trim().length > 0 ? savedTab.name : `Session ${index + 1}`;
          const tabState = savedTab?.state && typeof savedTab.state === 'object' ? this.deserializeTabState(savedTab.state as SerializableTabState) : this.createNewState();
          return {
            id: tabId,
            name: tabName,
            state: tabState,
          } as Tab;
        });

        this.tabs.set(loadedTabs);
        this.activeTabId.set(loadedTabs[0]?.id || '');
        TabManagerService.tabCounter = loadedTabs.length + 1;
        this.hasLoadedState = true;
        this.hasPendingSave = false;
        this.lastSavedSignature = JSON.stringify(this.buildSerializableState());
      },
      error: () => {
        this.hasLoadedState = true;
        this.hasPendingSave = false;
        this.addTab();
      },
    });
  }

  private serializeTabState(state: TabState): SerializableTabState {
    const plainState: any = {};
    for (const key in state) {
      let value = (state as any)[key]();
      if (value instanceof Map) {
        value = { __type: 'Map', value: Array.from(value.entries()) };
      } else if (value instanceof Set) {
        value = { __type: 'Set', value: Array.from(value.values()) };
      }
      plainState[key] = value;
    }
    return plainState;
  }

  private deserializeTabState(plainState: SerializableTabState): TabState {
    const newState = this.createNewState();
    for (const key in plainState) {
        let value = (plainState as any)[key];
      if (value && value.__type === 'Map') {
        (newState as any)[key].set(new Map(value.value));
      } else if (value && value.__type === 'Set') {
        (newState as any)[key].set(new Set(value.value));
      } else if ((newState as any)[key]) {
        (newState as any)[key].set(value);
      }
    }
    return newState;
  }

  private buildSocialReportPayload(): GraphReportPayload | null {
    const active = this.activeTab();
    if (!active) {
      return null;
    }

    const network = active.state.networkData();
    const nodes = network.nodes.map(node => ({
      id: String(node.id ?? ''),
      label: String(node.label ?? ''),
      type: this.getNodeType(node)
    }));
    const edges = network.edges.map((edge: any) => ({
      id: String(edge.id ?? `${edge.from}->${edge.to}`),
      from: String(edge.from ?? ''),
      to: String(edge.to ?? ''),
      label: edge.label ? String(edge.label) : ''
    }));

    const byType: Record<string, number> = {};
    nodes.forEach(node => {
      byType[node.type] = (byType[node.type] ?? 0) + 1;
    });

    const platforms = Array.from(active.state.scanResults().values()).flat();
    const activeUsers = active.state.activeUsernames().size;
    const tables = platforms.length > 0
      ? [{
          title: 'Scan Snapshot',
          values: {
            platforms: String(platforms.length),
            activeUsers: String(activeUsers),
            customEntities: String(active.state.customEntities().length),
            view: active.state.viewMode()
          }
        }]
      : [];

    return {
      graphKind: 'social',
      title: 'Social Graph Intelligence Report',
      sessionName: active.name,
      generatedAtIso: new Date().toISOString(),
      nodes,
      edges,
      graphImageDataUrl: this.captureSocialGraphSnapshot(),
      summary: {
        totalNodes: nodes.length,
        totalEdges: edges.length,
        groupedNodes: byType['group'] ?? 0,
        customEntities: active.state.customEntities().length,
        scannedPlatforms: platforms.length
      },
      tables
    };
  }

  private captureSocialGraphSnapshot(): string | undefined {
    if (typeof document === 'undefined') {
      return undefined;
    }
    const canvases = document.querySelectorAll('app-network-graph canvas');
    if (canvases.length === 0) {
      return undefined;
    }
    try {
      const base = canvases[0] as HTMLCanvasElement;
      const merged = document.createElement('canvas');
      merged.width = base.width;
      merged.height = base.height;
      const ctx = merged.getContext('2d');
      if (!ctx) {
        return undefined;
      }
      canvases.forEach(node => {
        const canvas = node as HTMLCanvasElement;
        if (canvas.width === merged.width && canvas.height === merged.height) {
          ctx.drawImage(canvas, 0, 0);
        }
      });
      const pad = Math.round(Math.max(merged.width, merged.height) * 0.06);
      const padded = document.createElement('canvas');
      padded.width = merged.width + (pad * 2);
      padded.height = merged.height + (pad * 2);
      const pctx = padded.getContext('2d');
      if (!pctx) {
        return merged.toDataURL('image/jpeg', 0.92);
      }
      pctx.fillStyle = '#0f172a';
      pctx.fillRect(0, 0, padded.width, padded.height);
      pctx.drawImage(merged, pad, pad);
      return padded.toDataURL('image/jpeg', 0.92);
    } catch {
      return undefined;
    }
  }

  private getNodeType(node: NetworkNode): string {
    const nodeId = String(node.id ?? '');
    if ((node.groupedPlatforms?.length ?? 0) > 0) {
      return 'group';
    }
    if (nodeId.startsWith('user-')) {
      return 'user';
    }
    if (nodeId.startsWith('platform-')) {
      return 'platform';
    }
    if (nodeId.startsWith('entity-')) {
      return 'entity';
    }
    if (nodeId.startsWith('relationship-node-')) {
      return 'relationship';
    }
    if (node.shape) {
      const shape = String(node.shape).toLowerCase();
      if (shape === 'icon' || shape === 'circularimage') {
        return 'entity';
      }
      return shape;
    }
    return 'node';
  }
}

import { Injectable, signal, computed, inject } from '@angular/core';
import { TabManagerService } from './tab-manager.service';
import { FetchingStateService } from './fetching-state.service';
import { PlatformResult, ManageProfilesModalData } from '../../../../shared/model/social/social-scan.models';
import { ContextMenuData } from '../network-graph/context-menu/context-menu.component';
import { NotificationData, NotificationType } from '../notification-bar/notification-bar.component';

interface DeleteConfirmationData {
    message: string;
}

interface InfoPopupData {
    type: 'info' | 'warning';
    title: string;
    message: string;
    confirmText: string;
}

export interface RelationshipConnectionItem {
    sourceUser: string;
    sourcePlatform: string;
    sourceUsername: string;
    sourceUrl: string;
    targetUser: string;
    relation: 'follows' | 'followed_by';
}

export interface RelationshipPopupData {
    userA: string;
    userB: string;
    count: number;
    connections: RelationshipConnectionItem[];
}

@Injectable({ providedIn: 'root' })
export class SocialMapperStateService {
    private tabManager = inject(TabManagerService);
    private fetchingState = inject(FetchingStateService);

    isMetadataPopupVisible = signal(false);
    selectedPlatformData = signal<PlatformResult | null>(null);
    summaryPopupData = signal<{ username: string; platforms: PlatformResult[]; email?: string; } | null>(null);
    notification = signal<NotificationData | null>(null);
    private notificationTimeout: any;
    nodeToFocus = signal<string | null>(null);
    contextMenuData = signal<ContextMenuData | null>(null);
    deleteConfirmationData = signal<DeleteConfirmationData | null>(null);
    deleteUsername = signal<string | null>(null);
    infoModalData = signal<InfoPopupData | null>(null);
    manageProfilesModalData = signal<ManageProfilesModalData | null>(null);
    isFollowerScanPopupVisible = signal(false);
    followerScanPopupData = signal<{ platform: PlatformResult } | null>(null);
    relationshipPopupData = signal<RelationshipPopupData | null>(null);

    private activeTabState = computed(() => this.tabManager.activeTab()?.state);
    private jobs = computed(() => this.activeTabState()?.jobs() ?? []);
    private scanResults = computed(() => this.activeTabState()?.scanResults() ?? new Map<string, PlatformResult[]>());
    private networkData = computed(() => this.activeTabState()?.networkData() ?? { nodes: [], edges: [] });

    openManageProfilesModal(username: string) {
        const results = this.scanResults().get(username);
        if (!results) {
            return;
        }
        const centralNodeId = `user-${username}`;
        const nodesOnGraph = new Set<string>();
        this.networkData().edges.forEach(edge => {
            if (edge.from === centralNodeId && !edge.to.toString().startsWith('user-')) {
                nodesOnGraph.add(edge.to.toString());
            }
        });
        this.networkData().nodes.forEach(node => {
            if (node.id.toString().startsWith(`group-${username}-`) && node.groupedPlatforms) {
                node.groupedPlatforms.forEach(p => nodesOnGraph.add(this.fetchingState.getPlatformUniqueKey(p)));
            }
        });
        const platformsWithSelection = results.map(p => ({ ...p, isSelected: nodesOnGraph.has(this.fetchingState.getPlatformUniqueKey(p)) }));
        this.manageProfilesModalData.set({ username, platforms: platformsWithSelection });
    }

    closeManageProfilesModal() { this.manageProfilesModalData.set(null); }

    openDeleteConfirmation(username: string) {
        const job = this.jobs().find(j => j.username === username);
        this.deleteUsername.set(username);
        this.deleteConfirmationData.set({
            message: `Are you sure you want to delete the profile for ${job?.displayName || username}? This will remove all associated data and cannot be undone.`,
        });
        this.closeContextMenu();
    }

    closeDeleteConfirmation() { this.deleteConfirmationData.set(null); this.deleteUsername.set(null); }

    openInfoModal(type: 'info' | 'warning', title: string, message: string, confirmText: string = 'OK') {
        this.infoModalData.set({ type, title, message, confirmText });
    }

    closeInfoModal() { this.infoModalData.set(null); }

    openPlatformNodePopup(nodeId: string) {
        if (!nodeId.startsWith('platform-')) {
            return;
        }
        const key = nodeId.substring('platform-'.length);
        const [keyUsername, platformName, platformUsername] = key.split('|');
        const platformData = this.scanResults().get(keyUsername)?.find(p => p.platform === platformName && p.username === platformUsername);
        if (platformData) {
            this.selectedPlatformData.set(platformData);
            this.isMetadataPopupVisible.set(true);
        }
    }

    closeMetadataPopup() { this.isMetadataPopupVisible.set(false); this.selectedPlatformData.set(null); }
    closeSummaryPopup() { this.summaryPopupData.set(null); }

    openFollowerScanPopup(nodeId: string) {
        if (!nodeId.startsWith('platform-')) {
            return;
        }
        const key = nodeId.substring('platform-'.length);
        const [keyUsername, platformName, platformUsername] = key.split('|');
        const userResults = this.scanResults().get(keyUsername);
        const pData = userResults?.find(p => p.username === platformUsername && p.platform === platformName);
        if (pData) {
          this.followerScanPopupData.set({ platform: pData });
          this.isFollowerScanPopupVisible.set(true);
        }
    }

    closeFollowerScanPopup() { this.followerScanPopupData.set(null); this.isFollowerScanPopupVisible.set(false); }

    openRelationshipPopup(data: RelationshipPopupData) {
        this.relationshipPopupData.set(data);
    }

    closeRelationshipPopup() {
        this.relationshipPopupData.set(null);
    }

    focusOnUser(username: string): void {
        this.nodeToFocus.set(`user-${username}`);
        setTimeout(() => this.nodeToFocus.set(null), 100);
    }

    closeContextMenu() { this.contextMenuData.set(null); }

    onNodeRightClicked({ nodeId, event }: { nodeId: string; event: MouseEvent }, isEditMode: boolean) {
        if (isEditMode) {
            return;
        }
        let type: ContextMenuData['type'] | null = null;
        const customEntities = this.activeTabState()?.customEntities() ?? [];

        if (nodeId.startsWith('user-')) {
            type = 'user';
        } else if (nodeId.startsWith('group-')) {
            type = 'group';
        } else if (customEntities.some(e => e.id === nodeId)) {
            type = 'customEntity';
        }
        else if (nodeId) {
            type = 'platform';
        }
        if (type) {
            this.contextMenuData.set({ x: event.clientX, y: event.clientY, nodeId, type });
        } else {
            this.closeContextMenu();
        }
    }

    showNotification(type: NotificationType) {
        clearTimeout(this.notificationTimeout);
        const notifications: Record<NotificationType, Omit<NotificationData, 'type'>> = {
          added: { message: 'User is already on the graph.', icon: 'bi bi-exclamation-triangle-fill', style: 'bg-yellow-500/90 text-slate-900 border border-yellow-400' },
          scanned: { message: 'A scan for this user already exists.', icon: 'bi bi-info-circle-fill', style: 'bg-blue-500/90 text-white border border-blue-400' },
          scanning: { message: 'A scan for this user is already in progress.', icon: 'bi bi-hourglass-split', style: 'bg-orange-500/90 text-white border border-orange-400' },
          busy: { message: 'An operation is already in progress for this user.', icon: 'bi bi-info-circle-fill', style: 'bg-cyan-500/90 text-white border border-cyan-400' }
        };
        this.notification.set({ type, ...notifications[type] });
        this.notificationTimeout = setTimeout(() => this.notification.set(null), 3000);
    }
}

import { Component, ChangeDetectionStrategy, input, viewChild, ElementRef, effect, signal, OnDestroy, output, computed, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Network, Options, Position } from 'vis-network';
import { DataSet } from 'vis-data';
import { NetworkData, PlatformResult } from '../../../../shared/model/social/social-scan.models';
import { FetchingStateService } from '../services/fetching-state.service';
import { SocialMapperStateService } from '../services/social-mapper-state.service';

@Component({
  selector: 'app-network-graph',
  templateUrl: './network-graph.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: true,
  imports: [CommonModule],
  host: {
    '[class.manipulation-active]': 'isManipulating()',
  }
})
export class NetworkGraphComponent implements OnInit, OnDestroy {
  data = input.required<NetworkData>();
  focusNodeId = input<string | null>(null);
  editMode = input(false);
  physicsEnabled = input(false);
  searchTerm = input<string>('');
  nodesWithFollows = input<Set<string>>(new Set());

  container = viewChild.required<ElementRef>('networkContainer');

  nodeClicked = output<string>();
  platformNodeClicked = output<string>();
  relationshipNodeClicked = output<string>();
  groupClicked = output<{ nodeId: string, position: Position }>();
  followersShortcutClicked = output<string>();
  dragStart = output<void>();
  zoom = output<void>();
  edgeAdded = output<{ from: string, to: string }>();
  edgeDeleted = output<{ edges: string[] }>();

  private fetchingState = inject(FetchingStateService);
  public state = inject(SocialMapperStateService);
  private networkInstance = signal<Network | null>(null);
  private visData = {
    nodes: new DataSet<any>(),
    edges: new DataSet<any>(),
  };

  deleteButtonState = signal({
    visible: false,
    x: 0,
    y: 0,
    edgeId: null as string | null
  });
  private hideButtonTimeout: any;
  isManipulating = signal(false);

  private animationFrameId: number | null = null;
  private animationStartTime: number | null = null;

  iconOverlayNodes = signal<{nodeId: string, x: number, y: number}[]>([]);
  private readonly minZoomScale = 0.35;
  private minZoomLockPosition: Position | null = null;

  private normalizeSearchValue(value: string): string
  {
    return value.trim().toLowerCase().replace(/^@+/, '').replace(/[\s_-]+/g, '');
  }

  loadingNodeIds = computed(() => {
    const loadingIds = new Set<string>();

    const statesToProcess = [
      this.fetchingState.profile(),
      this.fetchingState.posts(),
      this.fetchingState.platformImages(),
      this.fetchingState.followers(),
      this.fetchingState.following(),
    ];

    for (const state of statesToProcess) {
      if (state) {
        for (const key in state) {
          if (state[key]) {
            loadingIds.add(key);
            if (key.startsWith('platform-')) {
              const username = key.substring('platform-'.length).split('|')[0];
              loadingIds.add(`user-${username}`);
            }
          }
        }
      }
    }

    const imageState = this.fetchingState.userImages();
    if (imageState) {
      for (const key in imageState) {
        if (imageState[key]) {
            loadingIds.add(`user-${key}`);
        }
      }
    }

    return loadingIds;
  });

  constructor() {
    effect(() => {
      const networkData = this.data();
      const containerEl = this.container()?.nativeElement;

      if (containerEl && !this.networkInstance()) {
          this.createNetwork(containerEl, this.visData);
      }

      this.updateNetworkData(networkData);
    });

    effect(() => {
      const nodeId = this.focusNodeId();
      const network = this.networkInstance();
      if (nodeId && network) {
        network.focus(nodeId, {
          scale: 1.2,
          animation: {
            duration: 1000,
            easingFunction: 'easeInOutQuad'
          }
        });
      }
    });

    effect(() => {
      const network = this.networkInstance();
      if (!network) {
        return;
      }
      if (this.editMode()) {
        network.addEdgeMode();
      } else {
        network.disableEditMode();
        network.unselectAll();
        this.hideDeleteButton(true);
        this.isManipulating.set(false);
      }
    });

    effect(() => {
      const network = this.networkInstance();
      const enabled = this.physicsEnabled();
      if (network) {
        network.setOptions({ physics: { enabled: enabled } });
      }
    });

    effect(() => {
      const term = this.searchTerm();
      const network = this.networkInstance();
      if (!network || this.visData.nodes.length === 0) {
        return;
      }

      const originalNodes = this.data().nodes;
      const updates: any[] = [];
      const rawTerm = term ?? '';
      const lowerCaseTerm = rawTerm.toLowerCase();
      const normalizedTerm = this.normalizeSearchValue(rawTerm);
      const matchedUserNodeIds = new Set<string>();

      network.unselectAll();

      if (normalizedTerm) {
        for (const candidate of originalNodes) {
          const candidateId = candidate.id.toString();

          if (candidateId.startsWith('platform-')) {
            const rawKey = candidateId.substring('platform-'.length);
            const parts = rawKey.split('|');

            if (parts.length >= 3) {
              const keyUsername = parts[0];
              const platformName = parts[1];
              const platformUsername = parts.slice(2).join('|');
              const normalizedPlatformName = this.normalizeSearchValue(platformName);
              const normalizedPlatformUsername = this.normalizeSearchValue(platformUsername);

              if (normalizedPlatformName.includes(normalizedTerm) || normalizedPlatformUsername.includes(normalizedTerm)) {
                matchedUserNodeIds.add(`user-${keyUsername}`);
              }
            }
          } else if (candidateId.startsWith('group-') && candidate.groupedPlatforms) {
            const groupBody = candidateId.substring('group-'.length);
            const lastDashIndex = groupBody.lastIndexOf('-');
            const keyUsername = lastDashIndex > 0 ? groupBody.substring(0, lastDashIndex) : groupBody;
            const hasGroupedMatch = candidate.groupedPlatforms.some((platform: PlatformResult) => {
              const normalizedPlatformName = this.normalizeSearchValue(platform.platform ?? '');
              const normalizedPlatformUsername = this.normalizeSearchValue(platform.username ?? '');
              return normalizedPlatformName.includes(normalizedTerm) || normalizedPlatformUsername.includes(normalizedTerm);
            });

            if (hasGroupedMatch) {
              matchedUserNodeIds.add(`user-${keyUsername}`);
            }
          }
        }
      }

      if (!lowerCaseTerm.trim()) {
        originalNodes.forEach(originalNode => {
          updates.push({
            id: originalNode.id,
            color: originalNode.color,
            borderWidth: originalNode.borderWidth
          });
        });
      } else {
        this.visData.nodes.forEach((node: any) => {
          const originalNode = originalNodes.find(n => n.id === node.id);
          if (!originalNode) {
            return;
          }

          let isMatch = false;
          const nodeLabel = typeof node.label === 'string' ? node.label : '';
          const nodeTitle = typeof node.title === 'string' ? node.title : '';
          const nodeId = typeof node.id === 'string' ? node.id : '';
          const normalizedLabel = this.normalizeSearchValue(nodeLabel);
          const normalizedTitle = this.normalizeSearchValue(nodeTitle);

          if (nodeLabel.toLowerCase().includes(lowerCaseTerm) || nodeTitle.toLowerCase().includes(lowerCaseTerm)) {
            isMatch = true;
          }

          if (!isMatch && normalizedTerm && (normalizedLabel.includes(normalizedTerm) || normalizedTitle.includes(normalizedTerm))) {
            isMatch = true;
          }

          if (!isMatch && nodeId.startsWith('user-') && normalizedTerm) {
            const profileNameRaw = nodeId.substring('user-'.length);
            const normalizedProfileName = this.normalizeSearchValue(profileNameRaw);
            if (normalizedProfileName.includes(normalizedTerm)) {
              isMatch = true;
            }
          }

          if (!isMatch && nodeId.startsWith('user-') && matchedUserNodeIds.has(nodeId)) {
            isMatch = true;
          }

          if (!isMatch && nodeId.startsWith('user-') && normalizedTerm) {
            const profileNameRaw = nodeId.substring('user-'.length);
            for (const candidate of originalNodes) {
              const candidateId = candidate.id.toString();
              if (!candidateId.startsWith(`platform-${profileNameRaw}|`)) {
                continue;
              }
              const parts = candidateId.split('|');
              const platformUsername = parts.length > 2 ? this.normalizeSearchValue(parts[2]) : '';
              if (platformUsername.includes(normalizedTerm)) {
                isMatch = true;
                break;
              }
            }
          }

          if (!isMatch && nodeId.startsWith('user-') && normalizedTerm) {
            const profileNameRaw = nodeId.substring('user-'.length);
            for (const candidate of originalNodes) {
              const candidateId = candidate.id.toString();
              if (!candidateId.startsWith(`group-${profileNameRaw}-`) || !candidate.groupedPlatforms) {
                continue;
              }
              const hasGroupedMatch = candidate.groupedPlatforms.some((platform: PlatformResult) => {
                const normalizedPlatformUsername = this.normalizeSearchValue(platform.username ?? '');
                const normalizedPlatformName = this.normalizeSearchValue(platform.platform ?? '');
                return normalizedPlatformUsername.includes(normalizedTerm) || normalizedPlatformName.includes(normalizedTerm);
              });
              if (hasGroupedMatch) {
                isMatch = true;
                break;
              }
            }
          }

          if (!isMatch && originalNode.groupedPlatforms) {
            isMatch = originalNode.groupedPlatforms.some((p: PlatformResult) => {
              const platformName = p.platform ? p.platform.toLowerCase() : '';
              const platformUser = p.username ? p.username.toLowerCase() : '';
              const normalizedPlatformName = this.normalizeSearchValue(p.platform ?? '');
              const normalizedPlatformUser = this.normalizeSearchValue(p.username ?? '');
              return platformName.includes(lowerCaseTerm) || platformUser.includes(lowerCaseTerm) || normalizedPlatformName.includes(normalizedTerm) || normalizedPlatformUser.includes(normalizedTerm);
            });
          }

          if (isMatch) {
            updates.push({
              id: node.id,
              color: { ...originalNode.color, border: '#facc15' },
              borderWidth: originalNode.borderWidthSelected || (originalNode.borderWidth || 2) + 2,
            });
          } else {
            updates.push({
              id: node.id,
              color: originalNode.color,
              borderWidth: originalNode.borderWidth
            });
          }
        });
      }

      if (updates.length > 0) {
        this.visData.nodes.update(updates);
      }
    });
  }

  ngOnInit(): void {
    this.startAnimationLoop();
  }

  private startAnimationLoop(): void {
    const animate = (timestamp: number) => {
      if (!this.animationStartTime) {
        this.animationStartTime = timestamp;
      }

      const network = this.networkInstance();
      const loadingIds = this.loadingNodeIds();

      if (network && loadingIds.size > 0) {
        network.redraw();
      } else {
        this.animationStartTime = null;
      }

      this.animationFrameId = requestAnimationFrame(animate);
    };
    this.animationFrameId = requestAnimationFrame(animate);
  }

  private updateNetworkData(networkData: NetworkData) {
    const newNodes = networkData.nodes;
    const newEdges = networkData.edges;

    const currentNodeIds = this.visData.nodes.getIds();
    const newNodeIds = newNodes.map(n => n.id);

    const nodesToAdd = newNodes.filter(n => !currentNodeIds.includes(n.id));
    const nodesToRemove = currentNodeIds.filter(id => !newNodeIds.includes(id));

    if (nodesToRemove.length > 0) {
      this.visData.nodes.remove(nodesToRemove);
    }
    if (nodesToAdd.length > 0) {
      this.visData.nodes.add(nodesToAdd);
    }

    this.visData.nodes.update(newNodes);

    const currentEdgeIds = this.visData.edges.getIds();
    this.visData.edges.remove(currentEdgeIds);
    this.visData.edges.add(newEdges);
  }

  private createNetwork(containerEl: HTMLElement, data: { nodes: DataSet<any>, edges: DataSet<any>}) {
    this.destroyNetwork();

    const fallbackIcon = 'data:image/svg+xml;charset=utf-8,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="%23475569"/></svg>';

    const options: Options = {
      autoResize: true,
      height: '100%',
      width: '100%',
      nodes: {
        brokenImage: fallbackIcon,
        borderWidth: 2,
        shadow: {
          enabled: true,
          color: 'rgba(0,0,0,0.5)',
          size: 10,
          x: 5,
          y: 5
        },
        shapeProperties: {
          useBorderWithImage: true,
        },
        color: {
          highlight: { border: '#c4b5fd', background: '#6d28d9' },
          hover: { border: '#a5b4fc', background: '#5b21b6' }
        }
      },
      edges: {
        width: 1.5,
        smooth: {
          enabled: true,
          type: 'continuous',
          roundness: 0.5
        },
        color: {
            color: 'rgba(75, 85, 99, 0.8)',
            highlight: '#a78bfa',
            hover: '#d1d5db',
        },
        arrows: {
          to: { enabled: false }
        }
      },
      physics: {
        enabled: this.physicsEnabled(),
        forceAtlas2Based: {
          gravitationalConstant: -80,
          centralGravity: 0.005,
          springLength: 150,
          springConstant: 0.08,
          avoidOverlap: 0.7,
          damping: 0.6,
        },
        maxVelocity: 100,
        minVelocity: 0.75,
        solver: 'forceAtlas2Based',
        stabilization: {
          enabled: true,
          iterations: 1000,
          fit: true
        }
      },
      interaction: {
        tooltipDelay: 100,
        hideEdgesOnDrag: false,
        hover: true,
        navigationButtons: false,
        keyboard: true,
        zoomView: true,
        dragView: true
      },
      layout: {
        improvedLayout: true,
      },
      manipulation: {
        enabled: false,
        addEdge: (edgeData: any, callback: (data: any) => void) => {
          if (edgeData.from !== edgeData.to) {
            const fromIsUser = edgeData.from.toString().startsWith('user-');
            const toIsUser = edgeData.to.toString().startsWith('user-');
            if (fromIsUser && toIsUser) {
              callback(null);
              return;
            }
            this.edgeAdded.emit(edgeData);
            callback(edgeData);
          }
        },
        deleteEdge: (edgeData: any, callback: (data: any) => void) => {
          this.edgeDeleted.emit(edgeData);
          callback(edgeData);
        },
      }
    };

    const network = new Network(containerEl, data, options);

    network.on('afterDrawing', (ctx) => {
      const loadingIds = this.loadingNodeIds();
      if (loadingIds.size > 0) {
        const timestamp = performance.now();
        if (!this.animationStartTime) {
          this.animationStartTime = timestamp;
        }
        const elapsedTime = timestamp - this.animationStartTime;

        const positions = network.getPositions([...loadingIds]);

        for (const nodeId of loadingIds) {
            const pos = positions[nodeId];
            if (pos) {
                const boundingBox = network.getBoundingBox(nodeId);
                const radius = (boundingBox.right - boundingBox.left) / 2 + 5;
                const lineWidth = 4;

                const gradient = ctx.createConicGradient(0, pos.x, pos.y);
                gradient.addColorStop(0, 'rgba(34, 211, 238, 0)');
                gradient.addColorStop(0.15, 'rgba(34, 211, 238, 1)');
                gradient.addColorStop(0.6, 'rgba(129, 140, 248, 1)');
                gradient.addColorStop(1, 'rgba(129, 140, 248, 0)');

                ctx.strokeStyle = gradient;
                ctx.lineWidth = lineWidth;
                ctx.lineCap = 'round';

                const baseArcLength = Math.PI * 1.3;
                const pulse = Math.sin(elapsedTime / 450) * 0.5;
                const arcLength = baseArcLength + pulse;

                const rotationSpeed = 0.0025;
                const rotation = (elapsedTime * rotationSpeed);

                ctx.save();

                ctx.translate(pos.x, pos.y);
                ctx.rotate(rotation);
                ctx.translate(-pos.x, -pos.y);

                ctx.beginPath();
                ctx.arc(pos.x, pos.y, radius, 0, arcLength);
                ctx.stroke();

                ctx.restore();
            }
        }
      } else {
        this.animationStartTime = null;
      }

      const nodesToDraw = this.nodesWithFollows();
      if (nodesToDraw.size === 0) {
        if (this.iconOverlayNodes().length > 0) {
            this.iconOverlayNodes.set([]);
        }
        return;
      }

      const overlays: {nodeId: string, x: number, y: number}[] = [];

      for (const nodeId of nodesToDraw) {
        const nodePosition = network.getPosition(nodeId as string);
        if (nodePosition) {
            const boundingBox = network.getBoundingBox(nodeId as string);
            const radius = (boundingBox.right - boundingBox.left) / 2;
            const iconCanvasPos = {
                x: nodePosition.x + radius * 0.707,
                y: nodePosition.y - radius * 0.707,
            };
            const domPosition = network.canvasToDOM(iconCanvasPos);
            overlays.push({ nodeId: nodeId as string, x: domPosition.x, y: domPosition.y });
        }
      }
      this.iconOverlayNodes.set(overlays);
    });

    network.on('click', (properties) => {
      if (this.editMode()) {
        return;
      }

      const { nodes } = properties;
      if (nodes.length > 0) {
        const clickedNodeId = nodes[0] as string;
        if (clickedNodeId.startsWith('user-')) {
          this.nodeClicked.emit(clickedNodeId);
        } else if (clickedNodeId.startsWith('relationship-node-')) {
          this.relationshipNodeClicked.emit(clickedNodeId);
        } else if (!clickedNodeId.startsWith('group-')) {
          this.platformNodeClicked.emit(clickedNodeId);
        }
      }
    });

    network.on('doubleClick', (properties) => {
      if (this.editMode()) {
        return;
      }
      const { nodes, pointer } = properties;
      if (nodes.length > 0) {
        const clickedNodeId = nodes[0] as string;
        if (clickedNodeId.startsWith('group-')) {
          this.groupClicked.emit({ nodeId: clickedNodeId, position: pointer.canvas });
        }
      }
    });

    network.on('hoverEdge', (properties) => {
      if (this.editMode()) {
        this.isManipulating.set(true);
        this.cancelHideDeleteButton();

        const edgeId = properties.edge as string;

        const edgeData = (network as any).body.data.edges.get(edgeId);

        if (edgeData?.from && edgeData?.to) {
          const connectedNodeIds = [edgeData.from, edgeData.to];
          const positions = network.getPositions(connectedNodeIds as string[]);
          const fromNode = positions[edgeData.from];
          const toNode = positions[edgeData.to];

          if (fromNode && toNode) {
            const midX = (fromNode.x + toNode.x) / 2;
            const midY = (fromNode.y + toNode.y) / 2;

            const domPos = network.canvasToDOM({ x: midX, y: midY });

            this.deleteButtonState.set({
              visible: true,
              x: domPos.x,
              y: domPos.y,
              edgeId: edgeId
            });
          }
        }
      }
    });

    network.on('blurEdge', () => {
      if (this.editMode()) {
        this.isManipulating.set(false);
        this.hideDeleteButton();
      }
    });

    network.on('oncontext', (properties) => {
      properties.event.preventDefault();
      const nodeId = network.getNodeAt(properties.pointer.DOM);
      if (nodeId) {
          this.state.onNodeRightClicked({ nodeId: nodeId as string, event: properties.event }, this.editMode());
      }
    });

    network.on('dragStart', () => {
      this.dragStart.emit();
      this.hideDeleteButton(true);
    });

    network.on('zoom', (properties: any) => {
      const currentScale = network.getScale();
      const currentPosition = network.getViewPosition();

      if (currentScale <= this.minZoomScale) {
        const lockPosition = this.minZoomLockPosition ?? currentPosition;
        this.minZoomLockPosition = lockPosition;

        if (properties?.direction === '-') {
          network.moveTo({ scale: this.minZoomScale, position: lockPosition, animation: false });
        } else {
          network.moveTo({ scale: this.minZoomScale, animation: false });
        }
      } else {
        this.minZoomLockPosition = currentPosition;
      }

      this.zoom.emit();
      this.hideDeleteButton(true);
    });

    this.networkInstance.set(network);
  }

  ngOnDestroy(): void {
    this.destroyNetwork();
    if (this.animationFrameId !== null) {
      cancelAnimationFrame(this.animationFrameId);
    }
  }

  private destroyNetwork(): void {
    if (this.networkInstance()) {
      this.networkInstance()?.destroy();
      this.networkInstance.set(null);
    }
    this.visData.nodes.clear();
    this.visData.edges.clear();
  }

  deleteEdge(edgeId: string) {
    this.edgeDeleted.emit({ edges: [edgeId] });
    this.hideDeleteButton(true);
  }

  cancelHideDeleteButton() {
    clearTimeout(this.hideButtonTimeout);
  }

  hideDeleteButton(immediate = false) {
    if (immediate) {
      this.deleteButtonState.set({ visible: false, x: 0, y: 0, edgeId: null });
    } else {
      this.hideButtonTimeout = setTimeout(() => {
        this.deleteButtonState.set({ visible: false, x: 0, y: 0, edgeId: null });
      }, 200);
    }
  }

  onFollowersShortcutClick(event: MouseEvent, nodeId: string) {
    event.stopPropagation();
    this.followersShortcutClicked.emit(nodeId);
  }

  trackByOverlayNodeId(_index: number, item: { nodeId: string }): string {
    return item.nodeId;
  }
}
