  <div class="flex-grow">
    <h3 class="text-2xl font-bold text-slate-100">All Platforms Summary</h3>
    <p class="text-sm text-slate-400">Aggregated information for {{ username() }}</p>
  </div>
</div>

<div class="space-y-3">
  <details class="bg-slate-900/30 rounded-lg border border-slate-700" open>
