                <h4 class="font-semibold text-slate-200 flex-grow">{{ platform.platform }}</h4>
                <div *ngIf="fetchingState.profile()[getPlatformUniqueKey(platform)]" class="animate-spin rounded-full h-4 w-4 border-b-2 border-slate-400" role="status"></div>
              </div>
              <dl *ngIf="platform.profileDetails && getProfileDetailEntries(platform).length > 0; else noDetailData" class="text-sm">
                <div *ngFor="let item of getProfileDetailEntries(platform)" class="py-2 border-b border-slate-700/30 last:border-b-0">
