                  <dd class="text-slate-200 break-words mt-1">{{ item.value }}</dd>
                </div>
              </dl>
              <ng-template #noDetailData>
                <p class="text-center text-sm text-slate-500 py-2">No additional profile data found.</p>
              </ng-template>
            </div>
          </ng-container>
          <ng-template #detailFetchBlock>
            <div class="bg-slate-800/50 rounded-lg p-2 flex items-center justify-between">
              <div class="flex items-center gap-2 min-w-0">
                <div [socialMapperPlatformBg]="platform.platform" class="social-mapper-platform-icon flex-shrink-0 rounded-md flex items-center justify-center text-sm font-bold text-white h-6 w-6 p-1"><app-social-icon [platformName]="platform.platform"></app-social-icon></div>
                <h4 class="font-semibold text-slate-200 truncate">{{ platform.platform }}</h4>
              </div>
              <div *ngIf="fetchingState.profile()[getPlatformUniqueKey(platform)]; else detailFetchBtn" class="flex items-center gap-2 text-slate-400 text-xs shrink-0">
                <div class="animate-spin rounded-full h-4 w-4 border-b-2 border-current" role="status"></div>
                <span>Fetching...</span>
              </div>
              <ng-template #detailFetchBtn>
                <button (click)="fetchProfile.emit(platform)" [disabled]="isScanInProgress()" class="flex items-center shrink-0 justify-center gap-2 px-3 py-1 text-xs font-medium text-white bg-indigo-600/50 rounded-md hover:bg-indigo-600 transition-colors disabled:bg-slate-600 disabled:cursor-not-allowed">
                  <i class="bi bi-person-lines-fill"></i><span>Fetch</span>
                </button>
              </ng-template>
            </div>
          </ng-template>
        </div>
        <p *ngIf="filteredPlatformsForDetails().length === 0" class="text-center text-sm text-slate-500 py-4">No platforms match your filter.</p>
      </div>

      <button *ngIf="displayPlatformsForDetails().length < filteredPlatformsForDetails().length" (click)="loadMoreDetailsPlatforms()" class="w-full text-center mt-2 px-4 py-2 text-sm font-medium text-indigo-400 bg-slate-800/50 rounded-md hover:bg-slate-700 transition-colors">Load More Platforms</button>
    </div>
  </details>

  <details class="bg-slate-900/30 rounded-lg border border-slate-700" open>
    <summary class="flex justify-between items-center p-3 text-sm font-semibold text-slate-300 cursor-pointer social-mapper-list-item-custom">
      <span>Recent Posts</span>
    </summary>
    <div class="p-3 border-t border-slate-700 space-y-4">
      <div class="relative">
        <div class="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3"><i class="bi bi-search w-4 h-4 text-slate-400"></i></div>
        <input type="text" placeholder="Filter platforms..." [value]="postsSearchTerm()" (input)="onPostsSearch($event)" class="block w-full rounded-md border-0 bg-slate-900/50 py-1.5 pl-9 pr-9 text-white shadow-sm ring-1 ring-inset ring-slate-700 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-indigo-500 sm:text-sm sm:leading-6">
        <button *ngIf="postsSearchTerm()" (click)="clearPostsSearch()" class="absolute inset-y-0 right-0 flex items-center pr-3 text-slate-500 hover:text-slate-300 transition-colors"><i class="bi bi-x-circle-fill"></i></button>
      </div>

      <div class="space-y-2">
        <div *ngFor="let platform of displayPlatformsForPosts(); let i = index" class="animate-list-item-in">
          <ng-container *ngIf="platform.posts !== undefined; else postFetchBlock">
            <div class="bg-slate-800/50 rounded-lg p-3">
              <div class="flex items-center gap-2 mb-2 pb-2 border-b border-slate-700/50">
                <div [socialMapperPlatformBg]="platform.platform" class="social-mapper-platform-icon flex-shrink-0 rounded-md flex items-center justify-center text-sm font-bold text-white h-6 w-6 p-1"><app-social-icon [platformName]="platform.platform"></app-social-icon></div>
