                                        <div class="space-y-2 text-sm">
                                          <ng-container *ngIf="getMetadataEntries(platformNode.id.toString()) as metadataEntries">
                                            <div *ngFor="let item of metadataEntries; trackBy: trackByKey">
                                                <div class="flex justify-between items-start gap-4 py-2 border-b border-slate-700/50 last:border-b-0">
