                                                        <p *ngIf="!isImageUrl(item.value) && !isUrl(item.value)" class="break-words">{{ item.value }}</p>
                                                    </div>
                                                </div>
                                            </div>
                                            <p *ngIf="metadataEntries.length === 0" class="text-slate-500 text-center py-2">No additional metadata available.</p>
