                                        </div>

                                        <div *ngIf="getFollowers(platformData).length > 0 || getFollowing(platformData).length > 0" class="mt-4 grid grid-cols-1 md:grid-cols-2 gap-3">
                                          <div class="rounded-lg border border-slate-700 bg-slate-800/40 p-3">
                                            <div class="flex items-center justify-between mb-2">
                                              <p class="text-xs font-semibold uppercase tracking-wide text-indigo-300 mb-0">Followers</p>
                                              <span class="text-xs px-2 py-0.5 rounded-full bg-indigo-500/20 text-indigo-200">{{ getFollowers(platformData).length }}</span>
                                            </div>
                                            <div class="space-y-1.5">
