          <div *ngIf="following().length > 0; else fetchFollowingState" class="h-full flex flex-col">
            <div class="flex-grow overflow-y-auto social-mapper-custom-scrollbar pr-1 space-y-1.5">
              <div *ngFor="let username of displayFollowing(); trackBy: trackByUsername" class="bg-slate-700/40 border border-slate-700 rounded-md transition-colors hover:bg-slate-700">
                <div class="flex items-center gap-2 px-2 py-1.5">
                  <button type="button" (click)="toggleSelection(username)" class="flex-grow min-w-0 flex items-center justify-between rounded-md px-2 py-1.5 text-left transition-colors" [class]="isSelected(username) ? 'bg-indigo-600/30 border border-indigo-500/60 text-indigo-200' : 'border border-transparent text-slate-200'">
                    <span class="font-mono text-sm truncate pr-2">{{ '@' + username }}</span>
                    <i *ngIf="isSelected(username)" class="bi bi-check-circle-fill text-indigo-400"></i>
                  </button>
                  <button type="button" (click)="scanSingle(username)" class="h-8 w-8 flex items-center justify-center rounded-full text-indigo-300 bg-indigo-500/10 hover:bg-indigo-500/20 transition-colors" title="Scan this username"><i class="bi bi-search text-xs leading-none"></i></button>
                  <a [href]="getProfileUrl(username)" target="_blank" rel="noopener noreferrer" class="h-8 w-8 flex items-center justify-center rounded-full text-cyan-300 bg-cyan-500/10 hover:bg-cyan-500/20 transition-colors" title="Open account in new tab"><i class="bi bi-link-45deg text-sm leading-none"></i></a>
