            <button type="button" *ngIf="displayFollowing().length < filteredFollowing().length" (click)="loadMoreFollowing()" [disabled]="isLoadingMoreFollowing()" class="mt-3 w-full rounded-md bg-slate-700 hover:bg-slate-600 disabled:opacity-50 disabled:cursor-not-allowed text-slate-200 py-2 text-sm">{{ isLoadingMoreFollowing() ? 'Loading...' : 'Load More' }}</button>
