      </div>

      <div class="p-3 border-b border-slate-700 space-y-3">
        <div class="relative">
          <div class="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
            <i class="bi bi-search w-5 h-5 text-slate-400"></i>
          </div>
          <input type="text" placeholder="Filter platforms..." [value]="searchTerm()" (input)="onSearchChanged($event)" class="block w-full rounded-md border-0 bg-slate-900/50 py-2 pl-10 pr-10 text-white shadow-sm ring-1 ring-inset ring-slate-700 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-indigo-500 sm:text-sm sm:leading-6" />
          <button *ngIf="searchTerm()" (click)="clearSearch()" type="button" class="absolute inset-y-0 right-0 flex items-center pr-3 text-slate-500 hover:text-slate-300 transition-colors">
            <i class="bi bi-x-circle-fill"></i>
          </button>
        </div>
        <div class="flex items-center justify-between">
