              Select All
            </button>
            <button (click)="deselectAllVisible()" [disabled]="areAllVisibleDeselected()" class="px-2.5 py-1 text-xs font-medium text-slate-300 bg-slate-700 rounded-md hover:bg-slate-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
              Deselect All
            </button>
          </div>
        </div>
      </div>

      <div class="flex-grow p-3 overflow-y-auto min-h-[20rem] social-mapper-custom-scrollbar">
        <ng-container *ngIf="hasMatches(); else noMatches">
