                  <span class="flex-shrink-0 text-xs text-slate-500 px-4 font-semibold uppercase tracking-wider">Suggested Profiles</span>
                  <div class="flex-grow h-px bg-slate-700"></div>
              </div>
              <div class="rounded-lg">
